INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(120073, 'deDE', 'Bitte... Ich habe mich schon seit Wochen nicht nähren können...', '', 25549),
(120072, 'deDE', 'Soundeffekt für Truppen', '', 25549),
(120071, 'deDE', 'Soundeffekt für Truppen', 'Soundeffekt für Truppen', 25549),
(120070, 'deDE', '', 'Soundeffekt für Truppen', 25549),
(120069, 'deDE', '', 'Soundeffekt für Truppen', 25549),
(120068, 'deDE', 'Soundeffekt für Truppen', '', 25549),
(120067, 'deDE', 'Soundeffekt für Truppen', 'Soundeffekt für Truppen', 25549),
(120066, 'deDE', 'Soundeffekt für Truppen', '', 25549),
(120065, 'deDE', 'Soundeffekt für Truppen', '', 25549),
(120064, 'deDE', 'Soundeffekt für Truppen', '', 25549),
(120063, 'deDE', 'Soundeffekt für Truppen', 'Soundeffekt für Truppen', 25549),
(120062, 'deDE', 'Soundeffekt für Truppen', '', 25549),
(120061, 'deDE', 'Niemand darf das Eigentum der Herrin berühren.', 'Niemand darf das Eigentum der Herrin berühren.', 25549),
(120060, 'deDE', 'Soundeffekt für Truppen', '', 25549),
(120059, 'deDE', '', 'Hier drüben!', 25549),
(120058, 'deDE', 'Andere wurden gefangen genommen. Ich habe es gesehen. Sie sind überall!', 'Andere wurden gefangen genommen. Ich habe es gesehen. Sie sind überall!', 25549),
(120057, 'deDE', 'Lauft! So schnell Ihr könnt! Los!', 'Lauft! So schnell Ihr könnt! Los!', 25549),
(120056, 'deDE', 'Ihr seid wirklich $gein beachtlicher:eine beachtliche:c; $C, nicht wahr? Ich danke Euch.', 'Ihr seid wirklich $gein beachtlicher:eine beachtliche:c; $C, nicht wahr? Ich danke Euch.', 25549),
(120055, 'deDE', 'Das Land wird überrannt! Wir müssen sie aufhalten!', 'Das Land wird überrannt! Wir müssen sie aufhalten!', 25549),
(120054, 'deDE', 'Vielen Dank. Wir müssen weiter.', 'Vielen Dank. Wir müssen weiter.', 25549),
(120053, 'deDE', 'Geht weiter.', 'Geht weiter.', 25549),
(120052, 'deDE', 'Ich führe uns zum Herzstück dieses Gefährts. Bleibt in meiner Schutzbarriere, während ich den Pfad vom Makel der Dämonen befreie.', '', 25549),
(120051, 'deDE', 'Ich danke Euch, dass Ihr das Flüstern zum Schweigen gebracht habt. Die endlosen hungrigen Schreie der Leere zu ertragen, ist nun Eure Bürde.', '', 25549),
(120050, 'deDE', 'Hilfe, irgendjemand!', 'Hilfe, irgendjemand!', 25549),
(120049, 'deDE', 'Mich bekommt Ihr niemals lebendig!', 'Mich bekommt Ihr niemals lebendig!', 25549),
(120048, 'deDE', '', 'Ihr müsst einige Augenblicke warten, bevor Ihr wieder einen Kampf aufnehmen könnt, Valarjar.', 25549),
(120046, 'deDE', 'Wenn wir diesen Weg beschreiten, gibt es kein Zurück mehr.', '', 25549),
(120044, 'deDE', 'Ich werde gehorchen. Aber seid Euch darüber im Klaren...', '', 25549),
(120043, 'deDE', 'Wenn wir dies tun... werden wir dafür einen Preis zahlen.', '', 25549),
(120042, 'deDE', 'Tirion Fordring war einer der größten Champions, den diese Welt je gesehen hat!', '', 25549),
(120041, 'deDE', 'Der Tod versteht es, die Gemüter zu besänftigen... Ich bin mir sicher, sie wird der Schwarzen Klinge kompromisslos zu Diensten sein.', '', 25549),
(120040, 'deDE', 'Es gibt nur wenige auf dieser Welt, die mit größerer Überzeugung gelebt haben als Sally Weißsträhne.', '', 25549),
(120038, 'deDE', 'Wie dem auch sei, Euer Wunsch ist mein Befehl. Es wird der Schwarzen Klinge eine Ehre sein, König Thoras in unsere Mitte zu holen.', '', 25549),
(120037, 'deDE', 'Thoras Trollbann war einer der größten Könige, die die Welt je gesehen hat. Das wird der Allianz nicht gefallen.', '', 25549),
(120035, 'deDE', 'Das wird die Horde gegen uns aufbringen, aber Nazgrim wird einen mächtigen Todesritter abgeben.', '', 25549),
(120034, 'deDE', 'Die Vier Reiter... Ich habe meine Bedenken, aber ich werde Eurem Befehl Folge leisten.', '', 25549),
(120033, 'deDE', '', 'Darion!', 25549),
(120032, 'deDE', '', 'Das Licht beschützt diese Kapelle, Darion. Im Licht ist kein Platz für die Dunkelheit!', 25549),
(120031, 'deDE', '', 'Selbst der Lichkönig hatte an diesem Ort keine Macht!', 25549),
(120030, 'deDE', '', 'Ihr Narren. Habt Ihr wirklich geglaubt, das Licht würde so etwas zulassen?', 25549),
(120029, 'deDE', 'Ich habe gerade das letzte Kapitel in unser Buch eingefügt. Ihr solltet es unbedingt lesen.', 'Ich habe gerade das letzte Kapitel in unser Buch eingefügt. Ihr solltet es unbedingt lesen.', 25549),
(120028, 'deDE', 'Vielen Dank, dass Ihr so viele Ressourcen für dieses Projekt abgestellt habt. Ich hoffe, all das, was wir über Eure Waffe erfahren konnten, wird Euch helfen.', 'Vielen Dank, dass Ihr so viele Ressourcen für dieses Projekt abgestellt habt. Ich hoffe, all das, was wir über Eure Waffe erfahren konnten, wird Euch helfen.', 25549),
(120027, 'deDE', 'Es ist vollbracht, $n. Nach wochenlanger Forschung haben wir nun wohl die gesamte Geschichte Eurer Waffe zusammengetragen.', 'Es ist vollbracht, $n. Nach wochenlanger Forschung haben wir nun wohl die gesamte Geschichte Eurer Waffe zusammengetragen.', 25549),
(120026, 'deDE', 'Ich habe noch mehr zu dem Folianten über die Geschichte Eurer Waffe hinzugefügt. Ihr solltet ihn einmal lesen, es lohnt sich.', 'Ich habe noch mehr zu dem Folianten über die Geschichte Eurer Waffe hinzugefügt. Ihr solltet ihn einmal lesen, es lohnt sich.', 25549),
(120025, 'deDE', 'Ich habe noch mehr von der Geschichte Eurer Waffe niedergeschrieben. Wollt Ihr es sehen?', 'Ich habe noch mehr von der Geschichte Eurer Waffe niedergeschrieben. Wollt Ihr es sehen?', 25549),
(120024, 'deDE', 'Eure Waffe blickt auf eine bewegte Vergangenheit zurück. Ich habe den Folianten um einige Übersetzungen erweitert. Interessiert?', 'Eure Waffe blickt auf eine bewegte Vergangenheit zurück. Ich habe den Folianten um einige Übersetzungen erweitert. Interessiert?', 25549),
(120023, 'deDE', 'Ich habe etwas Fantastisches über Eure Waffe erfahren und direkt in dem Folianten verewigt. Ihr solltet es lesen.', 'Ich habe etwas Fantastisches über Eure Waffe erfahren und direkt in dem Folianten verewigt. Ihr solltet es lesen.', 25549),
(120022, 'deDE', 'Ich habe noch etwas von der Geschichte Eurer Waffe in den Folianten übertragen. Ihr solltet ihn Euch einmal ansehen.', 'Ich habe noch etwas von der Geschichte Eurer Waffe in den Folianten übertragen. Ihr solltet ihn Euch einmal ansehen.', 25549),
(120021, 'deDE', 'Ich werde sie erweitern, sobald wir neue Fortschritte in unserer Forschung machen. Ihr solltet Euch alles bei Gelegenheit einmal ansehen.', 'Ich werde sie erweitern, sobald wir neue Fortschritte in unserer Forschung machen. Ihr solltet Euch alles bei Gelegenheit einmal ansehen.', 25549),
(120020, 'deDE', 'Falls Euch die übersetzte Geschichte Eurer Waffe interessiert... Ich habe den Folianten gerade etwas ergänzt.', 'Falls Euch die übersetzte Geschichte Eurer Waffe interessiert... Ich habe den Folianten gerade etwas ergänzt.', 25549),
(120019, 'deDE', 'Diese Forschungen sind faszinierend! Ich habe schon die ersten Teile der übersetzten Geschichte in diesem Folianten niedergeschrieben.', 'Diese Forschungen sind faszinierend! Ich habe schon die ersten Teile der übersetzten Geschichte in diesem Folianten niedergeschrieben.', 25549),
(120018, 'deDE', 'Die Himmelsspalter waren einst ehrenhafte Sturmdrachen, denen der Schutz der Schildruhinsel oblag. Nun sind sie dem Wahnsinn von Helyas dunkler Magie erlegen.', '', 25549),
(120017, 'deDE', 'Auf den Gipfeln der Schildruhinsel findet Ihr die Himmelsspalter. Diese Drachen sind mächtig, uralt und wahnsinnig. Sammelt Eure Verbündeten und schaltet eine dieser Bestien aus.', '', 25549),
(120016, 'deDE', 'Dieser Mondbrunnen wird alles um ihn herum beschützen und nähren. Nun können wir diesen Ort endlich als unsere Heimat bezeichnen.', '', 25549),
(120015, 'deDE', 'Sie braucht viele Ressourcen, verursacht jedoch auch viel Schaden. Zum Glück können Eure Nahkampfangriffe ''Sturmbringer'' auslösen, was die Kosten senkt.', '', 25549),
(120014, 'deDE', '', 'Sie braucht viele Ressourcen, verursacht jedoch auch viel Schaden. Zum Glück können Eure Nahkampfangriffe ''Sturmbringer'' auslösen, was die Kosten senkt.', 25549),
(120013, 'deDE', 'Mit ''Verschwinden'' könnt Ihr Euch aus dem Kampf zurückziehen und entkommen.', '', 25549),
(120012, 'deDE', '', 'Mit ''Verschwinden'' könnt Ihr Euch aus dem Kampf zurückziehen und entkommen.', 25549),
(120011, 'deDE', 'Verschwindet so weit wie möglich von hier! Los!', 'Verschwindet so weit wie möglich von hier! Los!', 25549),
(120010, 'deDE', 'Dieses Gefühl. Ich kann es nicht erklären!', 'Dieses Gefühl. Ich kann es nicht erklären!', 25549),
(120009, 'deDE', 'Wo bin ich? Was ist passiert?', 'Wo bin ich? Was ist passiert?', 25549),
(120008, 'deDE', 'Wer... Wer seid Ihr?', 'Wer... Wer seid Ihr?', 25549),
(120007, 'deDE', 'Was geht hier vor?', 'Was geht hier vor?', 25549),
(120006, 'deDE', 'Dieses Ding... Ich muss hier raus!', 'Dieses Ding... Ich muss hier raus!', 25549),
(120005, 'deDE', 'Was... war das?!', 'Was... war das?!', 25549),
(120004, 'deDE', '', 'Euer Begleiter ist gestorben! Setzt ''Tier wiederbeleben'' ein.', 25549),
(120003, 'deDE', 'Euer Begleiter ist gestorben. Setzt ''Tier wiederbeleben'' ein!', '', 25549),
(120002, 'deDE', '', 'Ich werde Mythandros selbst den Segen bringen. Wir sehen uns dann dort!', 25549),
(120001, 'deDE', 'Nun gut. Ihr seid so lange unser Gast, bis Ihr Eure Angelegenheiten mit dem Kommandanten hier erledigt habt.', '', 25549),
(120000, 'deDE', '', 'Für die Horde!', 25549),
(119999, 'deDE', '', 'Wirkt ''Göttlicher Sturm''!', 25549),
(119998, 'deDE', 'Wirkt ''Göttlicher Sturm''!', '', 25549),
(119997, 'deDE', '', 'Die Fähigkeit ''Göttlicher Sturm'' eignet sich sehr gut für den Kampf gegen mehrere Gegner.', 25549),
(119996, 'deDE', '', 'Bei ihrem Einsatz werden alle Gegner in der Nähe von einem Sturm aus heiliger Energie getroffen.', 25549),
(119995, 'deDE', '', 'Für den Einsatz von ''Göttlicher Sturm'' benötigt Ihr 3 Heilige Kraft.', 25549),
(119994, 'deDE', 'Für den Einsatz von ''Göttlicher Sturm'' benötigt Ihr 3 Heilige Kraft.', '', 25549),
(119993, 'deDE', 'Bei ihrem Einsatz werden alle Gegner in der Nähe von einem Sturm aus heiliger Energie getroffen.', '', 25549),
(119992, 'deDE', 'Die Fähigkeit ''Göttlicher Sturm'' eignet sich sehr gut für den Kampf gegen mehrere Gegner.', '', 25549),
(119991, 'deDE', 'Ich danke Euch, edler Rothuf. Wir akzeptieren Euren Segen und danken Euch.', '', 25549),
(119990, 'deDE', 'Meine Güte, eine seltene Blume.', '', 25549),
(119989, 'deDE', 'Rothuf sieht erwartungsvoll zu Mythandros.', '', 25549),
(119988, 'deDE', 'Der vierte Reiter liegt vor Euch. Befehlt ihm, sich zu erheben.', '', 25549),
(119987, 'deDE', 'Doch Tod ist für die Lebenden, er waltet nicht über die Verdammten.', '', 25549),
(119986, 'deDE', 'Sein Leichnam liegt vor Euch. Voller Narben.', '', 25549),
(119985, 'deDE', 'Darion Mograine hat für die Schwarze Klinge mehr geopfert als alle anderen.', '', 25549),
(119983, 'deDE', 'Eine Hand wäscht die andere! Nehmt Euch einen weiteren Gegenstand aus dem Tresor, $n.', '', 25549),
(119982, 'deDE', 'Marin, ich habe diese Münze gefunden, auf der Euer Name steht.', 'Marin, ich habe diese Münze gefunden, auf der Euer Name steht.', 25549),
(119981, 'deDE', '', 'Dank Eurer Bemühungen haben die Nachtsüchtigen eine Zukunft.', 25549),
(119980, 'deDE', '', 'Ihr könnt den Nachtsüchtigen auf vielerlei Art helfen. Auch Eure Begleiter können sich nützlich machen.', 25549),
(119979, 'deDE', '', 'Ihr zeigt großes Potenzial.', 25549),
(119978, 'deDE', '', 'Es ist Zeit, Euch und Eure Begleiter auf die Probe zu stellen. Seid Ihr der Gunst der Valarjar würdig?', 25549),
(119977, 'deDE', '', 'Ich danke Euch. Wir müssen stets auf der Hut sein.', 25549),
(119976, 'deDE', '', 'Wir müssen das Land beschützen. Ich hoffe, Eure Gefährten sind gut vorbereitet!', 25549),
(119975, 'deDE', 'Der Alptraum verseucht immer noch die Wälder von Val''sharah, aber Ihr und Eure Begleiter habt geholfen, sie zu erhalten.', '', 25549),
(119974, 'deDE', 'Etwas bedroht die Geschöpfe Val''sharahs. Vielleicht könnt Ihr Eure Begleiter dazu anhalten, zu helfen.', '', 25549),
(119973, 'deDE', 'Gut gemacht! Ich spreche im Namen des Hofes und seiner Verbündeten, wenn ich sage: Wir danken Euch, Champion.', '', 25549),
(119972, 'deDE', 'Der Hof und seine Verbündeten brauchen Hilfe. Vielleicht können Eure Freunde helfen.', '', 25549),
(119971, 'deDE', 'Man sagt, es sei streng genommen nicht "legal", auf Turnierspiele zu wetten. Aber was sie nicht wissen, macht sie nicht heiß!', '', 25549),
(119970, 'deDE', 'Oha! Ihr habt einen der reisenden Trainer des Turniers entdeckt! Eine weitere Gelegenheit, Eure Fähigkeiten vorzuführen und mir etwas Gold zu verdienen!', '', 25549),
(119969, 'deDE', 'Erst hat meine Raupe ''ne Panne und dann fliegen mir diese Dinger um die Ohren... Ich werde hier nie was fertigbekommen!', '', 25549),
(119968, 'deDE', 'Ruhig jetzt... ganz ruhig! Lasst noch etwas für die anderen Teilnehmer übrig, ja?', '', 25549),
(119967, 'deDE', 'Für kurze Zeit nimmt eine der legendären Kreaturen Azeroths am Turnier teil. Zeigt, was in Euch steckt, solange Ihr könnt!', '', 25549),
(119966, 'deDE', 'Geht und tut, was getan werden muss.', '', 25549),
(119965, 'deDE', 'Der Körper des großen Tirion Fordring ruht unter der Kapelle.', '', 25549),
(119964, 'deDE', 'Die Schwarze Klinge wird zur Kapelle des Hoffnungsvollen Lichts zurückkehren.', '', 25549),
(119963, 'deDE', 'Ohne Anführer gibt es keine Einigkeit zwischen den Vieren.', '', 25549),
(119962, 'deDE', 'Einer der Vier Reiter muss die Macht haben, sie zu führen.', '', 25549),
(119961, 'deDE', 'Reist zum Scharlachroten Kloster und erweckt die Hochinquisitorin aus ihrem Grab in der Kathedrale.', '', 25549),
(119960, 'deDE', 'Ihre fanatische Willenskraft wird benötigt, um die Bindung der Vier zu stärken.', '', 25549),
(119959, 'deDE', 'Habt Ihr über Lokens letzte Worte an Euch nachgedacht?', 'Habt Ihr über Lokens letzte Worte an Euch nachgedacht?', 25549),
(119958, 'deDE', 'Hochinquisitorin Weißsträhne war eine Priesterin, deren Tragödie eine enge Bindung zum Licht schuf.', '', 25549),
(119957, 'deDE', 'Irgendwas an Euch ist faul, Priester.', '', 25549),
(119956, 'deDE', 'Was gibt es, $C?', '', 25549),
(119955, 'deDE', 'Gut gemacht! Immer weiter so und Ihr werdet noch berühmt werden... und mir dabei einen Haufen Gold einbringen!', '', 25549),
(119954, 'deDE', 'Tretet vor und fordert unseren amtierenden Turnierchampion heraus! Gewinner erhalten fürstliche Preise! Haftungsausschluss: Angaben zur Fürstlichkeit der Preise ohne Gewähr.', '', 25549),
(119952, 'deDE', 'Seine Stärke im Kampf war ohnegleichen und als Untoter wird er noch mächtiger sein.', '', 25549),
(119951, 'deDE', 'Dort findet Ihr das Grab von Thoras Trollbann, dem großen Kriegerkönig.', '', 25549),
(119950, 'deDE', 'Auf den Klippen von Arathor steht das gefallene Reich von Stromgarde.', '', 25549),
(119949, 'deDE', 'Die Zeit des zweiten Reiters ist nun gekommen.', '', 25549),
(119948, 'deDE', 'Nazgrim, der gefallene General der Horde wird der Erstgeborene. Geht nun und vollbringt es.', '', 25549),
(119947, 'deDE', 'Die Zeit der Vier Reiter steht bevor... und Ihr werdet ihre Rückkehr ermöglichen.', '', 25549),
(119946, 'deDE', 'Doch Helden allein werden die Welt nicht retten. Der Preis der Rettung ist zu hoch für die Lebenden.', '', 25549),
(119945, 'deDE', 'Azeroths größte Helden haben sich versammelt, um sich der Brennenden Legion zu stellen.', '', 25549),
(119944, 'deDE', 'Ich danke Euch für Eure Hilfe, $gFremder:Fremde;. Sie bedeutet mir mehr, als Ihr wissen könnt.', '', 25549),
(119943, 'deDE', 'Wir alle verdanken Mythandros und seinen Druidenbegleitern unsere Leben. Dank ihm können wir Suramar als unsere Heimat bezeichnen.', '', 25549),
(119942, 'deDE', '', 'Als wir aufgebrochen sind, waren wir noch mehr. Wäre Mayruna nicht gekommen, wäre ich gestorben.', 25549),
(119941, 'deDE', 'Das Flüstern ruft nach Euch.\n\n<Drak''thul seufzt tief und wirkt einen Moment lang sehr alt und gebrechlich.>\n\nIn meinen Jahren auf dieser Insel habe ich viele Dinge gelernt. Ich habe mich an Orte gewagt, die ich lieber hätte meiden sollen, und Sachen gelernt, die ich gerne vergessen würde.\n\nUnd nun möchte ich alleine sein, bis die Dunkelheit mich endlich überkommt.\n\nHinfort mit Euch.', '', 25549),
(119940, 'deDE', '', 'Der Alptraum ist uns überall hin gefolgt. Wir sind ihm erst entkommen, als wir Suramar erreicht hatten.', 25549),
(119938, 'deDE', 'Ihr seid wieder Ihr selbst. Was ist passiert?', 'Ihr seid wieder Ihr selbst. Was ist passiert?', 25549),
(119937, 'deDE', 'Wir kommen aus einem Dorf außerhalb von Shala''nir. Ich muss sagen, wir sind nur knapp entkommen.', '', 25549),
(119936, 'deDE', '', 'Ich bin während Yseras Angriff auf den Tempel aus Val''sharah geflohen. Ich hatte das Glück, Mythandros auf der Straße zu treffen.', 25549),
(119935, 'deDE', 'Athu''gag magg''naggwa.\n\nQor''naus''agth lwhuk.\n\nLilth gag''huqth''hoq.', '', 25549),
(119934, 'deDE', 'Drak''thul?', 'Drak''thul?', 25549),
(119933, 'deDE', '<Drak''thuls Augen sind verschleiert und scheinen ins Leere zu starren. Sein Kopf ist leicht geneigt, als würde er angestrengt lauschen, doch könnt Ihr nichts hören.>', '', 25549),
(119932, 'deDE', 'Sie kommen nicht, wenn ich sie rufe, Dummkopf.', '', 25549),
(119930, 'deDE', 'Der letzte aus Xe''ras'' Linie – O''ros – weilt ungeschützt im Herzen der Exodar. Zerstören sie O''ros, sind die Informationen im Herzen des Lichts für immer verloren.', '', 25549),
(119929, 'deDE', 'Erzählt mit von dem Flüstern.', 'Erzählt mit von dem Flüstern.', 25549),
(119928, 'deDE', 'Das ist der wahre Grund für die Invasion der Exodar durch die Brennende Legion.', '', 25549),
(119927, 'deDE', 'Doch der einzige Schlüssel zu den Geheimnissen im Herzen des Lichts ist ihre Nachkommenschaft. Deshalb solltet Ihr den Kern zu mir bringen.', '', 25549),
(119926, 'deDE', 'O''ros, Kind des Xe''ra und Herz der Exodar, ist das einzige Wesen im gesamten Kosmos, das die Nachricht im Herzen des Lichts entschlüsseln kann.', '', 25549),
(119925, 'deDE', 'Und doch – nur ein Abkömmling von Xe''ra ist fähig, den Kern zu öffnen. Darum wurdet Ihr geschickt, $p.', '', 25549),
(119924, 'deDE', 'Sicher eingeschlossen in diesem Kern liegt Weisheit... Wissen – unschätzbar in unserem Kampf gegen die Legion.', '', 25549),
(119923, 'deDE', 'Wo habt Ihr das entdeckt? Es ist so viele Jahre her...\n\n<Drak''thul dreht das Relikt in seiner Hand und gibt es Euch dann zurück.>\n\nDie Geister flüstern schon lange nicht mehr. Eine Weile lang waren sie still.\n\nDann begannen sie wieder. Anders, tiefer, düsterer.', '', 25549),
(119922, 'deDE', 'Ich war der Älteste, ich sollte König werden. Nicht dieser Wicht Skovald!', '', 25549),
(119921, 'deDE', 'Erkennt Ihr dieses Relikt?', 'Erkennt Ihr dieses Relikt?', 25549),
(119920, 'deDE', 'Skovald wird für seinen Verrat bezahlen.', '', 25549),
(119919, 'deDE', 'Widerwärtiger Wurm! Ihr seid doch nur der Schoßhund meines Bruders!', '', 25549),
(119918, 'deDE', 'Reizt den Schamanen nicht.', '', 25549),
(119917, 'deDE', 'Auf der Schildruhinsel wurden Sturmheims Könige und seine angesehensten Krieger begraben - in jener Zeit, als die Wellenskorn sich nicht vor der See fürchteten.', '', 25549),
(119916, 'deDE', 'Die Helarjar entweihen die Gräber der Schildruhinsel. Vertreibt sie!', '', 25549),
(119915, 'deDE', 'Die Toten der Schildruhinsel ruhen in Frieden, länger als ich denken kann. Ihr habt meinem Volk heute einen großen Dienst erwiesen.', '', 25549),
(119914, 'deDE', 'Vorsichtiges Schnappen', 'Vorsichtiges Schnappen', 25549),
(119913, 'deDE', 'Knochensprecher stören die Gebeine unserer Könige. Die Toten haben ihre Ruhe verdient. Haltet die Verräter auf.', '', 25549),
(119912, 'deDE', 'Vertreibt die Bleichborken aus meinem Königreich und ich werde Euch Zutritt zum Grab meines Vaters gewähren.', '', 25549),
(119911, 'deDE', '', 'Wir werden für ihre Vernichtung jedes erdenkliche Mittel einsetzen. Verrat und List. Täuschung und Mord. Und ja, wir geben unsere Leben, wenn es dazu kommen muss.', 25549),
(119910, 'deDE', '', 'Ein offener Krieg zwischen der Allianz und der Horde wurde verhindert. Nun können wir uns auf die Brennende Legion konzentrieren.', 25549),
(119909, 'deDE', '', 'Detheroc ist tot und Mathias Shaw ist wieder Anführer des SI:7.', 25549),
(119908, 'deDE', '', 'Lasst uns die Person feiern, die all dies möglich macht, unsere neueste Schattenklinge, $n!', 25549),
(119907, 'deDE', 'Ihr wusstet schon alles, was auf der Schriftrolle stand. Ihr seid so klug!', 'Ihr wusstet schon alles, was auf der Schriftrolle stand. Ihr seid so klug!', 25549),
(119906, 'deDE', 'Ich bin bereit. Nichts wie weg hier, Mathias.', 'Ich bin bereit. Nichts wie weg hier, Mathias.', 25549),
(119905, 'deDE', 'Ich kann Euch nicht genug danken für alles, was Ihr getan habt, $n. Ihr habt mir den SI:7 zurückgegeben und die Allianz und die Horde vor einem Krieg bewahrt, der uns teuer zu stehen gekommen wäre.\n\nDie Brennende Legion hätte uns alle vernichtet.\n\nEs versteht sich von selbst, dass Ihr mir nur sagen müsst, wenn ich etwas für Euch tun kann.\n\nSeid Ihr bereit, nach Dalaran und zur Halle der Schatten zurückzukehren?', '', 25549),
(119904, 'deDE', 'Es ist vorbei. Sprecht mich an, wenn Ihr bereit seid, $n. Ich werde uns sicher aus Sturmwind herausbringen.', '', 25549),
(119903, 'deDE', '', 'Vielleicht, aber nicht so bald, Dämon.', 25549),
(119902, 'deDE', 'Auf den Hochlord und die Silberne Hand!', '', 25549),
(119901, 'deDE', 'Unter der Führung unseres Hochlords haben wir dem Tod mutig ins Auge geblickt... und gesiegt.', '', 25549),
(119900, 'deDE', 'Wir haben gezeigt, wie unerschütterlich unser Wille ist!', '', 25549),
(119899, 'deDE', 'Wir haben die Brennende Legion zurückgeschlagen und unsere Verbündeten beschützt!', '', 25549),
(119898, 'deDE', 'Ritter der Silbernen Hand! Wir haben heute einen großen Sieg errungen!', '', 25549),
(119897, 'deDE', 'Habt Dank, Paladine der Silbernen Hand.', '', 25549),
(119896, 'deDE', '', 'Geschafft. Der Schreckenslord ist tot.', 25549),
(119895, 'deDE', 'Neeeiinnn!', '', 25549),
(119894, 'deDE', 'Ich werde mitansehen, wie Eure Welt zu Asche verbrennt!', '', 25549),
(119893, 'deDE', 'Sterbt im Feuer von tausend Sonnen!', '', 25549),
(119892, 'deDE', 'Nein! Ihr werdet mich NIEMALS besiegen!', '', 25549),
(119891, 'deDE', '', 'Ich danke Euch. Ich werde seine Worte in meinem Herzen behalten.', 25549),
(119890, 'deDE', 'Helden, sammelt Euch im Licht! Balnazzar, bereitet Euch auf Euer Ende vor.', '', 25549),
(119889, 'deDE', 'Auf Befehl des Hohen Exarchen Turalyon sind wir zu Eurer Hilfe geeilt. Ich werde Euch Verstärkung schicken.', '', 25549),
(119888, 'deDE', 'Verbündete, schöpft neuen Mut. Lothraxion, Oberkommandant der Großen Armee des Lichts, ist hier.', '', 25549),
(119887, 'deDE', '', 'Oh, Absolon...', 25549),
(119886, 'deDE', '', 'Noressa überfliegt kurz den Brief.', 25549),
(119885, 'deDE', '', 'Ich war mir so sicher, dass er tot wäre...', 25549),
(119884, 'deDE', 'Wo ist Euer Licht jetzt, Helden?', '', 25549),
(119882, 'deDE', '', 'Es hat keinen Zweck! Die Vision des Propheten hat sich bewahrheitet...', 25549),
(119881, 'deDE', '', 'Es sind zu viele!', 25549),
(119880, 'deDE', 'Weicht nicht zurück! Wir werden nicht kampflos untergehen!', '', 25549),
(119879, 'deDE', 'Kostet nun die WAHRE Macht DER BRENNENDEN LEGION!!!', '', 25549),
(119878, 'deDE', 'Genug! Ich bin diese Spielchen leid.', '', 25549),
(119877, 'deDE', 'Ihr seid allein, Helden. Niemand wird Euch jetzt noch helfen!', '', 25549),
(119876, 'deDE', 'Beeindruckend. Lasst uns sehen, wie Ihr Euch ohne Eure Verbündeten schlagt!', '', 25549),
(119875, 'deDE', 'Was? Der Orden der Silbernen Hand? Einerlei. Ich werde Euch trotzdem vernichten!', '', 25549),
(119874, 'deDE', 'Paladine der Silbernen Hand! Folgt dem Hochlord! Angriff!', '', 25549),
(119872, 'deDE', 'Balnazzar, Eure Arroganz ist grenzenlos. Aber Azeroths Helden werden Euch Widerstand leisten.', '', 25549),
(119871, 'deDE', 'Nun endlich gehört Eure Seele MIR!', '', 25549),
(119870, 'deDE', 'Lange haben wir nach Euch gesucht, Prophet Velen. Ihr dachtet, Ihr könntet Euch hier vor der Legion verstecken.', '', 25549),
(119869, 'deDE', '', 'Ich stimme zu. Eine vereinte Streitmacht könnte für ein Überraschungsmoment sorgen.', 25549),
(119868, 'deDE', 'Eure Allianz und Eure Horde sind dazu bestimmt, sich gegenseitig zu vernichten...', '', 25549),
(119867, 'deDE', 'Hey! Ich habe heute einen ganz besonderen Gegenstand für Euch!', '', 25549),
(119866, 'deDE', 'Genug! Ich brauche mehr Platz.', '', 25549),
(119865, 'deDE', 'Nein, ich bin es. Tötet ihn, $n!', '', 25549),
(119864, 'deDE', 'Ich bin der echte Mathias Shaw.', '', 25549),
(119863, 'deDE', 'Beim Licht, verflucht sei er!', '', 25549),
(119862, 'deDE', 'Was hat das zu bedeuten, $n? Ich dachte, wir stünden alle auf derselben Seite!', '', 25549),
(119861, 'deDE', 'Hier entlang! Wir müssen Rakeesh stoppen und O''ros retten!', '', 25549),
(119860, 'deDE', '', 'Sie sind im Obergeschoss, $n.', 25549),
(119859, 'deDE', 'Was geht da oben vor? Kämpft ja jemand?', '', 25549),
(119858, 'deDE', 'Das sind nicht Eure Feinde, Dummkopf.\n\nJetzt verschwindet.', '', 25549),
(119857, 'deDE', 'Ihr wisst doch sicher viel. Werdet Ihr uns helfen, sie zu bezwingen?', 'Ihr wisst doch sicher viel. Werdet Ihr uns helfen, sie zu bezwingen?', 25549),
(119856, 'deDE', 'He. Haltet Ihr mich für einen närrischen alten Orc, der gebrechlich ist und den Wölfen überlassen werden sollte?\n\nIch habe schon mit Dämonen gesprochen, als Ihr noch in Windeln gelegen habt.', '', 25549),
(119855, 'deDE', 'Die Dämonen übernehmen diese Insel, Ihr solltet vielleicht lieber gehen.', 'Die Dämonen übernehmen diese Insel, Ihr solltet vielleicht lieber gehen.', 25549),
(119854, 'deDE', 'Lasst mich in Frieden.', '', 25549),
(119853, 'deDE', 'Nun gut. Ich kümmere mich selbst um Euch.', '', 25549),
(119852, 'deDE', 'Erhebt Euch. Vernichtet den Eindringling!', '', 25549),
(119851, 'deDE', 'Meine Schöpfungen sind Euer Tod!', '', 25549),
(119850, 'deDE', '|TInterface\\Icons\\inv_misc_trinket6oih_orb4:20|t Ein |cFFFF0000|Hspell:211152|h[Mächtiges Auge von Gul''dan]|h|r fixiert sich auf Euch!', '', 25549),
(119849, 'deDE', 'Diese blutrünstige Bestie. Gute Arbeit.', '', 25549),
(119848, 'deDE', 'Braxas ist ein Legionskommandant, den selbst die anderen Dämonen fürchten. Man sagt, er töte jeden Dämon, der zu schwach ist, um seinen Respekt zu verdienen. Befreit Azeroth von diesem Ungeheuer!', '', 25549),
(119847, 'deDE', 'Wir mussten ihn aufhalten. Gute Arbeit.', '', 25549),
(119846, 'deDE', 'Als unser Volk noch unerfahren und leichtsinnig war, experimentierten wir frei mit arkaner Energie. Galeorn war sehr mächtig, doch durch die unreine Magie hier verfiel er dem Wahnsinn. Legt ihm das Handwerk.', '', 25549),
(119845, 'deDE', 'Eine scheußliche Kreatur. Allein der Gedanke daran lässt mich erschauern.', '', 25549),
(119844, 'deDE', 'Manche Geschöpfe der Natur dürfen nicht am Leben bleiben. Die Uralte Witwe, die sich in der Rabenwehr eingenistet hat, gehört dazu. Tötet sie!', '', 25549),
(119843, 'deDE', 'Gut gemacht. Es bereitet mir keine Freude, doch es war notwendig.', '', 25549),
(119842, 'deDE', 'General Tel''arn... einer der größten Helden während des Kriegs der Ahnen. Er wurde wieder zum Leben erweckt, doch der Kummer über sein Versagen machte ihn wahnsinnig. Gewährt ihm ewige Ruhe.', '', 25549),
(119841, 'deDE', 'Reiter, unser unheiliges Schicksal wartet! Sofort auf nach Acherus.', '', 25549),
(119840, 'deDE', 'Ich werde mir jetzt eine Unterkunft suchen. Ich hoffe, dass wir uns wiedersehen.', '', 25549),
(119839, 'deDE', 'Ihr habt mich gerettet.', '', 25549),
(119838, 'deDE', 'Sie ist fort. Ich dachte, ich würde mich in den Ruinen als hirnlose Hülle zu ihr gesellen, aber Ihr...', '', 25549),
(119837, 'deDE', 'Ich habe die Stadt verlassen, um nach meiner Tochter zu suchen. Sie war eine von denjenigen, die es wagten, Elisande zu kritisieren...', '', 25549),
(119836, 'deDE', 'Wir haben es geschafft! Solcher Macht kann die Legion gewiss nichts entgegensetzen.', '', 25549),
(119835, 'deDE', 'Verdammt, jetzt funktionier doch!', '', 25549),
(119834, 'deDE', '', 'Willkommen in unserer Klinik. Sollen wir Eure Wunden versorgen oder braucht Ihr Vorräte?', 25549),
(119833, 'deDE', '', 'Habt Dank. Hätte man die Mystiker sich selbst überlassen, so hätten diese dunklen Runen noch unzählige weitere Seelen der Valarjar ergriffen.', 25549),
(119832, 'deDE', '', 'Die Mystiker von Haustvald verderben weiterhin die Seelen unserer gefallenen Krieger. Betretet den Ort, in den meine Schwestern und ich uns nicht wagen, und zerstört ihre dunklen Runen.', 25549),
(119831, 'deDE', 'Hochlord, Euer Sattel ist bereit, Euch in den Kampf zu tragen!', 'Hochlord, Euer Sattel ist bereit, Euch in den Kampf zu tragen!', 25549),
(119830, 'deDE', 'Unsere Verstärkung ist im Anmarsch!', '', 25549),
(119829, 'deDE', '', 'Wir werden diese Last tragen, Talwandler. Habt ein wenig Vertrauen.', 25549),
(119828, 'deDE', '[Erleichtertes Seufzen] ...Das Gleichgewicht ist wiederhergestellt. Der Arcan''dor wird nicht versagen.', '', 25549),
(119827, 'deDE', 'Eine reine Lebensessenz... Ich kann nur hoffen, dass das reicht.', '', 25549),
(119826, 'deDE', 'Aus dem Weg! Hier kommt ein zukünftiger Gladiator!', '', 25549),
(119825, 'deDE', 'Ich danke Euch, $gFremder:Fremde;. Die Wut... die Verderbnis ist fort. Jetzt muss ich mich um die Gewässer kümmern, die ich schon so lange vernachlässigt habe.', '', 25549),
(119824, 'deDE', 'Lasst uns immer eine gelassene Haltung einnehmen, wenn wir jemanden getötet haben.', '', 25549),
(119823, 'deDE', 'Ich trage schon eine Flagge! Gewinnen wir?', '', 25549),
(119822, 'deDE', 'Denkt daran, kämpft immer auf den Straßen. Ziele sind für Narren.', '', 25549),
(119821, 'deDE', 'In Ordnung, tötet alle in Kleidern.', '', 25549),
(119820, 'deDE', 'Und jetzt Eure Siegespose!', '', 25549),
(119819, 'deDE', 'Keine Sorge, Boss. Ich schicke ein paar Blümchen.', '', 25549),
(119818, 'deDE', '', 'Azeroth musste noch nie der geballten Macht der Brennenden Legion trotzen, aber mit Mut und Ausdauer wird die Schwarze Klinge obsiegen.', 25549),
(119817, 'deDE', 'Autsch, das sah schmerzhaft aus.', '', 25549),
(119816, 'deDE', '', 'Jetzt, da wir unsere Anführerin zurückhaben, können die Vergessenen Schatten sich wieder erheben.', 25549),
(119815, 'deDE', '', 'Wir werden den Ungläubigen keine Chance lassen, ihr Ziel zu erreichen.\n\nDer Geist unserer Anführerin mag in der Leere verloren sein, doch wir werden ihren Körper schützen, bis ihr Geist zurückgebracht werden kann.', 25549),
(119814, 'deDE', 'Bumm! Absolut kalt erwischt!', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(119813, 'deDE', 'Wohin Ihr geht? Nirgendwohin!', '', 25549),
(119812, 'deDE', '', 'Es könnte einen Moment dauern, bis Eure Sicht sich an die neue Positionierung Eurer Augen gewöhnt hat. Es wäre zu empfehlen, einen Ast in der Nähe zu haben.', 25549),
(119811, 'deDE', '', 'Wenn Ihr Eure Flügel ausbreitet, stellt sie in den Wind, um in die Luft aufzusteigen.', 25549),
(119810, 'deDE', '', 'Seid gewarnt: Ihr werdet ein STARKES Verlangen haben, Würmer zu fressen. Das kann ich nicht klar genug sagen: Esst keine Würmer, Ihr würdet es bereuen.', 25549),
(119809, 'deDE', '', 'Mit Eurem Schnabel kann man nicht nur quatschen, putzt und pflegt Euch, sonst krabbelt bald Ungeziefer auf Euch herum!', 25549),
(119808, 'deDE', '', 'Andere Vögel fühlen sich möglicherweise zu Eurer neuen Gestalt hingezogen. Passt auf... romantisches Verhalten auf.', 25549),
(119807, 'deDE', '', 'Nutzt Eure Schwanzfedern, um zu lenken. Möglicherweise seid Ihr nicht gewohnt, diesen Muskel zu benutzen. Übt ein wenig, bevor Ihr noch einen Baum trefft!', 25549),
(119806, 'deDE', '', 'Sucht beim Gleiten nach Warmluftströmungen, die Euch in der Luft halten. Diese Sinne werden neu für Euch sein, doch mit der Zeit werdet Ihr Euch daran gewöhnen.', 25549),
(119805, 'deDE', 'Auf Euer Geheiß stellen wir uns zum letzten Gefecht! Sagt mir, wenn Ihr bereit seid.', '', 25549),
(119804, 'deDE', 'Ah, die freie Natur!', 'Ah, die freie Natur!', 25549),
(119803, 'deDE', 'Ich frage mich, ob ich dann auch Würmer essen will...', 'Ich frage mich, ob ich dann auch Würmer essen will...', 25549),
(119802, 'deDE', 'Das ist das Gruseligste, was wir je tun mussten!', 'Das ist das Gruseligste, was wir je tun mussten!', 25549),
(119801, 'deDE', 'Ich verstehe das nicht so ganz...', 'Ich verstehe das nicht so ganz...', 25549),
(119800, 'deDE', 'Ich kann es kaum erwarten, zwischen den Wolken zu gleiten.', 'Ich kann es kaum erwarten, zwischen den Wolken zu gleiten.', 25549),
(119799, 'deDE', 'Ich bin ziemlich nervös. Was, wenn ich falle?', 'Ich bin ziemlich nervös. Was, wenn ich falle?', 25549),
(119798, 'deDE', '|TInterface\\Icons\\Spell_Shadow_SoulGem:20|t Ein |cFFFF0000|Hspell:209489|h[Auge von Gul''dan]|h|r fixiert sich auf Euch!', '', 25549),
(119797, 'deDE', 'Arkane Essenz wird gescannt...', '', 25549),
(119796, 'deDE', 'Identifikation bitte. GEHORCHT.', '', 25549),
(119795, 'deDE', 'Verdächtige Person entdeckt.', '', 25549),
(119794, 'deDE', 'Überprüfung erfolgt umgehend.', '', 25549),
(119793, 'deDE', 'HALT. Kontrolle.', '', 25549),
(119792, 'deDE', 'Was wir heute hier getan haben... Ich kann nur hoffen, dass es das Richtige war. Ich danke Euch, Freunde.', '', 25549),
(119791, 'deDE', 'Verzeiht mir... Wir waren zu schwach...', '', 25549),
(119790, 'deDE', 'Oh, nein! Ursocs Geist wurde schon wieder gefangen? Schnell Freunde, ich werde so gut es geht helfen.', '', 25549),
(119789, 'deDE', 'Danke. Meine Zwiesprache mit der Natur hat mich an diesen Ort zurückgebracht. In diesem Gebiet stinkt irgendetwas zum Himmel und wir müssen es ausmerzen.', '', 25549),
(119788, 'deDE', 'Ihr da! Helft mir bitte und hört Euch an, was ich zu sagen habe!', '', 25549),
(119787, 'deDE', 'Ihr habt es geschafft! Ich habe ein Portal für Eure Rückkehr geöffnet. Beeilt Euch! Ich kann es nur für kurze Zeit aufrechterhalten.', '', 25549),
(119786, 'deDE', 'Wir müssen uns aufteilen und hineinschleichen. Bleibt in Bewegung. Bei Schwierigkeiten, verwendet die Heuballen.', '', 25549),
(119785, 'deDE', '', 'Wir sehen uns beim SI:7. Viel Glück, $n.', 25549),
(119784, 'deDE', '', 'Möge das Licht mich leiten.', 25549),
(119783, 'deDE', '', 'Ich kämpfe in Elunes Namen!', 25549),
(119782, 'deDE', '', 'Wir kämpfen gemeinsam!', 25549),
(119781, 'deDE', '', 'Sucht tief in Euch nach Stärke.', 25549),
(119780, 'deDE', '', 'Das Licht leitet mein Schwert!', 25549),
(119779, 'deDE', '', 'Vermutlich kommen wir nicht zurück. Detheroc erwartet uns sicher schon. Sagt Bescheid, wenn Ihr bereit seid.', 25549),
(119778, 'deDE', 'Ich bin so weit, wenn Ihr es seid, $p.', '', 25549),
(119777, 'deDE', '', 'Wählt mit Bedacht. Das Schicksal der Verheerten Inseln ruht in Euren Händen.', 25549),
(119776, 'deDE', 'Nein, Mutter. Ich bin Euer KÖNIG!', '', 25549),
(119775, 'deDE', '', 'Ihr... seid nicht länger... mein Sohn...', 25549),
(119774, 'deDE', 'Kehrt zurück, wenn Ihr bereit seid, Euch dem Alptraum zu stellen. Bis dahin planen wir unsere nächsten Schritte.', '', 25549),
(119773, 'deDE', '', 'Ihr mögt Euren Vater ermordet haben. Ihr mögt Eure Brüder ermordet haben. Aber das gibt Euch NICHT das Recht, unser Volk zu regieren!', 25549),
(119772, 'deDE', '', 'Dummer Junge. Glaubt Ihr, Eure Teufelstricks werden Euch vor meinem Zorn bewahren?', 25549),
(119771, 'deDE', '', 'Skovald wird fallen!', 25549),
(119770, 'deDE', '', 'Für die Königin!', 25549),
(119769, 'deDE', '', 'Euer falscher Gottkönig kann Euch jetzt auch nicht retten!', 25549),
(119768, 'deDE', '', 'Sterbt, Anhänger des falschen Königs!', 25549),
(119767, 'deDE', '', 'Verräter!', 25549),
(119766, 'deDE', 'Und so erhob sich Gottkönig Skovald, besudelt mit dem Blut seiner eigenen Familie.', '', 25549),
(119765, 'deDE', 'Und nun die Geschichte, die erzählt, wie Skovald König wurde. Erfahrt, wie er jene verriet, die ihm Leben schenkte.', '', 25549),
(119764, 'deDE', 'Su''esh rennt hinüber, um etwas zu trinken.', 'Su''esh rennt hinüber, um etwas zu trinken.', 25549),
(119763, 'deDE', 'Zu Spät! Ich bin unaufhaltbar!', '', 25549),
(119762, 'deDE', 'Ist das alles, was Ihr zu bieten habt?', '', 25549),
(119761, 'deDE', 'Er... übernimmt diesen Titanen... trotz allem...', '', 25549),
(119760, 'deDE', 'Wie... ist das... möglich?', '', 25549),
(119759, 'deDE', 'Und so fallt Ihr!', '', 25549),
(119758, 'deDE', 'Das war zu leicht!', '', 25549),
(119757, 'deDE', 'Bezeugt das unweigerliche Ende von allem, wofür Ihr gekämpft habt!', '', 25549),
(119756, 'deDE', 'Spürt die Flammen von Azzinoth!', '', 25549),
(119755, 'deDE', 'Spürt die Macht... des inneren Dämons!', '', 25549),
(119754, 'deDE', 'Werdet zu einem Gefäß der Dunkelheit!', '', 25549),
(119753, 'deDE', 'Ihr wisst nicht, was Euch erwartet!', '', 25549),
(119752, 'deDE', 'Seht den Schatten der drohenden Zukunft – der endlosen Finsternis, die Eure Welt verschlingen wird.', '', 25549),
(119751, 'deDE', 'Ihr schlagt einen Bauern und denkt, Ihr könnt es mit dem König aufnehmen? Diese Arroganz!', '', 25549),
(119750, 'deDE', 'Zeit, die Seele des Dämonenjägers seinem Körper zurückzugeben... und der Legion einen Wirt zu nehmen!', '', 25549),
(119749, 'deDE', 'Ich bin Gul''dan! Die Inkarnation der Dunkelheit! So... kann es nicht enden.', '', 25549),
(119748, 'deDE', '', 'Ich bin bereit zu gehen und nie mehr zurückzuschauen.', 25549),
(119747, 'deDE', 'Was danach kommt, bleibt im Dunkeln. Lasst uns einfach darauf vertrauen, dass uns das Licht erhört.', '', 25549),
(119746, 'deDE', '', 'Der Netherlichttempel ist in Gefahr. Ritter der Silbernen Hand, zusammen können wir gegen Balnazzar bestehen.', 25549),
(119745, 'deDE', 'Balnazzar wird keinen so heftigen Widerstand erwarten. Es könnte unsere Gelegenheit sein, ihn ein für alle Mal zu erledigen.', '', 25549),
(119744, 'deDE', 'Ihr würdet einem Fremden vertrauen? Noch dazu einem, der zunächst selbst ein Schreckenslord zu sein schien?', '', 25549),
(119742, 'deDE', '', 'Was ist, wenn dieser Fremde nicht kommt? Können wir seinem Wort vertrauen?', 25549),
(119741, 'deDE', '', 'Es ist ein Risiko, aber dennoch wird der Tempel verwundbar sein. Wir sollten zusammenhalten.', 25549),
(119740, 'deDE', 'Wie lautet Eure Botschaft, Priesterin?', 'Wie lautet Eure Botschaft, Priesterin?', 25549),
(119739, 'deDE', 'Es ist meine Pflicht, hierzubleiben und dafür zu sorgen, dass die Legion nicht durch die Tore kommt.', '', 25549),
(119738, 'deDE', 'Ich würde gern die Brauherausforderung noch einmal versuchen.', 'Ich würde gern die Brauherausforderung noch einmal versuchen.', 25549),
(119737, 'deDE', 'Erzmagier Vargoth, was ist die Quelle Eurer Macht?', 'Erzmagier Vargoth, was ist die Quelle Eurer Macht?', 25549),
(119736, 'deDE', 'Gezeitenrufer, beschützt mich!', '', 25549),
(119735, 'deDE', 'Schuppenwache, lasst sie zu Eis erstarren!', '', 25549),
(119734, 'deDE', 'Ich glaube zu wissen, wie ich Euch helfen kann, Magus.', '', 25549),
(119733, 'deDE', 'Ich glaube zu wissen, wie ich Euch helfen kann, kleines Wesen.', '', 25549),
(119732, 'deDE', 'Su''esh beginnt, nervös zum sich zu schlagen. Kehrt um, bevor sie Euch abwirft!', 'Su''esh beginnt, nervös zum sich zu schlagen. Kehrt um, bevor sie Euch abwirft!', 25549),
(119731, 'deDE', 'Endlich frei! Ich bin schon zu lange ein Gefangener ihres Glaubens gewesen.', 'Endlich frei! Ich bin schon zu lange eine Gefangene ihres Glaubens gewesen.', 25549),
(119730, 'deDE', 'Ihr habt mir eine zweite Chance gewährt. Ich werde sie nicht verschwenden.', 'Ihr habt mir eine zweite Chance gewährt. Ich werde sie nicht verschwenden.', 25549),
(119729, 'deDE', 'Ich danke Euch, $n. Ich werde Eure Güte nicht vergessen.', 'Ich danke Euch, $n. Ich werde Eure Güte nicht vergessen.', 25549),
(119728, 'deDE', 'Ihr habt mir mehr Gnade gezeigt, als ich verdient habe.', 'Ihr habt mir mehr Gnade gezeigt, als ich verdient habe.', 25549),
(119727, 'deDE', 'Su''esh brüllt $n glücklich an.', '', 25549),
(119726, 'deDE', 'Seid vorsichtig da draußen!', 'Seid vorsichtig da draußen!', 25549),
(119725, 'deDE', 'Hey! Ich war noch nicht fertig.', 'Hey! Ich war noch nicht fertig.', 25549),
(119724, 'deDE', 'Bitte an einem Stück wieder zurückbringen!', 'Bitte an einem Stück wieder zurückbringen!', 25549),
(119723, 'deDE', 'Vorsichtig mit dem Ding!', 'Vorsichtig mit dem Ding!', 25549),
(119722, 'deDE', 'Ihr habt recht, aber wie sollen wir dieses Ding gefahrlos anzapfen? Unsere Macht wird höchstens...\n\n<Tyrosus hält inne.>\n\nDie Schwarze Klinge.', '', 25549),
(119721, 'deDE', 'Es gibt kein Licht ohne Schatten. Wir müssen die perfekte Balance anstreben.', 'Es gibt kein Licht ohne Schatten. Wir müssen die perfekte Balance anstreben.', 25549),
(119720, 'deDE', 'Ich verstehe.\n\nIch vertraue auf Eure Weisheit, Hochlord. Aber ich kann nicht sagen, dass mich dieser Plan gerade begeistert. \n\nWie können wir jemals sicher sein, dass die Macht in diesem Ding Euch nicht... verändert?', '', 25549),
(119719, 'deDE', 'Ich habe einen dunklen und sehr mächtigen Kristall gefunden, Maxwell.\n\nWenn es uns gelingt, seine Macht zu nutzen, könnte er sich als wirkungsvolle Waffe gegen die Legion erweisen.', 'Ich habe einen dunklen und sehr mächtigen Kristall gefunden, Maxwell. Wenn es uns gelingt, seine Macht zu nutzen, könnte er sich als wirkungsvolle Waffe gegen die Legion erweisen.', 25549),
(119718, 'deDE', 'Spürt Ihr es auch, Hochlord? Irgendetwas stimmt nicht.', '', 25549),
(119717, 'deDE', 'Ich fühle eine dunkle Präsenz in der Nähe...', '', 25549),
(119716, 'deDE', 'Gar nicht schlecht... Aber grüne Augen? Ich hatte graue.', '', 25549),
(119715, 'deDE', 'Nein. Niedere Kaste. Nicht gut genug.', '', 25549),
(119714, 'deDE', 'Wisst Ihr, ich vermisse es irgendwie, Fleisch auf den Knochen zu haben. Vielleicht ließe sich da etwas machen?', '', 25549),
(119713, 'deDE', 'Bevor ich langsam verzehrt wurde, tat ich zwei Dinge.\n\nAls Erstes, was offensichtlich sein sollte, stellte ich meine nekromantischen Erkenntnisse auf die Probe und versiegelte meine Seele in dem Phylakterium, das Ihr gefunden habt. Das hat den Schmerz meines Todes zwar nicht einen Deut gelindert... aber es erfüllte seinen Zweck.\n\nDanach, als die Kreatur mich schon zur Hälfte verschlungen hatte, schleuderte ich den Kristall in den Fluss zu Eurer Seite in der Hoffnung, dass jemand ihn immer noch gegen die Streitkräfte der Dunkelheit einsetzen könnte.\n\n<Des Gesicht des Lichs verzieht sich zu so etwas wie einem Lächeln.>\n\nWenn Ihr ihn sucht, dann werdet Ihr ihn dort finden.', '', 25549),
(119712, 'deDE', 'Was ist mit dem Kristall geschehen?', 'Was ist mit dem Kristall geschehen?', 25549),
(119711, 'deDE', 'Ich fand einen Weg, die Geißel mit ihrer eigenen Magie zu bekämpfen. Es war eigentlich ganz einfach. Nach dem Amoklauf des Lichkönigs hatte ich ein ganzes Meer von Seelen zu meiner Verfügung.\n\nLetztendlich erschuf ich ein Gegenstück zu dem heiligen Relikt, das dem Aschenbringer seine Stärke verleiht. Aber bevor ich es in einer passenden Klinge versiegeln konnte, kamen Isillien und seine Hunde mir auf die Schliche.\n\nDer Rest war, wie sie es immer so schön ausdrücken, die reinste Qual.', '', 25549),
(119710, 'deDE', 'Alle Leitungen sind aktiviert. Könnt Ihr den Durchfluss verstärken?', 'Alle Leitungen sind aktiviert. Könnt Ihr den Durchfluss verstärken?', 25549),
(119709, 'deDE', 'Und das war?', 'Und das war?', 25549),
(119708, 'deDE', '<Nehmt das Buch.>', '<Nehmt das Buch.>', 25549),
(119707, 'deDE', 'Ich schätze, Ihr wisst es. Ansonsten würden wir uns wohl kaum treffen.\n\nMeine Geschichte ist schnell erzählt. Der ursprüngliche Besitzer Eurer Klinge war den endlosen Horden der Untoten nicht gewachsen, die unsere Welt bedrohten.\n\nAlso suchte ich nach einer anderen Lösung... einer unfehlbaren.', '', 25549),
(119706, 'deDE', 'Seid Ihr verrückt? Etwas weniger Schönes kann ich mir kaum vorstellen, höchstens, mir jedes einzelne meiner prächtigen Barthaare auszureißen.', '', 25549),
(119705, 'deDE', 'Was ist denn mit Euch passiert?', 'Was ist denn mit Euch passiert?', 25549),
(119704, 'deDE', 'Hier erwartet Euch kein Gefecht, Paladin. Ich kann Euch nichts anhaben und habe gegenüber den dunklen Kreaturen, die Ihr vernichten wollt, keinerlei Verpflichtungen.', '', 25549),
(119703, 'deDE', 'Ah, der Aschenbringer lebt noch. Seltsam.', '', 25549),
(119702, 'deDE', 'Geht. Ich lasse mich nicht bevormunden.', '', 25549),
(119701, 'deDE', 'Was habt Ihr dann getan?', 'Was habt Ihr dann getan?', 25549),
(119700, 'deDE', 'Wie furchtbar.', 'Wie furchtbar.', 25549),
(119699, 'deDE', 'Was habt Ihr aufgeschrieben?', 'Was habt Ihr aufgeschrieben?', 25549),
(119698, 'deDE', 'Ich würde ihnen nicht glauben?', 'Ich würde ihnen nicht glauben?', 25549),
(119697, 'deDE', 'Das ist schön.', 'Das ist schön.', 25549),
(119696, 'deDE', 'Was habt Ihr getan?', 'Was habt Ihr getan?', 25549),
(119695, 'deDE', 'Pah, keinerlei Respekt vor dem Alter.', '', 25549),
(119694, 'deDE', 'Einverstanden, $n.', '', 25549),
(119693, 'deDE', 'Ich habe dieses Exemplar zurückgekauft, aber der Rest ist schon lange verschwunden. Hat mich auch ganz schön was gekostet. Alles habe ich abgesucht, aber über den Rest gibt es nur Gerüchte. Langsam werden all die Abenteuer zu viel für meine alten Knochen.', '', 25549),
(119692, 'deDE', 'Ich hatte die Geschichte dieses Ordens aufgeschrieben. Aber dieser elende Lehrling hat alles verloren! Alles! Er hat sie für ein paar Kupferstücke pro Seite verkauft. Unfassbar!', '', 25549),
(119691, 'deDE', 'Ich habe die ganze Welt nach Informationen durchkämmt und alles aufgeschrieben! Selbst unwichtige Kleinigkeiten. Ich habe Dinge gesehen, die Ihr niemals glauben würdet, $gJunge:Mädchen;. Im Leben nicht!', '', 25549),
(119690, 'deDE', 'Die Jugend von heute... hat kein Sinn für die Archivierung. Als Lehrling war ich da ganz anders!', '', 25549),
(119689, 'deDE', 'Ich kann es mir nicht leisten, seiner jämmerlichen Existenz hier ein Ende zu setzen. Wenn ihn hier jemand fände, würde das mein glorreiches Werk nur erschweren.\n\nNein... Ich habe eine bessere Idee. Ich werde ihn bis zur Schwelle des Todes führen und dann in den Pestländern zurücklassen.\n\nAm Flussufer gibt es einen besonders widerwärtigen Schleim, der von der verräterischen Laus absolut nichts übrig lassen wird... Ich muss diese elende Kreatur nur finden.', '', 25549),
(119688, 'deDE', '<Blättert um.>', '<Blättert um.>', 25549),
(119687, 'deDE', 'Sieg den Valarjar! Sieg $gdem Schlachtenfürsten:der Schlachtenfürstin;!', '', 25549),
(119686, 'deDE', '<Einer der Abschnitte ist etwas abgenutzter als der Rest.>\n\n...der elende Zauberer ist zäher, als ich erwartet hatte.\n\nAber dennoch, ihm den Zorn des Lichts zu demonstrieren, hat mich in den letzten Wochen wirklich mit Genugtuung erfüllt. Der Ketzer hätte wirklich Schlimmeres verdient. Wer ist denn so töricht, etwas dermaßen Abartiges aus denselben Schatten zu konstruieren, deren Vernichtung wir geschworen haben?!\n\nIch wusste doch, dass man seinesgleichen nicht trauen kann.', '', 25549),
(119685, 'deDE', 'Lasst es alle wissen! Dank $gdes neuen Schlachtenfürsten:der neuen Schlachtenfürstin; der Valarjar haben wir unseren ersten wichtigen Sieg gegen die Legion errungen, auf einer ihrer eigenen Welten.', '', 25549),
(119684, 'deDE', 'Thorim... mein Sohn! Haltet sie auf! Ich entsende meine Champions, damit sie Euch helfen.', '', 25549),
(119683, 'deDE', '', 'Ich fürchte, das weiß ich nicht.\n\nNur die Kreuzfahrer, die ihn getötet haben, kennen die ganze Wahrheit, und von denen lebt keiner mehr.\n\nIhr solltet in ihren alten Festungen nach Hinweisen suchen.', 25549),
(119682, 'deDE', 'Ich weiß es nicht.\n\nAngeblich kennen nur die Kreuzfahrer die Wahrheit, aber die sind alle so gut wie ausgerottet.\n\nVielleicht findet Ihr die Antwort in einer ihrer alten Festungen.', '', 25549),
(119681, 'deDE', 'Die Hallen von Ulduar wurden von den Armeen der Legion überrannt. Wir kämpfen tapfer, aber ihre Zahl scheint endlos.', '', 25549),
(119680, 'deDE', 'Vater! Wir haben einen Eid geschworen, dem Ruf des Gjallarhorns zu folgen, doch wir vermögen es nicht.', '', 25549),
(119679, 'deDE', 'Armeen von Ulduar, hört Odyns Ruf!', '', 25549),
(119678, 'deDE', 'Wisst Ihr noch mehr darüber, was dieser Zauberer erschaffen hat, um solch ein Schicksal zu verdienen?', 'Wisst Ihr noch mehr darüber, was dieser Zauberer erschaffen hat, um solch ein Schicksal zu verdienen?', 25549),
(119677, 'deDE', 'Es war eine Zwergin, wenn ich mich nicht irre... und ich irre mich selten.\n\nSie kam mit einer Ausgabe genau dieses Buchs hierher, genau wie Ihr heute, aber sie hatte keinen Beweis für den Tod des schwarzen Drachen, also schwieg ich wie ein Grab. Sie war sehr begierig, zu erfahren, wo der Aschenbringer zu finden sei.\n\nWenn Ihr sie findet, kann sie Euch vielleicht weitere Erleuchtung schenken.', '', 25549),
(119676, 'deDE', 'Das war ein Tauren, wenn ich mich nicht irre... und ich irre mich selten.\n\nEr kam mit einer Ausgabe genau dieses Buchs hierher, genau wie Ihr heute, aber er hatte keinen Beweis für den Tod des schwarzen Drachen, also schwieg ich wie ein Grab. Er war sehr begierig, zu erfahren, wo der Aschenbringer zu finden sei.\n\nWenn Ihr ihn findet, kann er Euch vielleicht weitere Erleuchtung schenken.', '', 25549),
(119675, 'deDE', 'Wer hat Euch sonst noch aufgesucht?', 'Wer hat Euch sonst noch aufgesucht?', 25549),
(119674, 'deDE', 'Ein Menschenmagier gab mir vor vielen Jahren eine Ausgabe dieses Buchs. Er versuchte, mich davon zu überzeugen, ihm zu helfen, und redete unablässig davon, Feuer mit Feuer zu bekämpfen.\n\nWie Ihr wisst, kann ich diesen Ort nicht verlassen, also war das auch das letzte Mal, dass ich ihn zu Gesicht bekam. Ich nehme an, dass er fortging, um sich wieder seinen Verbündeten anzuschließen.\n\nEs gibt außer Euch aber noch andere, die sich für dieses Buch interessieren. Ich frage mich...', '', 25549),
(119673, 'deDE', 'Was ist mit diesem Buch? Könnt Ihr mir sagen, was das alles bedeutet?', 'Was ist mit diesem Buch? Könnt Ihr mir sagen, was das alles bedeutet?', 25549),
(119672, 'deDE', 'Ah, ja. Ich hörte von Nefarians Ableben, aber es ist wirklich ein besonderes Vergnügen, sein grausiges Ende mit eigenen Augen zu sehen. Säße ich nicht in diesen Hallen fest, würde ich wahrscheinlich sein Versteck aufsuchen.\n\nVielleicht eines Tages.\n\nWas meinen Teil unserer Vereinbarung angeht, so ist die Geschichte vom Aschenbringer natürlich eine meiner Lieblingsgeschichten.\n\n<Der Prinz wirft einen Blick auf Eure Waffe und lächelt.>\n\nDoch anscheinend seid Ihr mit genau dieser Geschichte bereits vertraut.', '', 25549),
(119671, 'deDE', 'Das war der Letzte von ihnen. Ich kann meine letzte Kraft noch einsetzen, um zu entkommen. Lebt wohl, Freunde.', '', 25549),
(119670, 'deDE', 'Das ist der Rest meiner Macht. Nehmt ihn und vernichtet diese Verräter!', '', 25549),
(119669, 'deDE', 'Was?! Die Nachtgeborenen sind da!', '', 25549),
(119668, 'deDE', 'Das war knapp. Ich dachte, deren Ansturm würde niemals aufhören.', '', 25549),
(119667, 'deDE', 'Bitte, wir haben keine Zeit zu verschwenden! Kommt!', '', 25549),
(119666, 'deDE', 'Achtung, Angriff!', '', 25549),
(119665, 'deDE', 'Warum nicht beides, Eure Hoheit? Ich werde Euch die Geschichte vom Fall des schwarzen Drachen Nefarian erzählen, wenn Ihr mir mehr über dieses Buch und den Aschenbringer erzählt.', 'Warum nicht beides, Eure Hoheit? Ich werde Euch die Geschichte vom Fall des schwarzen Drachen Nefarian erzählen, wenn Ihr mir mehr über dieses Buch und den Aschenbringer erzählt.', 25549),
(119664, 'deDE', 'Das ist erst der Anfang. Die Verdorrten werden von so viel Energie an einem Ort angezogen werden.', '', 25549),
(119663, 'deDE', 'Ein einzelner Goblingleiterbausatz kostet:', 'Ein einzelner Goblingleiterbausatz kostet:', 25549),
(119662, 'deDE', 'Die Elementare spüren die Unruhe hier. Verteidigt Euch!', '', 25549),
(119661, 'deDE', '', 'Gute Wahl! Benutzt ihn auf jeden Fall, bevor Ihr auf dem Boden aufschlagt. Danach bringt er nicht mehr viel.', 25549),
(119660, 'deDE', 'Ein Schmied mit ausreichendem Wissen kann die Einzelheiten erkennen. Die Kratzer auf der Klinge und die Abnutzung des Griffs lassen auf Belastung im Kampf schließen, und wo es am häufigsten getroffen wurde. Seht, wie einfach Ihr sie ausbalancieren könnt. Die Leichtigkeit Eures Griffs lässt auf jahrelange Erfahrung schließen. Dergleichen kann man nicht schmieden, aber ich kann eine Waffe an den richtigen Stellen verbessern, damit ihr Träger noch besser zuschlagen kann und sich weitere Jahre verdient.', '', 25549),
(119659, 'deDE', 'Also gut, obwohl ich noch nie gesehen habe, dass ein Schmied auf diese Weise arbeitet.', '', 25549),
(119658, 'deDE', 'Einen großartigen Kampf habe ich da gesehen! Meister Saurfang, ich glaube, $n hat sich zu Recht für Euch entschieden. Darf ich jetzt Euch und Eure Waffe gemeinsam in Augenschein nehmen?', '', 25549),
(119657, 'deDE', 'Klar, ich nehme einen.', 'Klar, ich nehme einen.', 25549),
(119656, 'deDE', '', 'Hallo Schätzchen! Seid vorsichtig, wenn Ihr Euch in den Dalarankrater begebt, da geht es ziemlich tief hinab.\n\nZufällig biete ich Gleiter an, solltet Ihr einen benötigen.\n\n10 Gold.\n\nKein Umtausch, keine Erstattung.', 25549),
(119655, 'deDE', 'Genug! Ihr habt Eure Fähigkeit unter Beweis gestellt. Ich werde Eurer Bitte entsprechen.', '', 25549),
(119654, 'deDE', 'Es ist schön, Euch zu sehen. Ich konnte sie zurückhalten, aber ich fürchte, es werden bald noch mehr kommen.', '', 25549),
(119653, 'deDE', 'Ich bin hier. Lasst uns keine Zeit verlieren!', '', 25549),
(119652, 'deDE', '', 'Ihr solltet versuchen, jemanden zu finden, der mehr über dieses Buch weiß. Ich glaube, dass es darin um weit mehr geht als einen fröhlichen Angelausflug!', 25549),
(119651, 'deDE', '', 'Aha! Es hat geklappt!', 25549),
(119650, 'deDE', '', 'Wie faszinierend. Es klingt, als ob dieser Nat Pagle ein echter Abenteurer ist!', 25549),
(119649, 'deDE', '', 'Ich werde eine Kopie für unsere Archive drucken lassen, damit Ihr das vollständige Buch behalten könnt, Hochlord.', 25549),
(119648, 'deDE', 'Wir treffen uns bei der Halle der Schatten.', 'Wir treffen uns bei der Halle der Schatten.', 25549),
(119647, 'deDE', '', 'Das sollte nicht allzu lange dauern. Oh, das ist so aufregend!', 25549),
(119646, 'deDE', 'Ich muss dem Rat von Euren Neuigkeiten berichten. Viel Glück, $n!', '', 25549),
(119645, 'deDE', 'Dafür haben wir einen Platz. Begebt Euch zum Zirkel des Ruhms. Ich werde eine Val''kyr losschicken, um diesen Saurfang herzubringen.', '', 25549),
(119644, 'deDE', 'Willkommen in Dalaran! Ich werde Euch gerne bei allem behilflich sein.', '', 25549),
(119643, 'deDE', '<Erzählt Helgar von Saurfang und seiner Bitte.>', '<Erzählt Helgar von Saurfang und seiner Bitte.>', 25549),
(119642, 'deDE', 'Ihr seht zufrieden aus. Habt Ihr Euren Krieger gefunden?', '', 25549),
(119641, 'deDE', 'Wieso hat man mich zurückgeholt, um für Euch zu kämpfen?', '', 25549),
(119640, 'deDE', 'Natürlich.', 'Natürlich.', 25549),
(119639, 'deDE', '', '<Elda blättert vorsichtig mit dem Daumen durch die Seiten und ihre Augen bewegen sich schnell, während sie den verwitterten Text liest.>\n\nBeim Licht, Hochlord... Ich glaube, Ihr habt recht! Das muss es sein!\n\nIch müsste es wieder zusammensetzen können. Gebt mir nur einen Moment Zeit!', 25549),
(119638, 'deDE', 'Ich weiß von Euren Heldentaten, aber ich muss sie mit eigenen Augen sehen, bevor ich Euch gebe, was Ihr wollt. Lasst uns ein Duell bestreiten.', '', 25549),
(119637, 'deDE', 'Schwester, könntet Ihr Euch die hier mal ansehen? Das könnten die verschwundenen Teile des Buchs sein!', 'Schwester, könntet Ihr Euch die hier mal ansehen? Das könnten die verschwundenen Teile des Buchs sein!', 25549),
(119636, 'deDE', 'Obwohl ich kein Interesse daran habe, Eure Allianz zu stärken, ist die Bedrohung durch die Legion zu groß, um nicht alles dagegen zu tun.', '', 25549),
(119635, 'deDE', '', 'Ich werde es sofort öffnen. Dann muss ich der Waldläufergeneralin berichten, was ich herausgefunden habe. Viel Glück!', 25549),
(119634, 'deDE', '', 'Ich habe etwas über ein Buch gelesen, das von einem Handwerksexperten geschrieben wurde und sich ausführlich mit dem Aschenbringer beschäftigt.\n\nDie meisten Ausgaben scheinen vor langer Zeit verschwunden zu sein und ihre zerfetzten Seiten wurden in alle Winde verstreut.\n\nIch frage mich, ob es noch irgendwo da draußen ist? Ich bin sicher, wir könnten das eine oder andere lernen, wenn wir in der Lage wären, es wieder zusammenzusetzen.', 25549),
(119633, 'deDE', 'Ich muss für König Anduin nach Dalaran. Könnt Ihr ein Portal öffnen?', 'Ich muss für König Anduin nach Dalaran. Könnt Ihr ein Portal öffnen?', 25549),
(119632, 'deDE', 'Wenn Ihr so weit seid, schickt mir Euren Boten. Ich werde kommen.', '', 25549),
(119631, 'deDE', 'Ihr habt ebenfalls viele Schlachten erlebt. Vielleicht ist es Zeit, zu sehen, wie weit Ihr es gebracht habt. Lasst uns ein Duell bestreiten und ich werde Eurem Schmied helfen.', '', 25549),
(119630, 'deDE', '', 'Ich habe Forschungen für Waldläufergeneralin Windläufer durchgeführt, als das Chaos losbrach.$b$bWas braucht Ihr?', 25549),
(119629, 'deDE', 'Es ehrt mich, dass Ihr und er so viel von mir haltet. Es ist richtig, dass ich nicht wenige Schlachten mitgemacht habe.', '', 25549),
(119628, 'deDE', '<Erzählt Saurfang von Helgars Bitte.>', '<Erzählt Saurfang von Helgars Bitte.>', 25549),
(119627, 'deDE', 'Ich tue nichts um des Lobes willen. Ich bin hier, um Azeroth und die Horde zu retten. Ich spüre, dass Ihr hier ein Ziel verfolgt. Was wollt Ihr?', '', 25549),
(119626, 'deDE', 'Ihr seid einer der größten Krieger, der je für die Horde ins Feld gezogen ist. Euer Arkanitschnitter wird von all Euren Feinden gefürchtet.', 'Ihr seid einer der größten Krieger, der je für die Horde ins Feld gezogen ist. Euer Arkanitschnitter wird von all Euren Feinden gefürchtet.', 25549),
(119625, 'deDE', 'Heute bin ich hier, um gegen die Feinde Azeroths zu kämpfen. Ich habe keine Lust, meine Kraft an Euch aufzureiben. Was wollt Ihr?', '', 25549),
(119624, 'deDE', 'Das war zu erwarten. Ymiron war ein grausamer und böser Herrscher, doch er hat immer mit großer Leidenschaft gekämpft.', '', 25549),
(119623, 'deDE', 'Manchmal ist das Beste, ins Feld zu ziehen und sich selbst ein Bild vom Krieg zu machen. Der Krieg könnte besser laufen.', '', 25549),
(119622, 'deDE', 'Danke.', 'Danke.', 25549),
(119621, 'deDE', 'Euer Schwert ist unglaublich. Ich frage mich, ob es eine gleichwertige Axt gibt.', '', 25549),
(119620, 'deDE', 'Das mag ja sein, aber es gibt doch keine bessere Strafe für ihn, als Euch bis ans Ende der Zeit dienen zu müssen, oder?', 'Das mag ja sein, aber es gibt doch keine bessere Strafe für ihn, als Euch bis ans Ende der Zeit dienen zu müssen, oder?', 25549),
(119619, 'deDE', 'Kommt überhaupt nicht in Frage.$B$BKönig Ymiron verriet sein Volk und stürzte es in ein verfluchtes Dasein.$B$BEr mag zwar tapfer kämpfend gestorben sein, aber ich verabscheue ihn und das beruht auf Gegenseitigkeit.', '', 25549),
(119618, 'deDE', 'Ich möchte, dass er sich unserer Armee anschließt.', 'Ich möchte, dass er sich unserer Armee anschließt.', 25549),
(119617, 'deDE', '<Odyns Gelächter klingt wie tiefer Donner.>$B$BIhr seid ein Schlitzohr, $n. Ihr habt recht, das würde mich belustigen. Lasst es geschehen!', '', 25549),
(119616, 'deDE', 'König Ymiron wurde besiegt. Er hat erbittert gekämpft.', 'König Ymiron wurde besiegt. Er hat erbittert gekämpft.', 25549),
(119615, 'deDE', 'Das mag unser Ende sein, Freunde – doch wenn wir heute hier sterben, dann sterben wir kämpfend!', '', 25549),
(119614, 'deDE', 'Brechen wir zur Insel des Donners auf und benutzen diesen Schlüssel.', 'Ich habe den Schlüssel, lasst uns den Beutezug beginnen. [Für Solo-Instanz anmelden.]', 25549),
(119613, 'deDE', 'Ist das ein Schlüssel zum Palast von Lei Shen? Wo habt Ihr den denn her?\n\nDie Schatzkammer des Donnerkönigs... Ein allerletzter Raubzug um der alten Zeiten willen? Ein Wort von Euch, und ich bin dabei.', 'Wir können den Beutezug jederzeit beginnen. Wir brauchen nur den Schlüssel. Habt Ihr ihn gefunden?', 25549),
(119612, 'deDE', 'Es muss eine geben. All die mächtigen Vorzüge des Kriegsbrechers vereint mit der spaltenden Stärke einer Axt. So etwas muss es doch geben!', '', 25549),
(119611, 'deDE', 'Gibt es eine Axt, die Strom''kar ebenbürtig ist?', 'Gibt es eine Axt, die Strom''kar ebenbürtig ist?', 25549),
(119610, 'deDE', 'Angesichts Eures Schwert stelle ich mir die Frage, ob es als Axt besser wäre. Wie würde diese Axt aussehen? Gibt es vielleicht bereits eine da draußen?', '', 25549),
(119609, 'deDE', 'Zerschmettert ihre Portale! Hinaus mit der Legion!', '', 25549),
(119608, 'deDE', 'Dämonen im Thronsaal! Schützt den König!', '', 25549),
(119607, 'deDE', 'Könnt Ihr mir sonst noch etwas über Xe''ra und die Naaru sagen, bevor wir losziehen? [ICH ZIEHE MEIN ROTES HEMD AN UND SETZE EINEN ZAUBERERHUT AUF.]', 'Könnt Ihr mir sonst noch etwas über Xe''ra und die Naaru sagen, bevor wir losziehen? [VIELE RP]', 25549),
(119606, 'deDE', 'Ich bin bereit, Velen!', 'Ich bin bereit, Velen!', 25549),
(119605, 'deDE', 'Seid Ihr bereit, O''ros vor Rakeesh zu retten und die Geheimnisse aufzudecken, die im Herz des Lichts bewahrt werden?', '', 25549),
(119604, 'deDE', 'Sagt mir, wenn Ihr bereit seid, O''ros zu retten, und wir werden gehen.', '', 25549),
(119603, 'deDE', 'Nehmt Euren Mut zusammen. Wir müssen schnell handeln!', '', 25549),
(119602, 'deDE', 'Diese Invasion war nur eine List. Wir wurden hier wie Vieh eingepfercht, genau, wie sie es geplant hatten. Jetzt haben sie O''ros gefunden, das letzte Kind der Lichtmutter!', '', 25549),
(119601, 'deDE', 'HA! Wenn man darauf einschlägt, ertönt Musik! Was für eine köstliche Kreatur! Ich werde das genießen.', '', 25549),
(119600, 'deDE', 'Ihr... Nachwuchs. O''ros... NEIN!', '', 25549),
(119599, 'deDE', 'Was Ihr mir da gebracht habt, nennt sich Herz des Lichts. Es ist der Kern aller Empfindung des höchsten Naaru – Xe''ra.', '', 25549),
(119598, 'deDE', 'Erklärungen folgen auf dem Weg. Sagt mir, wenn Ihr bereit seid, aber bitte – beeilt Euch.', '', 25549),
(119597, 'deDE', '$ct $n, wir müssen aufbrechen. JETZT!', '', 25549),
(119596, 'deDE', 'Mutter des Lichts! Es... Es tut mir leid. Ich wusste nicht...', '', 25549),
(119595, 'deDE', 'Merkt Euch das. Nur die Stärksten überleben.', '', 25549),
(119594, 'deDE', 'Ihr seid so ein Schwächling. Ihr schmeichelt mir nur, um Euch vor einem Kampf zu drücken.', '', 25549),
(119593, 'deDE', 'Ich hole Euch mehr Wein. Bitte tut mir nicht weh.', '', 25549),
(119592, 'deDE', 'Was nicht gesehen?', '', 25549),
(119591, 'deDE', 'Entschuldigt. Ich habe nichts gesehen...', '', 25549),
(119590, 'deDE', 'Ihr solltet die Kleinen nie unterschätzen. Wir sind ziemlich... trickreich.', '', 25549),
(119589, 'deDE', 'Überraschungsangriff!', '', 25549),
(119588, 'deDE', 'Nun, wenn das so ist, dann kann ich ja auch...', '', 25549),
(119587, 'deDE', 'Verzeiht. Ich hatte Euch nicht gesehen. Ich wollte nur...', '', 25549),
(119586, 'deDE', 'Von wegen "nur"! Ihr habt zehn Sekunden, um das zu richten. Dann kracht es!', '', 25549),
(119585, 'deDE', 'Was soll das? Ihr habt mich mit Arkwein übergossen!', '', 25549),
(119584, 'deDE', 'Ich bin einigermaßen beunruhigt.', 'Ich bin einigermaßen beunruhigt.', 25549),
(119583, 'deDE', 'Wie ich es hasse, immer recht zu behalten.', 'Wie ich es hasse, immer recht zu behalten.', 25549),
(119582, 'deDE', '', 'Dank Euch wird sich die Seuche nicht weiter ausbreiten.', 25549),
(119581, 'deDE', '', 'Dieser Schlüsselstein garantiert uns den Erfolg gegen die Magistrix. Wir werden Euch Eure Taten nie vergessen.', 25549),
(119580, 'deDE', '', 'Ohne Eure Hilfe hätten wir Arkanist Naran verloren. Vielen Dank, ich stehe in Eurer Schuld.', 25549),
(119579, 'deDE', '', 'Ich dachte nicht, dass die Schlangen so groß werden! Ihr habt uns alle gerettet.', 25549),
(119578, 'deDE', '', 'Dank Euch kommt der Arkus seinem alten Glanz ein wenig näher.', 25549),
(119577, 'deDE', 'Ich möchte einige Waldläufer requirieren.', 'Ich möchte einige Waldläufer requirieren.', 25549),
(119576, 'deDE', 'Ich möchte einige Fährtenleser requirieren.', 'Ich möchte einige Fährtenleser requirieren.', 25549),
(119575, 'deDE', 'Wie kann ich Euch dienen?', 'Wie kann ich Euch dienen?', 25549),
(119572, 'deDE', 'Was glaubt Ihr, was Ihr da macht?', 'Was glaubt Ihr, was Ihr da macht?', 25549),
(119571, 'deDE', 'Haltet ein! Sofort!', 'Haltet ein! Sofort!', 25549),
(119570, 'deDE', 'Delas, sagt Ihr?', '', 25549),
(119569, 'deDE', 'Möge das Licht Euch leiten.', '', 25549),
(119568, 'deDE', 'Segeln wir nach Sturmwind.', 'Segeln wir nach Sturmwind.', 25549),
(119567, 'deDE', '', 'Im Arkus greift eine Seuche um sich. Rottet sie aus, bevor sie sich ausbreiten kann!', 25549),
(119566, 'deDE', '', 'Ich danke Euch. Die Last der Dunkelheit wurde von mir genommen.', 25549),
(119565, 'deDE', '', 'Sucht den Schlüsselstein, der einst diese Hallen angetrieben hat. Das Mana in ihm wird unserer Sache dienen!', 25549),
(119564, 'deDE', '', 'Mein Geist ist eins mit der Leere!', 25549),
(119563, 'deDE', '', 'Arkanist Naran ist noch immer nicht aus dem Arkus zurück. Findet heraus, was mit ihm passiert ist, und erstattet mir Bericht.', 25549),
(119562, 'deDE', '', 'Das freigesetzte Mana des Arkus hat eine Monstrosität erschaffen! Kümmert Euch um sie, bevor sie noch mächtiger wird!', 25549),
(119561, 'deDE', '', 'Ihr werdet nicht allein reisen.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(119560, 'deDE', '', 'Möge das Licht Euch den Weg weisen.', 25549),
(119559, 'deDE', 'Bitte, lasst mich durch. Ich bringe Nachricht von Delas Mondfang!', '', 25549),
(119558, 'deDE', 'Keinen Schritt weiter! Nur Priester dürfen diesen Tempel betreten.', '', 25549),
(119557, 'deDE', '', 'Ich würde die Paladine gern mit einer kleinen Gruppe Priester auf ihrer Suche nach dieser Dämonenwelt begleiten. Wenn der Schreckenslord dort ist, werden wir ihn finden.', 25549),
(119556, 'deDE', '', 'Ich habe gemeinsam mit Aponi Lichtmähne und dem Anführer ihres Ordens einen Kodex übersetzt, der Details zu einer geplanten Invasion der Legion am Teufelsfeuervorstoß enthält.', 25549),
(119555, 'deDE', '', 'Ein fauliger Schleim tritt seit Wochen aus dem Arkus aus. Findet die Quelle und bringt sie zum Versiegen.', 25549),
(119554, 'deDE', 'Die Dämonen haben die meisten meiner Schamanen getötet. Wir haben uns hierher zurückgezogen, um uns ihnen ein letztes Mal entgegenzustemmen.$B$B<Nobundo seufzt.>', '', 25549),
(119553, 'deDE', 'Fahrt fort, Delas, erzählt uns, was Ihr erfahren habt.', '', 25549),
(119552, 'deDE', '', 'Die Schatten werden Euch zur Seite stehen, solltet Ihr ihrer jemals bedürfen.', 25549),
(119551, 'deDE', '', 'Die Schatten werden Euch verschlingen!', 25549),
(119550, 'deDE', '', 'Ihr habt mir die Chance gegeben, meine Schuld zu tilgen, und ich werde alles dafür tun, solange ich lebe.', 25549),
(119549, 'deDE', 'In Zeiten wie diesen können wir es uns nicht leisten, Hilfe abzuweisen. Seid willkommen, neuer Verbündeter.', '', 25549),
(119548, 'deDE', 'Das kommt unerwartet – eine scharlachrote Priesterin in unserem Tempel.', '', 25549),
(119547, 'deDE', '', 'Ich möchte die Priesterschaft in ihrem Kampf gegen die Brennende Legion unterstützen.', 25549),
(119546, 'deDE', '', 'Ich habe ihren Namen abgelegt, und ihre Werte.', 25549),
(119545, 'deDE', '', 'Nun macht schon! Ich sterbe lieber, als einen weiteren Tag in dieser Hölle aus Euren verzerrten Ansichten zu leben!', 25549),
(119544, 'deDE', 'Wir haben es geschafft!', 'Wir haben es geschafft!', 25549),
(119543, 'deDE', 'Großartige Arbeit von allen!', 'Großartige Arbeit von allen!', 25549),
(119542, 'deDE', 'Die Legion wird fallen!', 'Die Legion wird fallen!', 25549),
(119541, 'deDE', 'Bei unseren Klingen!', 'Bei unseren Klingen!', 25549),
(119540, 'deDE', 'Gemeinsam wie ein Mann!', 'Gemeinsam wie ein Mann!', 25549),
(119539, 'deDE', 'Ein guter Kampf!', 'Ein guter Kampf!', 25549),
(119538, 'deDE', 'Für die Allianz!', 'Für die Allianz!', 25549),
(119537, 'deDE', 'Darf ich ihn sehen?', '', 25549),
(119536, 'deDE', 'Ein unangenehm großer Dämon ist in unserem Lager in Süderstade aufgetaucht. Etwas Verstärkung wäre uns eine große Hilfe.', '', 25549),
(119535, 'deDE', 'Noch ein Dämon! Ostwachtturm! Wir halten ihn auf, so lange wir können!', '', 25549),
(119534, 'deDE', '', 'Schickt Verstärkung zum Südwachttor!', 25549),
(119533, 'deDE', 'Der Ostwachtturm wird angegriffen!', '', 25549),
(119532, 'deDE', 'ALLIANZ! Aufsitzen! In den westlichen Hügeln wimmelt es nur so von dämonischem Abschaum!', '', 25549),
(119531, 'deDE', 'Legionsgebäude! Felder südwestlich von Tarrens Mühle! Weg damit!', '', 25549),
(119530, 'deDE', 'Hilfe! Bitte!', 'Hilfe! Bitte!', 25549),
(119529, 'deDE', '', 'Danke, Meister Shaw. Das ist der Plan, Ungekrönte. Wer stimmt dafür?', 25549),
(119528, 'deDE', 'Der Plan ist einfach: in Sturmwind einschleusen, Detheroc enttarnen und dann töten.', '', 25549),
(119527, 'deDE', 'Detheroc gibt vor, ich zu sein und flüstert dem neuen König von Sturmwind Lügen über die Horde zu. Er muss aufgehalten werden, bevor es zu spät ist.', '', 25549),
(119526, 'deDE', 'Taoshi hat recht. Die Lage ist kritisch und verschlimmert sich zunehmend. Die Allianz steht kurz davor, die Horde anzugreifen.', '', 25549),
(119525, 'deDE', 'Diese Entscheidung werdet Ihr sicher nicht bereuen. Was ich Euch jetzt vorschlage, ist jedoch viel gefährlicher.', '', 25549),
(119524, 'deDE', 'Erst mal vielen Dank für meine Rettung trotz Gefährdung Eures eigenen Lebens.', '', 25549),
(119523, 'deDE', 'Tethys wird uns übers Meer zum Hafen bringen. Zum SI:7 müssen wir schleichen. Wir können nicht fliegen. Detheroc hat Scharfschützen auf den Dächern und unsere Gesichter auf Plakate drucken lassen.', '', 25549),
(119522, 'deDE', '', 'Die Lage in Sturmwind ist schlimmer als wir dachten. Wir haben einen Plan, um Detherocs Täuschung offenzulegen. Meister Shaw?', 25549),
(119521, 'deDE', 'Jetzt sind wir quitt. Von jetzt an geht alles wie gewohnt. Benutzt den Tiegel, so viel Ihr möchtet.', '', 25549),
(119520, 'deDE', 'Hey! Wenn Ihr jemandem eine Klinge an den Hals setzt, passt auf, mit wem Ihr es zu tun habt.', '', 25549),
(119519, 'deDE', '<Legt das mysteriöse lichtgebundene Objekt auf den Boden.>', '<Legt das mysteriöse lichtgebundene Objekt auf den Boden.>', 25549),
(119518, 'deDE', 'In Eurem Besitz befindet sich ein Gegenstand von großer Wichtigkeit. Kann ich ihn sehen?', '', 25549),
(119517, 'deDE', 'Ich weiß, Ihr seid weit gereist, um mich zu finden und bringt bittere Kunde mit Euch.', '', 25549),
(119516, 'deDE', 'Ich fürchte, wir haben nur einen Moment. Rakeesh ist noch hier – irgendwo. Er muss gestoppt werden, wenn mein Volk wieder Frieden finden soll.', '', 25549),
(119515, 'deDE', 'Nun zu Euch, Valarjar... Gut gemacht. Sehr gut!', '', 25549),
(119514, 'deDE', 'Wenn Ihr meinen Segen wünscht, müsst Ihr zuvor die uralten Prüfungen dieser Hallen bestehen, Valarjar.', '', 25549),
(119513, 'deDE', 'Meine Geduld ist am Ende. Bereitet mir das Festmahl, bevor wir kämpfen, oder mein Segen wird Euch an diesem Tag verwehrt bleiben!', '', 25549),
(119512, 'deDE', 'Danke für diese wahrhaft unglaubliche Reise. Solltet Ihr je nach einem neuen Abenteuer suchen – Ihr wisst, wo Ihr mich findet.', '', 25549),
(119511, 'deDE', 'Unglaublich. Es hat wirklich funktioniert!', '', 25549),
(119510, 'deDE', 'Der Zeitpunkt ist gekommen, $p. Entfesselt die Macht tief im Inneren!', '', 25549),
(119509, 'deDE', '', 'Elun''orin torel!', 25549),
(119508, 'deDE', 'Anar''endal dracon belora.', '', 25549),
(119507, 'deDE', 'Gemeinsam kämpfen? Nun... meinetwegen.', 'Gemeinsam kämpfen? Nun... meinetwegen.', 25549),
(119506, 'deDE', 'Lasst uns anfangen.', 'Lasst uns anfangen.', 25549),
(119505, 'deDE', 'Lasst den Schmerz zu mir sprechen.', 'Lasst den Schmerz zu mir sprechen.', 25549),
(119504, 'deDE', 'Ishnu-talah Kaldorei.', '', 25549),
(119503, 'deDE', 'Elun''falah shalar.', '', 25549),
(119502, 'deDE', 'Wir sind bereit, wenn Ihr es seid.', '', 25549),
(119501, 'deDE', 'Es tut gut, zu Hause zu sein. Auch, wenn es nur für eine kurze Weile ist.', '', 25549),
(119500, 'deDE', 'Ich nehme das Herz und treffe Euch dort. Die Mondwache wird den Bereich für unsere Ankunft sichern.', '', 25549),
(119499, 'deDE', 'Dann müssen wir sie wohl bitten, zu verschwinden.', '', 25549),
(119498, 'deDE', '', 'Natürlich! Doch in der Festung wimmelt es nur so vor Nachtgeborenen.', 25549),
(119497, 'deDE', 'Es gibt nur einen Ort, an dem wir die Macht der Splitter nutzen können: der Mondtiegel.', '', 25549),
(119496, 'deDE', '', 'Danke. Lasst Ly''leth wissen, dass ich auf ihrer Seite bin.', 25549),
(119495, 'deDE', 'Ja, Mutter.', '', 25549),
(119494, 'deDE', '', 'Du wirst so lange bei mir bleiben, bis ein Berater bestimmt wurde. Versprich mir das!', 25549),
(119493, 'deDE', 'Nur ein Gegenstand pro Woche, Boss. So sind die Regeln.', '', 25549),
(119492, 'deDE', 'Nun müsst Ihr Euch der Inkarnation der Dunkelheit selbst stellen... Gul''dan.', '', 25549),
(119491, 'deDE', 'Es könnte schwierig sein, einen Verbündeten unter unseren Feinden zu finden.', '', 25549),
(119490, 'deDE', 'Ich werde dieses höllische Schiff verlassen! Ich werde sofort zu meiner Mutter zurückkehren.', '', 25549),
(119489, 'deDE', 'Ein Entladenes Partikel fällt aus dem Nachtbrunnen.', '', 25549),
(119488, 'deDE', 'Freilassen', 'Freilassen', 25549),
(119487, 'deDE', 'Bringt mich hier raus!', '', 25549),
(119486, 'deDE', 'Sie haben uns verraten. Ihr Schicksal ist besiegelt.', '', 25549),
(119485, 'deDE', '', 'Ich werde vorausgehen und den anderen helfen. Zusammen kommen wir hier heraus, Schwester.', 25549),
(119484, 'deDE', 'Ich habe mit Thalrenus einen genauen Plan für unseren Angriff auf die Nachtfestung ausgearbeitet.', '', 25549),
(119483, 'deDE', 'Ein schwindendes Zeitpartikel fällt aus dem Nachtbrunnen.', '', 25549),
(119482, 'deDE', '', 'Ihr solltet zurück zum Portal gehen. Der Hochlord und ich werden uns um den Rest kümmern.', 25549),
(119481, 'deDE', 'Ja, mir geht es gut. Diese Wichtelmutter ist mir allerdings näher gekommen, als mir lieb war.', '', 25549),
(119480, 'deDE', '', 'Arator, seid Ihr noch am Leben?', 25549),
(119479, 'deDE', 'Kehrt zurück, sobald Ihr für einen Angriff auf die Nachtfestung bereit seid. Thalrenus und ich arbeiten inzwischen letzte Einzelheiten unseres Plans aus.', '', 25549),
(119478, 'deDE', '', 'Niemals. Das Licht steht zusammen.', 25549),
(119477, 'deDE', '', 'Ihr seid zurück! Ich dachte schon, das wäre das Ende.', 25549),
(119476, 'deDE', '', 'Delas, Ihr seid am Leben! Dem Licht sei gedankt!', 25549),
(119475, 'deDE', 'Zeit, die Chancen auszugleichen.', '', 25549),
(119474, 'deDE', '', 'Der Tempel... wird... fallen...', 25549),
(119473, 'deDE', 'Der Feind nutzt möglicherweise Magie, um uns zu täuschen! Seid auf der Hut!', '', 25549),
(119472, 'deDE', '', 'Nun werden unsere Armeen angreifen. Der Tempel wird fallen... und der große Prophet Velen mit ihm!', 25549),
(119471, 'deDE', '', 'Schließlich spürten wir seine Anwesenheit. Denn das heilige Licht sickerte durch den Wirbelnden Nether und blendete uns!', 25549),
(119470, 'deDE', '', 'Seit Ewigkeiten suchen wir schon nach dem Netherlichttempel! Und dabei lag er die ganze Zeit direkt vor unserer Nase!', 25549),
(119469, 'deDE', 'Bewegt Euch und zerschmettert alle, die sich der Legion widersetzen!', '', 25549),
(119468, 'deDE', '', 'Seid Ihr wegen ihm hier? An mir kommt Ihr nicht vorbei!', 25549),
(119467, 'deDE', 'Wer gegen den Meister die Stimme erhebt, muss vernichtet werden!', '', 25549),
(119466, 'deDE', 'Die Ordnung in der Stadt wird unter Einsatz von Gewalt wiederhergestellt!', '', 25549),
(119465, 'deDE', '', 'Es ist der Prophet Velen! Sein Leben könnte in großer Gefahr sein.', 25549),
(119464, 'deDE', '', 'Ich erkenne diesen Ort wieder. Ist dies nicht... der Netherlichttempel? Will die Legion etwa die Ordenshalle der Priester angreifen?', 25549),
(119463, 'deDE', '', 'Das ist ein detailliertes Reiseverzeichnis. Es scheint, die Legion hat im wirbelnden Nether nach etwas gesucht. Aber wonach?', 25549),
(119462, 'deDE', 'Tötet sie! Tötet sie sofort!', 'Tötet sie! Tötet sie sofort!', 25549),
(119461, 'deDE', 'Narren! Su''esh ist aus der Menagerie entkommen!', 'Narren! Su''esh ist aus der Menagerie entkommen!', 25549),
(119460, 'deDE', 'Su''esh ist frei! Zu den Waffen!', 'Su''esh ist frei! Zu den Waffen!', 25549),
(119459, 'deDE', 'Sterbt, Bestie!', 'Sterbt, Bestie!', 25549),
(119458, 'deDE', 'Keine Bestie ist eine Herausforderung für die Legion!', 'Keine Bestie ist eine Herausforderung für die Legion!', 25549),
(119457, 'deDE', 'Die Bestie ist frei! Tötet sie!', 'Die Bestie ist frei! Tötet sie!', 25549),
(119456, 'deDE', '', 'Ich werde nach Dalaran reisen und in Ruhe diese Runensteine entziffern.', 25549),
(119455, 'deDE', 'Zeit für eine kleine Lektion in Sachen Schmerz!', '', 25549),
(119454, 'deDE', 'Genug gesagt!', '', 25549),
(119453, 'deDE', '', 'Zu Befehl!', 25549),
(119452, 'deDE', 'Ich bringe den Tod!', '', 25549),
(119451, 'deDE', 'Auf geht''s!', '', 25549),
(119450, 'deDE', '', 'Für Elune!', 25549),
(119449, 'deDE', '', 'Ich werde sie jagen!', 25549),
(119448, 'deDE', '', 'Nachtauge ist dabei, sich in der Menagerie umzusehen. Hoffentlich passt er auf sich auf!', 25549),
(119447, 'deDE', '', 'Nachtauge ist wieder auf Patrouille. Ich hoffe, dass er diesmal sicher ist.', 25549),
(119446, 'deDE', '', 'Seid vorsichtig, $R. Die Nachtgeborenen sind mutig geworden und nun auch außerhalb ihrer Stadt aktiv.', 25549),
(119445, 'deDE', '', 'Ich werde Euch nicht enttäuschen.', 25549),
(119444, 'deDE', 'Fertig, Baron! Los geht''s!', '', 25549),
(119443, 'deDE', 'Ich werde einen Weg finden!', '', 25549),
(119442, 'deDE', 'Man hat mich angewiesen, ihn den Fleischfressern vorzuwerfen. Ihr werdet nur noch Knochen finden!', 'Man hat mich angewiesen, ihn in die Löwengrube zu werfen. Ihr werdet nur noch Knochen finden!', 25549),
(119441, 'deDE', 'Bah! Ich gebe mich geschlagen!', 'Bah! Ich gebe mich geschlagen!', 25549),
(119440, 'deDE', 'Ihr könnt ihn nicht retten. Er ist ohnehin so gut wie tot!', 'Ihr könnt ihn nicht retten. Er ist ohnehin so gut wie tot!', 25549),
(119439, 'deDE', 'Ich werde Euch gar nichts geben! Höchstens Schmerzen!', 'Ich werde Euch gar nichts geben! Höchstens Schmerzen!', 25549),
(119438, 'deDE', '', 'Genug geredet. Zeit zu handeln!', 25549),
(119437, 'deDE', 'Die Tirisgarde wird alles überstehen!', '', 25549),
(119436, 'deDE', 'Ich schaffe das!', '', 25549),
(119435, 'deDE', '', 'Ich ehre meine Meisterin!', 25549),
(119434, 'deDE', 'He, Mann! Das mach ich!', '', 25549),
(119433, 'deDE', '', 'Ich gebe mein Bestes!', 25549),
(119432, 'deDE', 'Ihr ruft die Winde?', '', 25549),
(119431, 'deDE', 'Nun gut, Delas. Kehrt zum Tempel zurück, sobald Ihr sichere Informationen habt.', '', 25549),
(119430, 'deDE', '', 'Kommandant, Alonsus – verzeiht die Störung, aber ich komme mit Neuigkeiten, die Ihr sicher hören möchtet.', 25549),
(119429, 'deDE', 'Calydus ist bereit!', '', 25549),
(119428, 'deDE', '', 'Das schaff'' ich!', 25549),
(119427, 'deDE', '', 'Eine einfache Bitte.', 25549),
(119426, 'deDE', 'Ehre und Gerechtigkeit für Euch, Hochlord. Ich werde weiter für den Orden kämpfen!', 'Ehre und Gerechtigkeit für Euch, Hochlord. Ich werde weiter für den Orden kämpfen!', 25549),
(119425, 'deDE', 'Ich bin so froh, Euch zu sehen, $n. Möge das Licht Euch segnen.', 'Ich bin so froh, Euch zu sehen, $n. Möge das Licht Euch segnen.', 25549),
(119424, 'deDE', 'Habt Dank, Hochlord. Für die Silberne Hand!', 'Habt Dank, Hochlord. Für die Silberne Hand!', 25549),
(119423, 'deDE', 'Ich hätte nicht erwartet, dass mich eines Tages die Silberne Hand retten würde. Vielen Dank an Euch und auch an Euren Orden.', 'Ich hätte nicht erwartet, dass mich eines Tages die Silberne Hand retten würde. Vielen Dank an Euch und auch an Euren Orden.', 25549),
(119422, 'deDE', 'Meine Gebete wurden erhört. Ich danke Euch, $C.', 'Meine Gebete wurden erhört. Ich danke Euch, $C.', 25549),
(119421, 'deDE', 'Ich habe niemals die Hoffnung aufgegeben, $C. Vielen Dank.', 'Ich habe niemals die Hoffnung aufgegeben, $C. Vielen Dank.', 25549),
(119420, 'deDE', 'Mein Glaube gab mir die Kraft, nie an meiner Rettung zu zweifeln. Vielen Dank.', 'Mein Glaube gab mir die Kraft, nie an meiner Rettung zu zweifeln. Vielen Dank.', 25549),
(119419, 'deDE', 'Als sie uns durch das Portal brachten, dachte ich schon, es wäre aus mit uns. Ich danke Euch, $C.', 'Als sie uns durch das Portal brachten, dachte ich schon, es wäre aus mit uns. Ich danke Euch, $C.', 25549),
(119418, 'deDE', 'Vielen Dank. Möge das Licht Euch segnen.', 'Vielen Dank. Möge das Licht Euch segnen.', 25549),
(119417, 'deDE', 'Danke für Eure Hilfe, Ashildir. Wenn Ihr uns nun entschuldigen würdet, wir müssen ein paar Dämonen austreiben.', '', 25549),
(119416, 'deDE', '', 'Ihr habt den Segen des mächtigen Odyn? Das hätte ich nicht für möglich gehalten.', 25549),
(119415, 'deDE', '|TInterface\\Icons\\Sha_Ability_Mage_FireStarter_nightmare:20|t%s setzt |cFFFF0000|Hspell:191325|h[Odem der Verderbnis]|h|r ein!', '', 25549),
(119414, 'deDE', 'Wir sollten zum Thron der Gezeiten im Meeresschlund aufbrechen, das Szepter muss sich dort befinden. Doch wir sollten vorsichtig sein – ich fürchte, Neptulons Reich wurde infiltriert!', '', 25549),
(119413, 'deDE', 'Alles deutet darauf hin, dass Adelee das Szepter im Meeresschlund vermutet hat. Dem Pfad lässt sich leicht folgen... vielleicht zu leicht. Es könnte eine Falle sein.', '', 25549),
(119412, 'deDE', 'Glücklicherweise ist Adelees Tagebuch mit wasserfester Tinte geschrieben. Darin beschreibt sie sicher ihre Suche nach dem Szepter. Ich werde Zeit brauchen, es zu lesen – bringt es mir.', '', 25549),
(119411, 'deDE', 'Adelee sprach von einem mächtigen Wellenstein. Ich weiß jetzt, was sie meinte. Die Auren, die diesen Stein umgeben, verbergen Bewegungen vor Neptulon, dadurch konnten die Naga unbemerkt in sein Reich gelangen.', '', 25549),
(119410, 'deDE', 'Das ist der Stab von Wellensprecherin Adelee. Hmmm, er ist auf den Meeresschlund abgestimmt. Vielleicht finden wir Sharas''dal dort? Ich hatte sie davor gewarnt, allein dorthin zu gehen...', '', 25549),
(119409, 'deDE', 'Diese uralte Stadt war einst eines der Juwelen von Kalimdor. Durchkämmt die Ruinen.', '', 25549),
(119408, 'deDE', 'Wenn wir sie finden, finden wir auch das Szepter!', '', 25549),
(119407, 'deDE', 'Unsere verschollene Schamanin, Wellensprecherin Adelee, hatte das Szepter der Gezeiten zu dieser versunkenen Stadt verfolgt, bevor sie verschwand.', '', 25549),
(119406, 'deDE', 'Hier lang. Während des Kataklysmus habe ich viele Monate in den Tiefen Vashj''irs verbracht. Es ist wie meine zweite Heimat.', '', 25549),
(119404, 'deDE', 'Für das, was Ihr mir angetan habt, was Ihr mir gestohlen habt, sollte ich Euch niederstrecken.', '', 25549),
(119403, 'deDE', 'Ihr habt schon einmal solche Fesseln besessen. Ein ewiges Gefängnis, aus welchem Ihr mich nur befreit habt, um neidisch nach meiner Macht zu greifen.', '', 25549),
(119402, 'deDE', 'Es ist getan, $R. Ruft nicht erneut nach mir.', '', 25549),
(119401, 'deDE', 'Gebt mir die Fesseln, damit ich sie gegen den Feuerlord und seine Diener nutzen kann. Ich werde Euch großzügig belohnen.', '', 25549),
(119400, 'deDE', 'Doch nun hat der Irdene Ring sich um meine Rückkehr gekümmert. Ich neige daher dazu, etwas Geduld zu zeigen. Vielleicht werden Eure Mühen sich ja nicht als vergeblich herausstellen.', '', 25549),
(119399, 'deDE', 'Und gierige Sterbliche wie Ihr befreiten mich, nur um mich anzugreifen und meine Waffe sowie meine Macht zu stehlen.', '', 25549),
(119398, 'deDE', 'Der Feuerlord Ragnaros hielt mich einst gefangen und nutzte dazu Fesseln wie jene in Eurem Besitz.', '', 25549),
(119397, 'deDE', '$gSterblicher:Sterbliche:r; $R. Ihr traut Euch einiges zu, mich zu beschwören.', '', 25549),
(119396, 'deDE', '', 'Ich schicke Euch zurück zur Taverne, wenn Ihr bereit seid.', 25549),
(119395, 'deDE', '', 'Ich hätte es gern vermieden, aber Ihr habt Euch gut geschlagen.', 25549),
(119394, 'deDE', 'Ich habe wohl meine ermächtigte Verkleidung verloren...', 'Ich habe wohl meine ermächtigte Verkleidung verloren...', 25549),
(119393, 'deDE', 'Die Linien der Verlassenen brechen unter unserem Ansturm auf diesen Inseln zusammen. Vorwärts, für die Allianz!', '', 25549),
(119392, 'deDE', 'Die Horde erhebt erneut Anspruch auf einen Turm der Wächterinnen, der uns gehören sollte. Zeigt ihnen den Zorn der Allianz.', '', 25549),
(119391, 'deDE', '', 'Zeig einem Köter wahre Macht und er zieht den Schwanz ein. Dieser Turm gehört der Horde!', 25549),
(119390, 'deDE', '', 'Erobert den Turm! Die Macht der Horde wird Graumähnes Truppen zerquetschen!', 25549),
(119389, 'deDE', '', 'Ich erwarte einen Titel.', 25549),
(119388, 'deDE', '', 'Ich ändere Eure Tarnung, damit Ihr wie einer von uns kämpfen könnt.', 25549),
(119387, 'deDE', 'Ich bin bereit, Coryn entgegenzutreten.', 'Ich bin bereit, Coryn entgegenzutreten.', 25549),
(119386, 'deDE', '', 'Alles läuft wie geplant. Ihr müsst Euch keine Sorgen machen.', 25549),
(119385, 'deDE', 'Kehrt zu mir zurück, wenn Ihr für diese Herausforderung bereit seid.', '', 25549),
(119384, 'deDE', 'Die Naglfar muss aufgehalten werden, doch Ihr seid noch nicht stark genug.', '', 25549),
(119383, 'deDE', 'Trefft mich auf dem Dach des Sanktums, wenn Ihr sterben wollt, Emporkömmling.', '', 25549),
(119382, 'deDE', 'Ich brauche keinen Champion. Ich verteidige meine Ehre selbst.', '', 25549),
(119381, 'deDE', '', 'Tal''ashar also. Hier ist mein neuer Champion.', 25549),
(119380, 'deDE', 'Die Dryaden umzubringen und in Monstrositäten zu verwandeln... Gut, dass Ihr die Eulenbiester und ihre verderbte Magie aufhalten konntet.', '', 25549),
(119379, 'deDE', 'Eulenbestien sind treue Hüter der heiligen Orte. Aber ohne das Licht von Elune werden sie manchmal aggressiv. Rettet die Dryaden, die von ihnen bedrängt werden.', '', 25549),
(119378, 'deDE', '', 'Im Wald muss wieder Frieden herrschen. Der Grauholzstamm ist seit Langem mit dem Volk von Val''sharah verbündet und hat Eure Hilfe mehr als verdient.', 25549),
(119377, 'deDE', '', 'Die sonst eher zurückgezogenen Grell sind in letzter Zeit aggressiv geworden und haben den Furbolgstamm der Grauholz angegriffen! Ich fürchte, sie werden das Dorf überrennen.', 25549),
(119376, 'deDE', '', 'Vielleicht wird sich dieses Land nie von dem Bösen erholen, aber wir müssen tun, was wir können.', 25549),
(119375, 'deDE', '', 'Der Schreckenswurz war einst ein wunderschöner Wald, der nun von Monstrositäten des Alptraums überrannt wurde. Haltet sie auf!', 25549),
(119374, 'deDE', 'Die nächste Aufgabe könnte sogar für Euch zu gefährlich sein, kleiner Fremdling. Kehrt zu mir zurück, wenn Ihr Eurer Stärke den nötigen Feinschliff gegeben habt.\n\nErst dann könnt Ihr darauf hoffen, die Naglfar zu überleben.', '', 25549),
(119373, 'deDE', 'Wir werden nach Acherus zurückkehren. Kommt Reiter, es gilt, eine Seele zu binden.', '', 25549),
(119372, 'deDE', 'Die Zeit ist gekommen. Tirion Fordring wartet auf uns.', '', 25549),
(119371, 'deDE', 'Zeigt uns, was Ihr habt, Ravis.', 'Zeigt uns, was Ihr habt, Ravis.', 25549),
(119370, 'deDE', 'Wir müssen alle zusammenarbeiten, um die Legion zu besiegen.', '', 25549),
(119369, 'deDE', '', 'Widerliche, kleine Teufel! Diese Geister brauchten eine Lektion, damit sie die Bären in Ruhe lassen!', 25549),
(119368, 'deDE', '', 'Ich spüre, dass die sonst so friedvollen Bären des Sylvantals in Aufruhr sind. Es leben Geister in der Nähe... Vielleicht sind sie die Ursache...', 25549),
(119367, 'deDE', '', 'Xavius'' Verderbnis hat sich überall ausgebreitet! Wir müssen die Höhle der Schläfer läutern.', 25549),
(119366, 'deDE', '', 'Wir konnten die Druiden in der Höhle der Schläfer wecken, aber jetzt geht der Alptraum darin umher. Löscht diese üblen Kreaturen aus!', 25549),
(119365, 'deDE', 'Der Kampf war wirklich hart! Geht und helft Hodir, ich halte den Ausgang frei.', '', 25549),
(119364, 'deDE', '', 'Der Verlust von Dienern des Traums ist tragisch, aber zumindest ruhen sie jetzt in Frieden. Ich danke Euch.', 25549),
(119363, 'deDE', '', 'Unsere Verbündeten, die Hüter und die Dryaden, wurden von dem widerwärtigen Alptraum verderbt. Ihr müsst ihr Leiden beenden.', 25549),
(119362, 'deDE', '', 'Immer noch herrscht die Dunkelheit über das Tal. Aber Ihr habt einen Hoffnungsschimmer gebracht. Ich danke Euch.', 25549),
(119361, 'deDE', '', 'Die Diener des Alptraums beflecken weiterhin das Mondklauental. Löscht sie aus, Champion!', 25549),
(119360, 'deDE', '', 'Eines Tages wird der Weltenbaum Shala''nir mitsamt seinen Wurzeln wieder in Sicherheit sein. Bis zu diesem Tag dürfen wir nicht ruhen!', 25549),
(119359, 'deDE', '', 'Der Alptraum hat die Wurzeln des Weltenbaums selbst verderbt. Befreit Shala''nir von der Verderbnis, die ihn befallen hat.', 25549),
(119358, 'deDE', '', 'Der Krieg der Ahnen gebar viele große Schlachten, wie jene, die Ihr gerade erlebt habt. Für den Sieg über die Dämonen mussten damals alle Verteidiger vereint kämpfen. Genau wie heute.', 25549),
(119357, 'deDE', '', 'Blattbart der Erzähler ist da! Diese alte Seele hat eine packende Geschichte über den Krieg der Ahnen zu erzählen. Hört gut zu, um daraus etwas zu lernen, das Euch im Kampf gegen die Legion helfen kann.', 25549),
(119356, 'deDE', '', 'Wie kann man so verdreht sein, einen solch wundervollen See zu infizieren? Aber jetzt hat das ja zum Glück ein Ende.', 25549),
(119355, 'deDE', '', 'Übles Gift strömt in das Wasser des Nebelgrunds. Ich spüre in meinen Knochen, dass ein verderbter Druide dafür verantwortlich ist. Findet ihn und beendet diesen Frevel.', 25549),
(119354, 'deDE', '', 'Wir haben zwar unsere Differenzen, aber Bradenbach ist meine Heimat. Danke, dass Ihr eingegriffen habt.', 25549),
(119353, 'deDE', '', 'Die armen Leute von Bradenbach! Sie haben Gilneas verlassen, um nicht Opfer des Worgenfluches zu werden. Aber jetzt werden sie von Lord Rabenkrones Dienern bedrängt. Sie brauchen Eure Hilfe!', 25549),
(119352, 'deDE', 'Die Rettung der Eulen war eine edle Tat!', '', 25549),
(119351, 'deDE', 'Die Harpyien wollen die anmutigen Eulen unseres Waldes verfluchen! Beeilung! Hoffentlich ist es noch nicht zu spät...', '', 25549),
(119350, 'deDE', 'Weit mehr als durch magische oder körperliche Fertigkeiten zeichnen sich echte Helden durch Hilfsbereitschaft aus. Heute habt Ihr bewiesen, dass Ihr dazugehört!', '', 25549),
(119349, 'deDE', 'Die Wurmkrallenharpyien sind über das Schattenmoor hergefallen. Die Überlebenden konnten sich zum Glück in Sicherheit bringen. Aber hättet Ihr vielleicht die Güte, ihre Hinterlassenschaften zu bergen?', '', 25549),
(119348, 'deDE', 'Druidenmagie zu missbrauchen, ist eine Sünde! Diese Anhänger von Düsterholz haben den Tod verdient!', '', 25549),
(119347, 'deDE', 'Die Druiden von Düsterholz haben die Pflanzen selbst gegen uns aufgebracht! Wir müssen sie aufhalten, bevor sie noch mehr Unheil anrichten!', '', 25549),
(119346, 'deDE', 'Der Alptraum dringt immer mehr in unsere Realität ein. Aber diese Schlacht habt Ihr zumindest gewonnen.', '', 25549),
(119345, 'deDE', 'Der Alptraum greift unablässig den Tempel von Elune an. Wir müssen diesen heiligsten aller Orte dringend verteidigen.', '', 25549),
(119344, 'deDE', '', 'Feendrachen sind so liebenswert! Man muss sie einfach beschützen!', 25549),
(119343, 'deDE', '', 'Dieses Mal sind die Geister zu weit gegangen! Sie peinigen diese süßen, kleinen Feendrachen der Mondschwingen! Also zieht bitte los und rettet sie!', 25549),
(119342, 'deDE', '', 'Der Angriff der Geister ist vorerst zurückgedrängt. Können Tote jemals wirklich sterben?', 25549),
(119341, 'deDE', '', 'Im Land der Lebenden halten sich viele edle Geister auf, aber die verfluchten Diener von Lord Rabenkrone zählen nicht dazu. Ihr solltet sie vernichten, bevor sie alle gemeinsam über Bradenbach herfallen.', 25549),
(119340, 'deDE', 'Ihr habt viele Verbündete befreit, aber diese Harpyien geben nie auf. Wir müssen weiter wachsam sein, um dieses Land zu schützen.', '', 25549),
(119339, 'deDE', 'Die Steinblutharpyien verwandeln die Akolythen von Elothir mithilfe dunkler Magie zu Stein! Rettet unsere edlen Verbündeten!', '', 25549),
(119338, 'deDE', 'Wir dürfen einem solch tückischen Feind wie den Harpyien nicht nachgeben. Wir müssen diese Verderbnis mit allen Mitteln läutern!', '', 25549),
(119337, 'deDE', 'Die Harpyien schicken sich an, den Wald zu übernehmen. Bekämpft diese Kreaturen und läutert den Wald von ihrem Befall.', '', 25549),
(119336, 'deDE', 'Es kommen noch mehr Champions! Macht Euch bereit!', '', 25549),
(119335, 'deDE', 'Was für $gein:eine:c; $C! Jetzt schaut Euch mal diese Rüstung an! So etwas habe ich noch nie gesehen! Dieser Dämon scheint mir jetzt fällig zu sein.', '', 25549),
(119334, 'deDE', 'Ah, $gein:eine:c; $C! Von Eurer Sorte können wir noch mehr brauchen!', '', 25549),
(119333, 'deDE', 'Es scheint Verstärkung eingetroffen zu sein!', '', 25549),
(119332, 'deDE', 'Gut gekämpft! Auch wenn das wohl nur der Anfang war. Wir müssen diese Bedrohung vollständig ausschalten, Champions!', '', 25549),
(119331, 'deDE', '', 'Hochlord! Hier drüben!', 25549),
(119330, 'deDE', '', 'Ich glaube, sie will uns helfen. Schaut Euch ihre Schwinge an – Oh! Vielen Dank!', 25549),
(119329, 'deDE', 'Im Namen des Lichts seid Ihr erneut im Kampf geboren!', 'Im Namen des Lichts seid Ihr erneut im Kampf geboren!', 25549),
(119328, 'deDE', '', 'Ich bin froh, dass Ohn''ahra uns ihren Segen gewährt. Ich hatte Angst, die Verbrechen der Bluttotem hätten sie erzürnt. Brechen wir nach Sturmheim auf!', 25549),
(119327, 'deDE', 'Erhebt Euch, Champion!', 'Erhebt Euch, Champion!', 25549),
(119326, 'deDE', '', 'Sie fliegt weiter! Ohn''ahra will, dass Ihr ihr folgt.', 25549),
(119325, 'deDE', 'Ich überbringe dringende Neuigkeiten, mein König. Ihr seid von Gefahren umzingelt!', '', 25549),
(119324, 'deDE', '', 'Vielen Dank. Wir konnten das heilige Erbstück meines Volkes nicht einem solchen Ungeheuer überlassen!', 25549),
(119323, 'deDE', 'Das Monster wird für diese Entweihung bezahlen!', '', 25549),
(119322, 'deDE', 'Die Legion hat das Verlies der Wächterinnen auf der Suche nach Fürst Illidans Leichnam überrannt. Gul''dan hat ihn mitgenommen.', '', 25549),
(119321, 'deDE', '', 'Ich verstehe, Geliebter. Aber wenn Maiev sie freigelassen hat, muss die Lage noch verzweifelter sein, als wir wissen.', 25549),
(119320, 'deDE', 'Die Illidari in unseren Reihen sind mir nicht geheuer. Ihresgleichen waren seit dem Sturz meines Bruders weggeschlossen.', '', 25549),
(119319, 'deDE', 'Wer seid Ihr? Was hat das zu bedeuten?', '', 25549),
(119318, 'deDE', 'Wartet... seid das etwa Ihr? Hah! Ihr seid weit gekommen. Erst habt Ihr mir dabei geholfen, Loken zu besiegen, und nun führt Ihr Odyns Armeen an!', '', 25549),
(119317, 'deDE', '', 'Bereitet Euch auf die Schlacht vor. Nicht einmal die Valarjar wagen sich so nah an Helyas Reich heran.', 25549),
(119316, 'deDE', 'Hauptmann! Ihr müsst Euch jetzt ausruhen. Und wenn Ihr nicht hört, lasse ich den Dämon holen, damit er Euch zusammenflickt!', 'Hauptmann! Ihr müsst Euch jetzt ausruhen. Und wenn Ihr nicht hört, lasse ich den Dämon holen, damit er Euch zusammenflickt!', 25549),
(119314, 'deDE', 'Ihr müsst Euch ausruhen, und Eure Soldaten sind gut ausgebildet. Jetzt haltet still.', 'Ihr müsst Euch ausruhen, und Eure Soldaten sind gut ausgebildet. Jetzt haltet still.', 25549),
(119313, 'deDE', 'Ihr müsst das ihnen überlassen! Das ist jetzt ihr Kampf!', 'Ihr müsst das ihnen überlassen! Das ist jetzt ihr Kampf!', 25549),
(119312, 'deDE', 'Schluss jetzt! Von all dem Gebrüll wird es nur schlimmer!', 'Schluss jetzt! Von all dem Gebrüll wird es nur schlimmer!', 25549),
(119311, 'deDE', 'Hört auf, zu maulen! Eure Soldaten sind gut ausgebildet. Sie werden es schaffen.', 'Hört auf, zu maulen! Eure Soldaten sind gut ausgebildet. Sie werden es schaffen.', 25549),
(119310, 'deDE', 'Hauptmann, was macht Ihr denn da? Ihr könnt doch in dem Zustand nicht kämpfen.', 'Hauptmann, was macht Ihr denn da? Ihr könnt doch in dem Zustand nicht kämpfen.', 25549),
(119309, 'deDE', '', 'Odyns Tapferkeit wird nur von seinem Appetit übertroffen. Ein wahrer Krieger.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(119308, 'deDE', 'Zeigt ihnen, was Ihr könnt! Für die Allianz!', '', 25549),
(119307, 'deDE', 'Eins kann ich Euch versichern, das war heute nicht das letzte Exemplar, das wir erledigen!', '', 25549),
(119306, 'deDE', 'Haltet sie auf Trab! Lasst sie nicht aus den Augen!', '', 25549),
(119305, 'deDE', 'Da will sich jemand wohl nicht geschlagen geben!', '', 25549),
(119304, 'deDE', '', 'Ich konnte mich kurz befreien. Bitte, wer auch immer dies findet, Ihr seid unsere einzige Hoffnung auf Rettung.', 25549),
(119303, 'deDE', '', 'Wir leben noch, aber sie bringen uns durch das Portal... auf ihre Heimatwelt. Was befindet sich bloß auf der anderen Seite?', 25549),
(119302, 'deDE', '', 'Wir haben die Durchtriebenheit der Legion unterschätzt! Als wir angriffen, wurde das Portal plötzlich aktiv. Balnazzar kam und rieb unsere Verteidigung auf.', 25549),
(119301, 'deDE', '', 'Wir werden morgen angreifen. Möge das Licht uns leiten.', 25549),
(119300, 'deDE', '', 'Die Legion hat unsere Anwesenheit noch nicht bemerkt. Ihre Anführerin, Brutkönigin Aramis, inspiziert jeden Tag das Lager.', 25549),
(119299, 'deDE', '', 'Die Priester suchen ebenfalls nach Balnazzar. Ihr Anführer, Prophet Velen, sah in einer Vision, wie der Schreckenslord Zerstörung über Azeroth niederregnen ließ.', 25549),
(119298, 'deDE', '', 'Wie versprochen hat Delas Priester der Konklave für die Schlacht mitgebracht. Sie fügen sich sehr gut in unsere Truppen ein.', 25549),
(119297, 'deDE', '', 'Wir haben den Teufelsfeuervorstoß kurz nach unserem Aufbruch von der Kapelle erreicht. Dieses Tagebuch erzählt von der Reise.', 25549),
(119296, 'deDE', 'Irgendwie muss man das Herz vor der Unbeständigkeit der Legionsmagie schützen können. Ich habe eine Idee.', '', 25549),
(119295, 'deDE', 'Die Matrix destabilisiert sich!', '', 25549),
(119294, 'deDE', '', 'Ishnu-talah Kaldorei!', 25549),
(119293, 'deDE', '', 'Elun''falah shalar.', 25549),
(119292, 'deDE', 'Endlich gute Nachrichten an diesem Tag der Trauer.', '', 25549),
(119291, 'deDE', '', 'Trefft mich im Sanktum der Ordnung. Ich muss die Zeremonie vorbereiten.', 25549),
(119290, 'deDE', 'Was wisst Ihr über die Kvaldir?', 'Was wisst Ihr über die Kvaldir?', 25549),
(119289, 'deDE', 'Helyas Aufgabe ist es, über die Seelen der Unwürdigen zu wachen, denn wer ruhmreich stirbt, wird zu Odyn an die Pforte der Tapferkeit geschickt, um für die letzte Schlacht zu trainieren. Doch Helya ist eine eifersüchtige Hexe und die Seelen, die man ihr überlässt, reichen ihr nicht.\n\nAlso erschuf sie die Kvaldir. Diese waren einst mächtige Vrykul, die jetzt durch ihre widerwärtige Magie zerrissen und verderbt sind. Sie dienen ihr bis in alle Ewigkeit und plündern die Seelen der Lebenden, um ihre unersättliche Gier nach Tod zu befriedigen.\n\nSie sind eine wahre Pest, Fremdling. Nichts weiter.', '', 25549),
(119288, 'deDE', 'Wisst Ihr, was Ihr hier seht, kleiner Fremdling? Das Schicksal der Wellenskorn, die einst mehr Glück mit den Wellen hatten.\n\nDer Zorn von Helya, der grässlichen Meereshexe, verschlang ihre Flotten und ihre widerlichen Nebel brachen die mächtigsten aller Vrykul. Die Jarls hatten keine andere Wahl, als das Meer aufzugeben, da ihre Äxte und Schwerter Nebel und Salz nicht zu besiegen vermögen.', '', 25549),
(119287, 'deDE', '', 'Ich weiß nicht. Doch unser Freund verdient einen Versuch.', 25549),
(119286, 'deDE', 'Seid Ihr sicher, dass das funktioniert, Syrana?', '', 25549),
(119285, 'deDE', '', 'Lasst uns mit dem Ritual beginnen.', 25549),
(119284, 'deDE', 'Ich werde Euer Elfending zerbrechen!', '', 25549),
(119283, 'deDE', '', 'Wir sind wenige, doch die Legion wird noch lernen, die Wache zu fürchten.', 25549),
(119282, 'deDE', '', 'Perfekt. Sollen wir die Zauberformel testen?', 25549),
(119281, 'deDE', '%s beugt sich Eurem Willen.', '%s beugt sich Eurem Willen.', 25549),
(119280, 'deDE', 'Ja, ja, wir haben alles. Mit dem richtigen Ritual können wir das Herz mit der mächtigsten Magie erfüllen!', '', 25549),
(119279, 'deDE', 'Es ist Zeit. Bringt uns nach Niskara.', 'Es ist Zeit. Bringt uns nach Niskara.', 25549),
(119278, 'deDE', 'Nicht nur die Legion kann durch den Kosmos greifen, um Gegner anzugreifen.$B$BIhr müsst es nur sagen, $n. Ich werde von dieser Seite aus ein Tor offenhalten.', '', 25549),
(119277, 'deDE', 'Genau die! Ich spüre sie schon von hier!', '', 25549),
(119276, 'deDE', 'Kommt mit mir. Wir fliegen direkt nach Pandaria.', '', 25549),
(119275, 'deDE', '', 'Das war noch nicht ganz die richtige Lösung, was? Versucht, die Kiste noch einmal zu aktivieren, um es erneut zu versuchen.', 25549),
(119274, 'deDE', 'Fragt nach der Rolle von Elun''dris. Nur sie enthält die Informationen, die wir brauchen!', '', 25549),
(119273, 'deDE', 'Seid wachsam. Das Vertrauen der Nachtsüchtigen zu gewinnen kann dauern.', '', 25549),
(119272, 'deDE', 'Achtet auf Eure Schritte. Die Mogu dieser Ruinen sind seit langem tot, doch ihre Geister verbleiben... ebenso wie ihre Fallen.', '', 25549),
(119271, 'deDE', 'Kommt zu Furog, kleine Elfenmonster!', '', 25549),
(119270, 'deDE', 'Wir schulden Euch viel für die Evakuierung unserer Festung. Wie können wir uns revanchieren?', '', 25549),
(119269, 'deDE', 'Ihr habt der Wache einen großen Dienst erwiesen, $p. Wie können wir Euch helfen?', '', 25549),
(119268, 'deDE', '', 'Wir nehmen Eure Hilfe gern in Anspruch, Delas. Das Licht ist heller, wenn es nicht alleine strahlt.', 25549),
(119267, 'deDE', '', 'Gestattet mir, Euch zu begleiten, Schwester. Ich schicke dem Netherlichttempel eine Nachricht und bitte um Verstärkung vom Priesterorden.', 25549),
(119266, 'deDE', '', 'Der Teufelsfeuervorstoß muss zerstört werden. Mit Eurer Zustimmung werden Arator und ich uns darum kümmern.', 25549),
(119265, 'deDE', '', 'Ishnu''alah, Schwester. Danke für Euren herzlichen Empfang.', 25549),
(119264, 'deDE', '', 'Hochlord, Ihr seid zurück. Und Delas mit Euch! Es ist lange her, mein Freund.', 25549),
(119263, 'deDE', 'HEY! Könnte mal jemand meine Wunden heilen? Ich weiß, dass einer von Euch des Heilens mächtig ist!', '', 25549),
(119262, 'deDE', 'Sagt meinen Kindern, ich hätte mein Bestes versucht, doch da es keine Helden gab, die meine Wunden heilten, bin ich gestorben.', '', 25549),
(119261, 'deDE', 'Ich werde weiterkämpfen, bis mein Körper zusammenbricht!', '', 25549),
(119260, 'deDE', 'Wir haben den Kodex der Befehlsgewalt entschlüsselt.', 'Wir haben den Kodex der Befehlsgewalt entschlüsselt.', 25549),
(119259, 'deDE', 'Ich werde diese Wunden nicht mehr lange überleben.', '', 25549),
(119258, 'deDE', 'Ich bin schwer verletzt!', '', 25549),
(119257, 'deDE', 'Bitte kümmert Euch um meine Wunden, damit ich weiterkämpfen kann!', '', 25549),
(119256, 'deDE', 'Ich brauche Eure Hilfe, $gHeiler:Heilerin;!', '', 25549),
(119255, 'deDE', 'Ich brauche Heilung!', '', 25549),
(119254, 'deDE', 'Ich bin verletzt!', '', 25549),
(119253, 'deDE', 'Spürt das reinigende Feuer!', '', 25549),
(119252, 'deDE', '', 'Passt auf, wo Ihr hintretet...', 25549),
(119251, 'deDE', '', 'Stirb, Wurm!', 25549),
(119250, 'deDE', 'Ihr habt einen Jeder-gegen-Jeden-PvP-Bereich betreten!', 'Ihr habt einen Jeder-gegen-Jeden-PvP-Bereich betreten!', 25549),
(119243, 'deDE', 'Das also hat sie vor? Tapferes Mädchen. Ich würde gerne helfen, aber...', '', 25549),
(119242, 'deDE', 'Ihr seht irgendwie merkwürdig aus. Ist etwas geschehen? Habt Ihr Bedarf für mein... Können?\n\n<Arluin lächelt faul.>', '', 25549),
(119241, 'deDE', 'Wir brauchen Eure Hilfe, um ein paar Adelshäuser davon zu "überzeugen", Ly''leths Wahl zur Beraterin zu unterstützen. Seid Ihr dabei?', 'Wir brauchen Eure Hilfe, um ein paar Adelshäuser davon zu "überzeugen", Ly''leths Wahl zur Beraterin zu unterstützen. Seid Ihr dabei?', 25549),
(119237, 'deDE', 'Ich werde Vanthir besuchen, wenn ich Zeit finde. Kümmert Euch um Euren Kram, wenn Ihr nichts für mich habt.', '', 25549),
(119235, 'deDE', 'Diese Gassen sind gefährlich. Man weiß nie, wer einem in die Taschen greift.', '', 25549),
(119234, 'deDE', 'Ich weiß, Ihr liebt mein charmantes Verhalten, doch Ihr solltet wirklich nicht hier sein, wenn Ihr nichts Geschäftliches mit mir zu bereden habt.', '', 25549),
(119233, 'deDE', 'Wenn Ihr etwas seht, sagt es jemanden. Nur nicht mir.', '', 25549),
(119232, 'deDE', 'Meine Klingen! Dieses Blut... ist ganz frisch! Jemand muss die anderen warnen!', '', 25549),
(119231, 'deDE', 'Was... Was ist das?! Wie konnte ich... Haltet sie auf! Ihr müsst sie aufhalten!', '', 25549),
(119230, 'deDE', 'Ich habe so etwas noch nie im Leben gesehen! Ich verstehe das nicht...', '', 25549),
(119229, 'deDE', 'Seht nur, was sie getan haben! Ihr müsst sie aufhalten!', 'Seht nur, was sie getan haben! Ihr müsst sie aufhalten!', 25549),
(119228, 'deDE', 'Ich konnte nichts für sie tun!', 'Ich konnte nichts für sie tun!', 25549),
(119227, 'deDE', 'Dieses Ding war das! Befreit unser Land von diesen Dämonen!', 'Dieses Ding war das! Befreit unser Land von diesen Dämonen!', 25549),
(119226, 'deDE', 'Wir müssen uns unser Land zurückholen!', 'Wir müssen uns unser Land zurückholen!', 25549),
(119225, 'deDE', 'Schaut mich nur an... Schaut, was sie getan haben! Ihr müsst dieser Bedrohung ein Ende setzen!', 'Schaut mich nur an... Schaut, was sie getan haben! Ihr müsst dieser Bedrohung ein Ende setzen!', 25549),
(119224, 'deDE', 'Ihr müsst diese Gefahr beseitigen, $n!', 'Ihr müsst diese Gefahr beseitigen, $n!', 25549),
(119223, 'deDE', '|TInterface\\Icons\\INV_Misc_Herb_Liferoot_Stem:20|t%s wirkt |cFFFF0000|Hspell:212786|h[Entwurzeln]|h|r. Nehmt Euch vor Garststachelsetzlingen in Acht!', '', 25549),
(119222, 'deDE', '', 'Wir sehen uns in der Kammer der Schatten, $n.', 25549),
(119221, 'deDE', 'Danke.', '', 25549),
(119220, 'deDE', '', 'Ich bringe Mathias durch die Kanalisation in Sicherheit.', 25549),
(119219, 'deDE', 'Das ist Wahnsinn! Absoluter Wahnsinn!', '', 25549),
(119218, 'deDE', '', 'Ich konnte nichts tun! Sie... Sie haben ihn einfach umgebracht!', 25549),
(119217, 'deDE', 'Shannon... Geht es ihr gut? Ihr müsst den anderen helfen!', '', 25549),
(119216, 'deDE', '', 'Geht! Verschwindet so weit wie möglich von hier!', 25549),
(119215, 'deDE', '', 'Beauxbeaux. Was haben sie getan?!', 25549),
(119212, 'deDE', 'Das Schwarze Tor... tretet durch.', '', 25549),
(119211, 'deDE', 'Was ist das?', '', 25549),
(119210, 'deDE', 'Endlich, die Vier Reiter erhalten ihren Anführer...', '', 25549),
(119209, 'deDE', 'Wir werden unsere so tapfer Gefallenen von den Toten zurückholen, aber die Taten der Schwarzen Klinge bleiben unvergessen.', '', 25549),
(119208, 'deDE', 'Es wird Zeit, dass Ihr diesen Ort verlasst und nie wieder zurückkehrt.', '', 25549),
(119207, 'deDE', 'Dies Bürde wird stets auf unseren Schultern lasten, mein Sohn.', '', 25549),
(119206, 'deDE', 'Ich werde nicht tatenlos zusehen, wie sich mein Sohn in ein Monster verwandelt!', '', 25549),
(119205, 'deDE', 'Gut. Dann endet Euer unheiliger Kreuzzug hier und jetzt. Die Vier Reiter werden niemals zurückkehren.', '', 25549),
(119204, 'deDE', 'Schaut, was Ihr angerichtet habt! Das Blut unserer tapferen Verbündeten besudelt diese heilige Kapelle. Blut, das Ihr vergossen habt!', '', 25549),
(119203, 'deDE', 'Darion, mein Sohn! Was hat das zu bedeuten?', '', 25549),
(119202, 'deDE', '', 'Solch ungeheure Macht... Wie ist das möglich?', 25549),
(119201, 'deDE', '', 'Im Namen des Lichts, seid geläutert!', 25549),
(119200, 'deDE', '', 'Ich kann das Schloss nicht knacken. $p, Ihr seid dran.', 25549),
(119199, 'deDE', 'Was ist los, Taoshi?', '', 25549),
(119198, 'deDE', '', 'So, nur noch ein Schloss!', 25549),
(119197, 'deDE', '', 'Dazu werdet Ihr bald genug die Chance haben, Mathias.', 25549),
(119196, 'deDE', 'Holt mich hier raus, damit ich helfen kann.', '', 25549),
(119195, 'deDE', 'Lasst uns mit Thalrenus und den Seinen sprechen. Nur mit ihrem Wissen können wir das Herz noch weiter verstärken.', '', 25549),
(119194, 'deDE', 'Nur die Mondwachen kennen die alte Magie, mit deren Hilfe wir das Herz noch weiter verstärken können. Ihr müsst sie retten.', '', 25549),
(119193, 'deDE', 'Nur wenige sind so weit in die Dunkelheit vorgedrungen und zurückgekehrt.', '', 25549),
(119192, 'deDE', 'Taoshi, öffnet die Schlösser, ich kümmere mich um die Dämonen.', 'Taoshi, öffnet die Schlösser, ich kümmere mich um die Dämonen.', 25549),
(119191, 'deDE', '', 'Wir müssen Shaw aus diesem Käfig befreien.', 25549),
(119190, 'deDE', 'Danke für Eure Hilfe, Senegos. Ich hoffe, dass sich unsere Pfade eines Tages wieder kreuzen.', '', 25549),
(119189, 'deDE', 'Ich fürchte, dass Ihr das Ausmaß ihrer Verderbtheit nicht kennt, Bruder. Wir müssen weiterhin alles nur Mögliche tun, sonst drohen wir zu scheitern.', '', 25549),
(119188, 'deDE', 'Wir müssen Beistand leisten, Kalecgos. Die Macht ist zu groß!', '', 25549),
(119185, 'deDE', 'Bleibt einfach nicht zu lange dort drinnen, in Ordnung?', '', 25549),
(119184, 'deDE', 'Macht Euch bereit, $p.', '', 25549),
(119183, 'deDE', 'Ein Mitglied der Ungekrönten. Ich hatte nichts Geringeres erwartet.', '', 25549),
(119182, 'deDE', '...Aber wenn darüber irgendjemand lacht, dann SIE.', '', 25549),
(119181, 'deDE', 'Lächerlich! Ein Witz über meinen Lord? Nur ein Wahnsinniger würde es wagen!', '', 25549),
(119180, 'deDE', '', 'Nein, das ist einfach unmöglich...', 25549),
(119179, 'deDE', '', 'Das ist das Symbol von Haus Stelleris... aber das kann nicht sein. Coryn war Ruvens engster Freund...', 25549),
(119178, 'deDE', '...Warum SOLLTE er so etwas tun...?', '', 25549),
(119177, 'deDE', 'Definitiv NICHT! Warum sollte er so etwas tun? Hat er denn keine Ehre?!', '', 25549),
(119176, 'deDE', '', 'Da kommen sie!', 25549),
(119175, 'deDE', 'Auf der Straße erzählt man sich, man hätte ein Silberwappen bei seinem Leichnam entdeckt... Ist das wahr?', 'Auf der Straße erzählt man sich, man hätte ein Silberwappen bei seinem Leichnam entdeckt... Ist das wahr?', 25549),
(119174, 'deDE', 'Ich habe einen geschmacklosen Witz über Ruven gehört, als ich die Familie Stelleris besucht habe. Ich denke nicht, dass Ihr ihn hören wollen würdet...', 'Ich habe einen geschmacklosen Witz über Ruven gehört, als ich die Familie Stelleris besucht habe. Ich denke nicht, dass Ihr ihn hören wollen würdet...', 25549),
(119173, 'deDE', 'Ich habe gehört, dass Coryn Stelleris anfangen soll, die verbleibenden Diener von Dämmermaar zu kaufen... Ist das wahr?', 'Ich habe gehört, dass Coryn Stelleris anfangen soll, die verbleibenden Diener von Dämmermaar zu kaufen... Ist das wahr?', 25549),
(119172, 'deDE', 'Ich verstehe.', 'Ich verstehe.', 25549),
(119171, 'deDE', '', 'Oh, mein armer Ruven...\n\nEr war so ein freches Kind, so voller Stolz. Ich wusste immer, dass er eines Tages große Macht für sich beanspruchen würde.\n\nDoch dies... dies habe ich nicht vorhergesehen. Oh, mein Kind...', 25549),
(119170, 'deDE', 'Mein Lord Ruven hat mir so viel Macht versprochen, wenn er in den Palast kommen würde. Ich glaubte ihm! Machte Pläne!\n\nNun ist er tot und ich kann mich nicht blicken lassen, ohne angestarrt zu werden. Ich schäme mich.\n\nWie konnte jemand wie er nur so tief sinken?', '', 25549),
(119169, 'deDE', 'Ich war der persönliche Diener von Lord Ruven. Jetzt verteile ich nur noch Wein und Süßigkeiten an launischen, verhätschelten Adel ohne wahre Macht oder Einfluss.\n\nErbärmlich.', '', 25549),
(119168, 'deDE', 'Oh, Kalecgos! Das ist erst der Anfang. Nun müssen wir tief in den Alptraum eintauchen.', '', 25549),
(119167, 'deDE', 'Unglaublich! Aber die Macht einer Essenz reicht einfach nicht aus.', '', 25549),
(119166, 'deDE', '', 'Haltet sie mir vom Leib, dann befreie ich den Agenten aus seinem Käfig.', 25549),
(119165, 'deDE', 'Es... es funktioniert!', '', 25549),
(119164, 'deDE', 'Wir haben alles Nötige. Gute Arbeit!', '', 25549),
(119163, 'deDE', 'Verschwindet, $R. Mit Euren närrischen Plänen will ich nichts zu tun haben.', '', 25549),
(119162, 'deDE', 'Interessant.\n\nDonneraan ist dank der Bemühungen des Irdenen Rings zurückgekehrt. Der neue Windlord ist auferstanden und mit ihm solltet Ihr über diese elenden Schöpfungen sprechen.\n\nDoch selbst dann wird eine einzige Fessel dem Lord des Himmelswalls nicht viel bringen.', '', 25549),
(119161, 'deDE', 'Ich habe kein Verlangen, den Windlord einzusperren. Ich möchte eine Vereinbarung mit ihm treffen.', 'Ich habe kein Verlangen, den Windlord einzusperren. Ich möchte eine Vereinbarung mit ihm treffen.', 25549),
(119160, 'deDE', 'Genug! Ich werde mich selbst um Euch kümmern.', '', 25549),
(119159, 'deDE', 'Was würde man benötigen, um eine Audienz beim Windlord zu erhalten?', 'Was würde man benötigen, um eine Audienz beim Windlord zu erhalten?', 25549),
(119158, 'deDE', 'Kühn, $R. Die Elementarlords sind nicht gerade für ihre Großzügigkeit bekannt.\n\nDennoch, wenn Ihr beide Fesseln finden solltet, und dazu noch ein Erz, das mächtig genug ist, um sie in etwas Nutzbares zu formen, dann werde ich für Euch eine Audienz bei Donneraan dem Windlord arrangieren.\n\nNutzt die Zeit bis dahin, um die Klugheit des Treffens zu überdenken. Ich würde es verstehen, wenn Ihr nicht zurückkehren solltet.', '', 25549),
(119157, 'deDE', 'Eure Fesseln interessieren mich nicht.\n\nDonneraan ist dank der Bemühungen des Irdenen Rings zurückgekehrt. Der neue Windlord ist auferstanden. Mit ihm solltet Ihr über diese elenden Schöpfungen sprechen.\n\nDoch selbst dann wird eine einzige Fessel nicht viel gegen den Windlord bringen.', '', 25549),
(119156, 'deDE', 'Bei der Lebensbinderin... Ich dachte, das Herz wäre nur eine Legende.', '', 25549),
(119155, 'deDE', 'Nun seht Euch an, was Ihr angerichtet habt. Ihr wolltet ja nicht hören, oder?', '', 25549),
(119154, 'deDE', '...Ich habe Euch enttäuscht, Lord Detheroc...', '', 25549),
(119153, 'deDE', 'Nun... Ich hoffe, Ihr esst gerne rohen Fisch, $n.', '', 25549),
(119152, 'deDE', 'Stählt Euer Herz, junges Wesen. Niemand ist sicher vor dem Einfluss des Alptraums.', '', 25549),
(119151, 'deDE', 'Ich habe keine Angst vor dem Windlord. Solange ich diese Fessel habe, sollte er mich fürchten.', 'Ich habe keine Angst vor dem Windlord. Solange ich diese Fessel habe, sollte er mich fürchten.', 25549),
(119150, 'deDE', 'Ihr besitzt eine mächtige Fessel von den Angehörigen des Feuerlords. Das sind keine Spielzeuge, $R. Solche Fesseln bedrohen selbst die großen Elementarlords. Es ist unvorstellbar gefährlich, so etwas zu besitzen.\n\nWollt Ihr den Windlord mit diesen Fesseln einfangen? Oder habt Ihr etwas anderes vor?', '', 25549),
(119149, 'deDE', 'Sprecht mich an, sobald Ihr Eure Geschäfte hier abgeschlossen habt, damit wir diesen Ort verlassen können.', '', 25549),
(119148, 'deDE', 'Eichenherz beschützte den großen Baum unzählige Jahre lang und wankte nicht ein Mal. Ein tragisches Ende.', '', 25549),
(119147, 'deDE', 'Passt auf! Azsharas Diener werden das Herz nicht kampflos aufgeben.', '', 25549),
(119146, 'deDE', '<Er mustert Euch misstrauisch von Kopf bis Fuß.>', '', 25549),
(119145, 'deDE', 'Ich weiß es nicht... Ich bin irgendwie... hier heruntergefallen.', 'Ich weiß es nicht... Ich bin irgendwie... hier heruntergefallen.', 25549),
(119144, 'deDE', 'Fast wäre es mir anders ergangen, hätte Euer Freund nicht eingegriffen.', '', 25549),
(119143, 'deDE', 'Ich bin froh, Euch gesund und munter wiederzusehen, Senegos.', '', 25549),
(119142, 'deDE', '', 'Worte sind Waffen.', 25549),
(119141, 'deDE', '', 'Das Haus Lunastre steht über allem.', 25549),
(119140, 'deDE', '', 'Wollt Ihr mich etwa ärgern?!', 25549),
(119139, 'deDE', '', 'Und tschüss.', 25549),
(119138, 'deDE', '', 'Geht jetzt.', 25549),
(119137, 'deDE', '', 'Beschämend.', 25549),
(119136, 'deDE', '', 'Was?', 25549),
(119135, 'deDE', '', 'Sagt schon.', 25549),
(119134, 'deDE', '', 'Bringen wir''s hinter uns.', 25549),
(119133, 'deDE', 'Beschämend.', '', 25549),
(119132, 'deDE', 'Geht jetzt.', '', 25549),
(119131, 'deDE', 'Und tschüss.', '', 25549),
(119130, 'deDE', 'Bringen wir''s hinter uns.', '', 25549),
(119129, 'deDE', 'Sagt schon.', '', 25549),
(119128, 'deDE', 'Was?', '', 25549),
(119127, 'deDE', 'Hinfort mit Euch! Ihr habt schon genug Ärger gemacht!', '', 25549),
(119126, 'deDE', 'Man muss auch ernten, was man säht.', '', 25549),
(119125, 'deDE', 'Überdenkt Euren Weg.', '', 25549),
(119124, 'deDE', 'Ich spüre Eure Unruhe.', '', 25549),
(119122, 'deDE', 'Beruhigt Euch.', '', 25549),
(119119, 'deDE', 'Ande''thoras-ethil.', '', 25549),
(119116, 'deDE', 'Ich weiß, dass jemand Ailen Astravar hierhergebracht hat. Sagt mir, wo er ist.', 'Ich weiß, dass jemand Ailen Astravar hierhergebracht hat. Sagt mir, wo er ist.', 25549),
(119115, 'deDE', 'Sucht Harmonie.', '', 25549),
(119112, 'deDE', 'Lebt wohl.', '', 25549),
(119107, 'deDE', 'Verfolgt Euer Ziel.', '', 25549),
(119106, 'deDE', 'Und alle werden sich im Lichte vereinen.', '', 25549),
(119105, 'deDE', 'Längst vergessene Schatten erheben sich!', '', 25549),
(119104, 'deDE', 'Alte Feinde werden zu Verbündeten.', '', 25549),
(119103, 'deDE', 'Jetzt wird alles klar.', '', 25549),
(119102, 'deDE', 'Ich kenne meinen Weg.', '', 25549),
(119101, 'deDE', 'Ich sehe einen Pfad, der zu unserem Sieg führt! Ihr seid dort,... wandelnd im Licht zeigt Ihr uns den Weg.', '', 25549),
(119100, 'deDE', 'Neeeiiin!', '', 25549),
(119099, 'deDE', 'Dies ist unser Schicksal... wenn nicht...', '', 25549),
(119098, 'deDE', 'Das ist unser Schicksal. Wir sind dazu bestimmt, durch die Hand des Schreckenslords Balnazzar zu sterben.', '', 25549),
(119097, 'deDE', 'Durch seine Hand wird der Orden fallen, und jeder der unsrigen wird sterben.', '', 25549),
(119096, 'deDE', 'Eine große Dunkelheit zieht über dem Netherlichttempel herauf. Es ist der Schatten der Brennenden Legion. Bereit, zuzuschlagen.', '', 25549),
(119095, 'deDE', 'Schwer ist unsere Bürde.', '', 25549),
(119094, 'deDE', 'Grüße.', '', 25549),
(119093, 'deDE', 'Ishnu-alah.', '', 25549),
(119092, 'deDE', '', 'Ich komme gerne zum Nachdenken hierher. In der Gegenwart der Statue fühle ich, wie die Ruhe über mich kommt.', 25549),
(119091, 'deDE', '', 'Seid gegrüßt, $C. Möge das Licht Euren Weg erleuchten.', 25549),
(119087, 'deDE', 'Meine Eule scheint Euch zu mögen.', '', 25549),
(119086, 'deDE', 'Das reicht! Los, Kal! Auf die Augen!', '', 25549),
(119085, 'deDE', '<grummel> Stark sein... Stark sein...', '', 25549),
(119084, 'deDE', 'Tausende Jahre Übung haben mich diszipliniert. Eure ärmlichen Belästigungen gleiten von mir ab wie der Morgentau von den Blättern.', '', 25549),
(119083, 'deDE', 'Wir dürfen nicht aufhören zu kämpfen. Weitermachen!', 'Wir dürfen nicht aufhören zu kämpfen. Weitermachen!', 25549),
(119082, 'deDE', 'Ich weiß Eure Hilfe zu schätzen. Wenn Ihr mich jetzt bitte entschuldigen wollt, ich muss weitermachen.', 'Ich weiß Eure Hilfe zu schätzen. Wenn Ihr mich jetzt bitte entschuldigen wollt, ich muss weitermachen.', 25549),
(119081, 'deDE', 'Ich komme schon klar. Los jetzt!', 'Ich komme schon klar. Los jetzt!', 25549),
(119080, 'deDE', 'Ihr wollt mich provozieren? Vergesst es.', '', 25549),
(119079, 'deDE', 'Haltet die Klingen sauber.', '', 25549),
(119078, 'deDE', 'An''ratha adore.', '', 25549),
(119077, 'deDE', 'Seid umsichtig.', '', 25549),
(119076, 'deDE', 'Lebt wohl.', '', 25549),
(119075, 'deDE', 'Nett sein oder stark sein.', '', 25549),
(119074, 'deDE', 'Die Shal''dorei leiden.', '', 25549),
(119073, 'deDE', 'Ein weiterer Eindringling? Wagt es nicht, Euch in Angelegenheiten des Hochbergs einzumischen!', '', 25549),
(119072, 'deDE', 'Ich schwöre, Suramar zu beschützen.', '', 25549),
(119071, 'deDE', 'Wenn dieser starrsinnige Geist nur gehorchen würde!', '', 25549),
(119070, 'deDE', 'Es gibt keine Ordnung mehr.', '', 25549),
(119069, 'deDE', 'Aran''arcana.', '', 25549),
(119068, 'deDE', 'Seid gegrüßt.', '', 25549),
(119067, 'deDE', 'Euer Stamm hatte genug Zeit, den Speer zu finden, doch Ihr habt versagt. Ich werde Fangklaue zurückbringen... für die Bluttotems!', '', 25549),
(119066, 'deDE', '', 'Warum tut Ihr das? Ich weiß, der Frieden zwischen uns war stets brüchig, aber...', 25549),
(119065, 'deDE', '', 'Ich kann dieses "mehr Energie!" nicht mehr hören. Der Arkus ist kein Förderband mit Waren drauf, sondern eine Reihe von Leitungen!', 25549),
(119064, 'deDE', '', 'Wo ich herkomme, kann man sich so etwas nicht erlauben...', 25549),
(119063, 'deDE', '', 'Ist das eine Art primitives Ritual, jemanden zu provozieren, bis er die Geduld verliert?', 25549),
(119062, 'deDE', '', 'Val-TWAH. Twwahhh! Das "R" wird nicht... Ach, nennt mich doch, wie Ihr wollt.', 25549),
(119061, 'deDE', '', '<Räusper.> Immer noch da?', 25549),
(119060, 'deDE', '', 'Lebt wohl.', 25549),
(119059, 'deDE', '', 'Aran''arcana.', 25549),
(119058, 'deDE', 'Guter Schuss, $n. Das reicht für heute.', '', 25549),
(119057, 'deDE', 'Na ja, genug von den Schullektionen. Geht dort hinein und versucht, die Ziele zu treffen, die ich markiert habe. Ich bin wieder hier drüben, um Daten zu sammeln.', '', 25549),
(119056, 'deDE', 'Und wenn ich "werfen" sage, meine ich natürlich verschießen. Mit Feuer.', '', 25549),
(119055, 'deDE', 'Ihr müsst wissen, dass es bei Magie nicht allein darum geht, Feuerbälle zu beschwören und sie auf die Gegner zu schleudern. Manchmal muss man auch Felsen werfen, richtig GROSSE Felsen.', '', 25549),
(119054, 'deDE', 'Seid gegrüßt, $n. Würdet Ihr mir bei etwas Wissenschaft behilflich sein?', '', 25549),
(119053, 'deDE', '', 'Das Arkane obsiegt.', 25549),
(119052, 'deDE', '', 'Wahre Hilfe ist so selten.', 25549),
(119051, 'deDE', '', 'Verschwindet.', 25549),
(119050, 'deDE', '', 'Sprecht ruhig.', 25549),
(119049, 'deDE', 'Eure Hilfe wird dafür sorgen, dass wir diesen Krieg gewinnen.', 'Eure Hilfe wird dafür sorgen, dass wir diesen Krieg gewinnen.', 25549),
(119048, 'deDE', 'Ich stehe in Eurer Schuld.', 'Ich stehe in Eurer Schuld.', 25549),
(119047, 'deDE', 'Ich danke Euch, $gPriester:Priesterin;.', 'Ich danke Euch, $gPriester:Priesterin;.', 25549),
(119046, 'deDE', '', 'Shal''assan torah.', 25549),
(119045, 'deDE', '', 'Warum hat Elisande unsere Magie angezweifelt?', 25549),
(119044, 'deDE', '', 'Die Macht wartet. Wir müssen nur zugreifen.', 25549),
(119043, 'deDE', '', 'Irgendetwas stimmt nicht. Das ist seltsam... Vorsicht!', 25549),
(119042, 'deDE', '', 'Hin und wieder machen sich tapfere Jäger auf die Suche nach Fangklaue. Sie bitten den Adlergeist um seinen Segen und begeben sich auf die Jagd. Doch leider endeten all diese Unternehmungen gleich: mit dem Tod.', 25549),
(119041, 'deDE', '', 'Ja?', 25549),
(119040, 'deDE', '<Seufzt.> Jetzt habt Ihr mich zum Fluchen gebracht.', '', 25549),
(119039, 'deDE', '', 'Ausgezeichnet! Diese Information wird für unsere Forschung von unschätzbarem Wert sein.', 25549),
(119038, 'deDE', '', 'Geht zu der Kiste und interagiert mit ihr, um das Rätsel zu beginnen.', 25549),
(119037, 'deDE', '', 'Eine faszinierende Entdeckung. Dieses Gerät scheint durch eine Art Rätsel gesichert zu sein.', 25549),
(119036, 'deDE', 'Oh, zischt schon ab!', '', 25549),
(119035, 'deDE', 'Teleportation gefällig? Vielleicht weit, weit weg von hier?', '', 25549),
(119034, 'deDE', 'Ihr wolltet gerade gehen, oder?', '', 25549),
(119033, 'deDE', 'Prüfen. Beobachten. Wiederholen!', '', 25549),
(119032, 'deDE', 'Folgt dem rechten Weg.', '', 25549),
(119031, 'deDE', 'Tel vallath.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(119030, 'deDE', 'Respektiert die Magie oder sie übermannt Euch.', '', 25549),
(119029, 'deDE', 'Wo soll es denn hingehen?', '', 25549),
(119028, 'deDE', 'Anar-ammenos.', '', 25549),
(119027, 'deDE', 'Was habt Ihr entdeckt?', '', 25549),
(119026, 'deDE', 'Oh, hallo.', '', 25549),
(119025, 'deDE', '', 'Wenn das alles vorbei ist, fahre ich den Schild wieder hoch.', 25549),
(119024, 'deDE', '', '<seufzt> Zehntausend Jahre Paradies. Und jetzt stecke ich hier fest. Mit Euch.', 25549),
(119023, 'deDE', '', 'Zeit zu gehen...', 25549),
(119022, 'deDE', '', 'Sind alle Fremdländer so... eifrig?', 25549),
(119021, 'deDE', '', 'Suramar muss frei sein!', 25549),
(119020, 'deDE', '', 'Ausgezeichnete Arbeit, $n! Ich kann es kaum erwarten, den Manasäbler zu analysieren. Die Luft um ihn herum wird sicher mit Leyenergie angereichert sein!', 25549),
(119019, 'deDE', '', 'Vertraut nicht jedem...', 25549),
(119018, 'deDE', '', 'An''ratha adore.', 25549),
(119017, 'deDE', 'Wo ist der andere hin?', '', 25549),
(119016, 'deDE', '', 'Unsere Isolation ist vorbei.', 25549),
(119015, 'deDE', '', 'Der Nachtbrunnen ruft mich...', 25549),
(119014, 'deDE', '', 'Amüsiert? Gut. Genießt es. Noch.', 25549),
(119013, 'deDE', '', 'Vergesst es. Ich gewinne.', 25549),
(119012, 'deDE', '', 'Wisst Ihr nicht, wer ich bin?', 25549),
(119011, 'deDE', '', 'Lebt wohl.', 25549),
(119010, 'deDE', '', 'Ich werde meinen Vater ehren!', 25549),
(119009, 'deDE', '', 'Das Volk wird sich erheben.', 25549),
(119008, 'deDE', '', 'Ruhm den Shal''dorei!', 25549),
(119007, 'deDE', '', 'Guten Tag.', 25549),
(119006, 'deDE', '', 'Ja?', 25549),
(119005, 'deDE', '', 'Grüße.', 25549),
(119004, 'deDE', '<Dieser Leitfaden scheint von mindestens einem Dutzend verschiedener Wildtiere zerfetzt worden zu sein. Obwohl er mehrfach wieder zusammengeflickt wurde, ist er nicht mehr lesbar. Außerdem riecht er unangenehm nach Moschus.>', '<Dieser Leitfaden scheint von mindestens einem Dutzend verschiedener Wildtiere zerfetzt worden zu sein. Obwohl er mehrfach wieder zusammengeflickt wurde, ist er nicht mehr lesbar. Außerdem riecht er unangenehm nach Moschus.>', 25549),
(119003, 'deDE', 'Dort! Diese Person hat die Explosionen ausgelöst!', '', 25549),
(119002, 'deDE', '', '$n, sie haben Euch entdeckt. Verschwindet!', 25549),
(119001, 'deDE', 'Ich kann Euch helfen, einige wertvolle Gegenstände zu beschaffen.', 'Ich kann Euch helfen, einige wertvolle Gegenstände zu beschaffen.', 25549),
(119000, 'deDE', 'Ich habe früher eine Menge Manatränke hinuntergegluckert. Bin ich zwar nicht stolz drauf, aber ich tat, was ich tun musste!', '', 25549),
(118999, 'deDE', 'Jäger aller Völker arbeiten zusammen... So war das früher aber nicht!', '', 25549),
(118998, 'deDE', 'Die Scherbenwelt hatte ihren Charme. Aber als ich von dieser Hütte hörte, musste ich vorbeikommen, um sie mir mit eigenen Augen anzusehen.', '', 25549),
(118997, 'deDE', 'Ich habe schon viele Jahre Jäger angeleitet. Wenn ich sehe, wie weit wir es gebracht haben, bin ich richtig stolz!', '', 25549),
(118996, 'deDE', '', 'Kehrt dieser unheiligen Mission den Rücken oder stellt Euch der Läuterung durch das Licht!', 25549),
(118995, 'deDE', '', 'Todesritter! Eure Taten hier sind ein Affront gegen alles Heilige dieser Welt!', 25549),
(118994, 'deDE', '', 'Wir sind nur so stark wie unser Wille.', 25549),
(118993, 'deDE', '', 'Ein Tag nach dem anderen.', 25549),
(118992, 'deDE', '|TInterface\\Icons\\spell_mage_temporalshield:20|t |cFFFF0000|Hspell:219815|h[Temporalkugeln]|h|r schweben aus dem Nachtbrunnen!', '|TInterface\\Icons\\spell_mage_temporalshield:20|t |cFFFF0000|Hspell:219815|h[Temporalkugeln]|h|r schweben aus dem Nachtbrunnen!', 25549),
(118991, 'deDE', '', 'Nur noch diese Treppe hinunter. Beeilt Euch, $p!', 25549),
(118990, 'deDE', '', 'Es ist nicht mehr weit.', 25549),
(118989, 'deDE', '', 'Er ist hier drin.', 25549),
(118988, 'deDE', '', 'Wir dürfen keine Zeit verlieren, $p.', 25549),
(118987, 'deDE', '', 'Wir müssen schnell zu Mathias.', 25549),
(118986, 'deDE', '', 'Hier lang, $p.', 25549),
(118985, 'deDE', '', 'Schnell! Es ist nicht mehr weit zu Mathias Shaw.', 25549),
(118984, 'deDE', '', 'Wir müssen schnell und unbemerkt zu Mathias Shaw.', 25549),
(118983, 'deDE', 'Führt mich zu Mathias.', 'Führt mich zu Mathias.', 25549),
(118982, 'deDE', '', 'Mathias Shaw wird in den Hallen der Dunkelung im Süden festgehalten.', 25549),
(118981, 'deDE', 'Es könnte in der Tat möglich sein...', '', 25549),
(118980, 'deDE', 'Ich muss eine Sache regeln, bevor wir nach unten gehen. Ich bin bald zurück.', '', 25549),
(118979, 'deDE', 'Ich brauche einen kräftigen Schluck.', '', 25549),
(118978, 'deDE', 'Tut mir leid, ich schließe gleich.', '', 25549),
(118977, 'deDE', 'Nur durch die Hilfe dieser Helden konnten wir diesen Tag überstehen! Schnell, Brüder und Schwestern, zur Halle des Lichts! Der Prophet braucht uns!', '', 25549),
(118976, 'deDE', 'Ich behalte mir das Recht vor, mir meine Kunden auszusuchen.', '', 25549),
(118975, 'deDE', 'Kämpft vereint! Nur gemeinsam können wir sie besiegen!', '', 25549),
(118974, 'deDE', '%s hat den Zauberstab des wilden Manas gegen $n eingesetzt!', '%s hat den Zauberstab des wilden Manas gegen $n eingesetzt!', 25549),
(118973, 'deDE', 'Passt auf Euch auf.', '', 25549),
(118972, 'deDE', 'Das Mondsichelforum ist rund um die Uhr geöffnet.', '', 25549),
(118971, 'deDE', 'Braucht Ihr irgendetwas?', '', 25549),
(118970, 'deDE', '%s hat einen Kontrakt mit den schurkischen Witwenschwestern geschlossen! Haltet Eure Geldbörsen fest!', '%s hat einen Kontrakt mit den schurkischen Witwenschwestern geschlossen! Haltet Eure Geldbörsen fest!', 25549),
(118969, 'deDE', '%s hat Wichtel beschworen!', '%s hat Wichtel beschworen!', 25549),
(118968, 'deDE', '%s hat die Fledermäuse aufgeweckt! Achtet auf Euren Kopf!', '%s hat die Fledermäuse aufgeweckt! Achtet auf Euren Kopf!', 25549),
(118967, 'deDE', 'Meine Tür steht immer offen.', '', 25549),
(118966, 'deDE', '%s hat die Krokis aus den Rohren der Abwasserkanäle gespült!', '%s hat die Krokis aus den Rohren der Abwasserkanäle gespült!', 25549),
(118965, 'deDE', 'Ihr braucht nur zu fragen.', '', 25549),
(118964, 'deDE', 'Wie kann ich helfen?', '', 25549),
(118963, 'deDE', 'Grüße.', '', 25549),
(118962, 'deDE', '%s hat einige junge mutierte Kriegsschildkröten von Laura Malley gekauft! Kommt und zähmt sie, bevor sie ausreißen!', '%s hat einige junge mutierte Kriegsschildkröten von Laura Malley gekauft! Kommt und zähmt sie, bevor sie ausreißen!', 25549),
(118961, 'deDE', '%s hat überall Köder in den Gewässern vom Schwarzmarkt verteilt! Kommt und angelt Euch ein blindes Auge!', '%s hat überall Köder in den Gewässern vom Schwarzmarkt verteilt! Kommt und angelt Euch ein blindes Auge!', 25549),
(118960, 'deDE', '%s hat eine Kiste mit Rattenhengstharnischen gekauft! Kommt und holt Euch Euer Reittier an der Wachstation ab! Die Ratten bleiben aber nicht ewig bei Euch!', '%s hat eine Kiste mit Rattenhengstharnischen gekauft! Kommt und holt Euch Euer Reittier an der Wachstation ab! Die Ratten bleiben aber nicht ewig bei Euch!', 25549),
(118959, 'deDE', '%s hat ein Bankett bezahlt! Kommt und holt Euch im Gasthaus einen deftigen Happen!', '%s hat ein Bankett bezahlt! Kommt und holt Euch im Gasthaus einen deftigen Happen!', 25549),
(118958, 'deDE', 'Schwertkampf ist nicht meine Spezialität, aber ihre Fähigkeiten haben mich sehr beeindruckt.', '', 25549),
(118957, 'deDE', 'Der Palastgärtner hat sich in eine Pflanze verwandelt?', '', 25549),
(118956, 'deDE', 'Dieser Astronom hielt immer sehr viel von sich. Doch ein guter Magier weiß, dass Intelligenz nicht alles ist!', '', 25549),
(118955, 'deDE', 'Das war für Tirion Fordring, Monster! Auch wenn Krosus ihn nicht eigenhändig getötet hat, war er doch verantwortlich für den Tod unseres Champions.', '', 25549),
(118954, 'deDE', 'Im Dritten Krieg fiel Tichondrius im Kampf gegen Illidan Sturmgrimm. Ich glaube, den Geist des Dämonenjägers freut das erneute leidvolle Ende des Schreckenslords.', '', 25549),
(118953, 'deDE', 'Ich behalte Euch im Auge. Viel Glück!', '', 25549),
(118952, 'deDE', '', 'Das Volk von Suramar schuldet diesen Helden mehr, als es je zurückzahlen kann. Ich werde ihnen bis zum Ende beistehen.', 25549),
(118951, 'deDE', 'Ich werde unsere Stellung hier befestigen. Thalyssra, Eure Unterstützung für unsere Champions ist unersetzlich. Sie brauchen Eure Weisheit in der kommenden Schlacht.', '', 25549),
(118950, 'deDE', 'Die Tore wurden durchbrochen! Wir konnten leider nicht früher kommen, weil wir uns erst durchkämpfen mussten.', '', 25549),
(118949, 'deDE', '', 'Ich hätte nicht Melandrus beauftragen, sondern Euch selbst auslöschen sollen. Wenn ich mit diesen Welpen fertig bin, klebt Euer Blut an meiner Klinge!', 25549),
(118948, 'deDE', '', 'Ihr!', 25549),
(118947, 'deDE', 'Bald können wir den Wert ihres Geschenkes abschätzen. Jetzt ist es Zeit, Gul''dan direkt anzugreifen!', '', 25549),
(118946, 'deDE', '', 'Skawn! Nein! Dafür werdet Ihr büßen!', 25549),
(118945, 'deDE', '', 'Aluriel hat zahllose Nachtgeborene im Schwertkampf unterrichtet. Sie wäre eine wertvolle Verbündete, aber sie hat sich anders entschieden.', 25549),
(118944, 'deDE', '', 'Er ist eben in seiner Arbeit aufgegangen.', 25549),
(118943, 'deDE', '', 'Etraeus hielt sich für so... unübertrefflich. Ich gebe zu, seine Demütigung ist mir eine Freude.', 25549),
(118942, 'deDE', '', 'So sieht man sich wieder, Aluriel.', 25549),
(118941, 'deDE', '', 'Meine Leute mussten für Elisandes Abkommen mit der Legion einen furchtbaren Preis zahlen. Dafür habe ich sie gehasst! Wenn Ihr aber mithilfe ihrer Magie die Legion besiegen könnt, wäre Elisande ein Stück weit rehabilitiert.', 25549),
(118940, 'deDE', '', 'Wir müssen die Legion zurückdrängen, bevor sie noch mehr solcher Abscheulichkeiten entfesseln!', 25549),
(118939, 'deDE', '', 'Ich habe versucht, auszubrechen, aber die Holzstäbe sind zu dick.', 25549),
(118938, 'deDE', '', 'Die Herrschaft der Großmagistrix endet heute! Nehmt ihren Turm ein, meine Freunde! Stürzt sie und befreit mein Volk!', 25549),
(118937, 'deDE', '', 'Die Nachtgeborenen helfen unseren alten und neuen Verbündeten, die Legion zurückzudrängen. Wir teilen ein Schicksal, meine Freunde. Wir retten nicht nur diese Stadt, sondern ganz Azeroth! Tor ilisar''thera''nal!', 25549),
(118936, 'deDE', '', 'Endlich kämpfen wir gemeinsam für die Befreiung von Suramar! Unser Widerstand kann aus den Schatten treten!', 25549),
(118935, 'deDE', '', 'Die Zauberklinge! Wenn sie besiegt ist, werden wir die Palasttore öffnen können!', 25549),
(118934, 'deDE', '', 'Das Palastgelände ist gleich da vorn. Es ist noch stärker befestigt als die unteren Bereiche.', 25549),
(118933, 'deDE', '', 'Dies ist ein großer Tag, meine Freunde. Bis zum Eintreffen der Legion war es Fremden zehntausend Jahre lang untersagt, die Nachtfestung zu betreten.', 25549),
(118932, 'deDE', '', 'Dieser Käfig ist ziemlich stabil, aber der Geist eines Murlocs ist schwach und leicht zu kontrollieren!', 25549),
(118931, 'deDE', '', 'Shanar daloras! Ich weiß nicht, wie so ein Wesen entstehen konnte, aber es ist durchdrungen mit der Essenz des Nachtbrunnens.', 25549),
(118930, 'deDE', '', 'Ihr da, hier her! Ich brauche Eure Hilfe!', 25549),
(118929, 'deDE', '', 'Jetzt liegt das Schicksal meines Volkes in den Händen von Euch... den Fremden. Ihr könnt den furchtbaren Pakt der Königin aufheben.', 25549),
(118928, 'deDE', '', 'Ich danke Euch.', 25549),
(118927, 'deDE', '', 'Ich werde Euch das Fleisch von den Knochen reißen!', 25549),
(118926, 'deDE', '', 'Entbeint sie, mein Liebling!', 25549),
(118925, 'deDE', '', 'Was für eine wahnsinnige Idee, diese Kreatur mit der Macht des Nachtbrunnens zu verstärken! Habt Acht. Wenn diese Monstrosität zur Verteidigung der unteren Bereiche der Zitadelle erschaffen wurde, muss sie besonders tödlich sein.', 25549),
(118924, 'deDE', 'Also, es gibt Zeiten, da denke ich, dass die Bürger uns nicht anständig wertschätzen.', 'Also, es gibt Zeiten, da denke ich, dass die Bürger uns nicht anständig wertschätzen.', 25549),
(118923, 'deDE', 'Wir hatten so lange ein gutes Leben. Warum müssen diese Fremden jetzt Ärger machen?', 'Wir hatten so lange ein gutes Leben. Warum müssen diese Fremden jetzt Ärger machen?', 25549),
(118922, 'deDE', 'Mir macht die Legion nichts aus. Es ist doch schön, auf der Seite der Gewinner zu sein.', 'Mir macht die Legion nichts aus. Es ist doch schön, auf der Seite der Gewinner zu sein.', 25549),
(118921, 'deDE', 'Der Wein ist furchtbar. Melandrus hat ihn wieder verwässert.', 'Der Wein ist furchtbar. Melandrus hat ihn wieder verwässert.', 25549),
(118920, 'deDE', 'Da war eben Aluriel die Zauberklinge. Sie wirkt immer so... zornig.', 'Da war eben Aluriel die Zauberklinge. Sie wirkt immer so... zornig.', 25549),
(118919, 'deDE', 'Wusstet Ihr, dass Estraeus so klug ist, dass sein Kopf dreimal so viel wiegt wie der eines adligen Elfen und sechsmal so viel wie der eines Bürgers?', 'Wusstet Ihr, dass Estraeus so klug ist, dass sein Kopf dreimal so viel wiegt wie der eines adligen Elfen und sechsmal so viel wie der eines Bürgers?', 25549),
(118918, 'deDE', 'Also... ähem... Ruhe und Ordnung sind natürlich wiederhergestellt. Wir sind sicher, dank der Großmagistrix!', 'Also... ähem... Ruhe und Ordnung sind natürlich wiederhergestellt. Wir sind sicher, dank der Großmagistrix!', 25549),
(118917, 'deDE', 'Schweigt! Die Großmagistrix ist vor Ort. Wollt Ihr etwa ihren Zorn wecken?!', 'Schweigt! Die Großmagistrix ist vor Ort. Wollt Ihr etwa ihren Zorn wecken?!', 25549),
(118916, 'deDE', 'Vandros war nur der Anfang. Jeder Adlige in Suramar ist jetzt ein Ziel!', 'Vandros war nur der Anfang. Jeder Adlige in Suramar ist jetzt ein Ziel!', 25549),
(118915, 'deDE', 'Wirklich? Ich dachte, es war ein Aufständischer. Aber Eifersucht klingt ja viel aufregender!', 'Wirklich? Ich dachte, es war ein Aufständischer. Aber Eifersucht klingt ja viel aufregender!', 25549),
(118914, 'deDE', 'Es ging wohl um Eifersucht.', 'Es ging wohl um Eifersucht.', 25549),
(118913, 'deDE', 'Was weiß man über den Mord an Berater Vandros?', 'Was weiß man über den Mord an Berater Vandros?', 25549),
(118912, 'deDE', 'Gnade? Ihr macht wohl Witze?! Nehmt ihnen den Arkwein, dann kommen sie schon angekrochen!', 'Gnade? Ihr macht wohl Witze?! Nehmt ihnen den Arkwein, dann kommen sie schon angekrochen!', 25549),
(118911, 'deDE', 'Das Haus Lunastre hat recht. Man muss dem gemeinen Volk Gnade gewähren, um es zu beherrschen.', 'Das Haus Lunastre hat recht. Man muss dem gemeinen Volk Gnade gewähren, um es zu beherrschen.', 25549),
(118910, 'deDE', 'Ich muss mich derzeit um etwas Wichtiges kümmern, aber wir treffen uns schon bald.', '', 25549),
(118909, 'deDE', 'Selbst wenn. Trotzdem sollte lieber er Berater werden als diese Ly''leth Lunastre.', 'Selbst wenn. Trotzdem sollte lieber er Berater werden als diese Ly''leth Lunastre.', 25549),
(118908, 'deDE', 'Coryn Stelleris ein Mörder? Das glaube ich nicht!', 'Coryn Stelleris ein Mörder? Das glaube ich nicht!', 25549),
(118907, 'deDE', 'Aber sie wollen nicht! Sie schwören vielmehr Lunastre die Treue!', 'Aber sie wollen nicht! Sie schwören vielmehr Lunastre die Treue!', 25549),
(118906, 'deDE', 'Das Haus Astravar sollte den Berater stellen, wenn Ihr mich fragt.', 'Das Haus Astravar sollte den Berater stellen, wenn Ihr mich fragt.', 25549),
(118905, 'deDE', 'Die Bürger haben Schuld. Dieses niedere Volk macht alles kaputt!', 'Die Bürger haben Schuld. Dieses niedere Volk macht alles kaputt!', 25549),
(118904, 'deDE', 'Ich werde Euch in Kürze an der Azurschwingenrast treffen. Sichere Reise.', '', 25549),
(118903, 'deDE', 'Ruven Dämmermaar wäre mein Favorit gewesen. Wirklich schade.', 'Ruven Dämmermaar wäre mein Favorit gewesen. Wirklich schade.', 25549),
(118902, 'deDE', 'Sie macht sich Sorgen. Zu viel Mitgefühl mit dem niederen Volk.', 'Sie macht sich Sorgen. Zu viel Mitgefühl mit dem niederen Volk.', 25549),
(118901, 'deDE', 'Karzak, ich rufe Euch! BEENDET ES!', '', 25549),
(118900, 'deDE', 'Lunastre dabei zu unterstützen, Beraterin zu werden? Ich weiß nicht. Wenn Ranthos noch hier wäre, vielleicht. Aber seine Tochter...', 'Lunastre dabei zu unterstützen, Beraterin zu werden? Ich weiß nicht. Wenn Ranthos noch hier wäre, vielleicht. Aber seine Tochter...', 25549),
(118899, 'deDE', 'Es reicht! Schwestern, beendet diesen Unfug!', '', 25549),
(118898, 'deDE', 'Boden- und Luftangriff! Teufelswachen, Verdammniswachen, vernichtet sie!', '', 25549),
(118897, 'deDE', 'Sargeras selbst wird meine Talente bemerken und vielleicht meinen Geist erweitern. Oder ich seinen?', '', 25549),
(118896, 'deDE', 'Viele Welten da draußen bedürfen der Läuterung. Wer könnte sie besser finden als ich?', '', 25549),
(118895, 'deDE', 'Bringt mir den Kopf dieses trotzigen Kümmerlings!', '', 25549),
(118894, 'deDE', 'Die Brennende Legion hat schon genug zu tun. Sie brauchen jemanden mit meiner Weitsicht, um ihre Zukunft zu gestalten.', '', 25549),
(118893, 'deDE', '', 'Wo ist er? Wo ist mein Ailen?', 25549),
(118892, 'deDE', 'Ja, das wäre ihnen eine Lektion!', 'Ja, das wäre ihnen eine Lektion!', 25549),
(118891, 'deDE', '', 'Oh Ailen... Du bist zu jung, um in so etwas hineingezogen zu werden.', 25549),
(118890, 'deDE', 'Ich weiß gar nicht, warum einige Bürger gegen den Plan der Großmagistrix sind.', 'Ich weiß gar nicht, warum einige Bürger gegen den Plan der Großmagistrix sind.', 25549),
(118889, 'deDE', '', 'Verfluchte Tricks. Was haben sie mit meinem Sohn angestellt?', 25549),
(118888, 'deDE', '', 'Er hätte schon zurück sein müssen.', 25549),
(118887, 'deDE', '', 'Was haben sie mit meinem Jungen vor?', 25549),
(118886, 'deDE', '', 'Wohin haben sie ihn wohl gebracht?', 25549),
(118885, 'deDE', '', 'Mit wachsendem Hunger werden die Rebellen übereinander herfallen wie Ratten. Wir offenbaren ihre Anhänger und stellen die Ordnung wieder her!', 25549),
(118884, 'deDE', '', 'Niederer Dreck! Man sollte ihre Arkweinrationen einschränken, um sie zu züchtigen.', 25549),
(118881, 'deDE', '', 'Grüße.', 25549),
(118880, 'deDE', 'Wahrhaft fantastisch! Ich frage mich...', '', 25549),
(118879, 'deDE', 'Nur wenige Sterbliche kennen die Geschichte des hohen Hüters Ra, seiner Meisterschaft der Elementarebene und seiner Beziehung zum Mogureich.\n', '', 25549),
(118878, 'deDE', '', 'Die Shal''dorei werden erlöst.', 25549),
(118877, 'deDE', 'Euer Begleiter erwartet Euch. Trefft mich später an meinem Tempel. Wir werden sehen, ob Ihr schafft, was der Donnerkönig nicht konnte.', '', 25549),
(118876, 'deDE', 'Sieg! Versorgt Eure Wunden und stärkt Euch. Wir müssen weiter auf der Hut sein. Denn die Angriffe der Legion haben gerade erst begonnen.', '', 25549),
(118875, 'deDE', 'Lei Shen war dem Sturm und dem Zorn des hohen Bewahrers ebenbürtig, doch nicht in der Meisterschaft der Elemente selbst. Vielleicht seid Ihr das.', '', 25549),
(118874, 'deDE', 'Schamane, der Donnerkönig nahm die Waffen von Ra-den, doch er konnte sie nicht führen.\n', '', 25549),
(118873, 'deDE', 'Doch die Mogu waren Ra-dens Untergang. Viele Jahre später verdarb sie der Fluch des Fleisches. Angeführt vom Donnerkönig Lei Shen, brachten sie den hohen Hüter zu Fall.\n', '', 25549),
(118872, 'deDE', 'Freut Euch über unseren Sieg, aber vergesst nie... die Zeit ist gegen uns. Die Legion wird zurückkehren.', '', 25549),
(118871, 'deDE', 'Als die Zeit für den Krieg gegen das Schwarze Imperium gekommen war, erschuf der hohe Hüter Ra eine steinerne Armee. Diese Kreaturen hießen "Mogu" und sie nannten ihren Gott "Ra-den" oder "Meister Ra".', '', 25549),
(118870, 'deDE', 'Den Schlüssel dieser Reiche verankerte er in seinem Schild, dem "Schutz des hohen Hüters". Ra bewanderte die Elementarebenen als Wärter und Meister zugleich.\n', '', 25549),
(118869, 'deDE', 'Gemeinsam mit der titanengeschmiedeten Zauberin Helya erschuf der hohe Hüter Ra die vier Elementarreiche als Gefängnis für die eigensinnigen Elementarlords.', '', 25549),
(118868, 'deDE', 'Der Titan Aman''thul verlieh dem hohen Bewahrer eine Faust des Lichts, eine Klaue, die im Himmel geschmiedet wurde und die die Sprache der Stürme sprach. Er legte die Macht der Blitze in Ras geballte Faust.', '', 25549),
(118867, 'deDE', 'Leidet, Dämon! Ihr könnt uns nicht brechen! Die Brennende Legion wird fallen!', '', 25549),
(118866, 'deDE', 'Vor langer Zeit, noch vor der Zeit der sterblichen Völker, regierte der hohe Hüter Ra über das südliche Kalimdor.', '', 25549),
(118865, 'deDE', 'Genug von Eurem Wahnsinn, Dämon! Eure Zeit ist gekommen!', '', 25549),
(118864, 'deDE', 'Da kommen noch mehr! Wir müssen sie aufhalten!', '', 25549),
(118863, 'deDE', 'Die Dunkelheit wächst. Ihr Einfluss wird größer! Stellt Euch ihnen entgegen!', '', 25549),
(118862, 'deDE', 'Kein Dämon soll im Hügelland wandeln, der nicht meinen Befehlen gehorcht! Schwärmt aus! Vertreibt sie!', '', 25549),
(118861, 'deDE', 'Champions, wir können noch siegen! Rückt aus und befreit unser Land von dieser dämonischen Präsenz!', '', 25549),
(118860, 'deDE', 'Stellt sicher, dass dieser Dämon für seine Frechheit bezahlt!', '', 25549),
(118859, 'deDE', '', 'Aran''arcana.', 25549),
(118858, 'deDE', 'Macht diesen Dämon einen Kopf kürzer, dann wendet sich das Blatt!', '', 25549),
(118857, 'deDE', 'Solch rohe Gewalt! Sie werden stärker! Bleibt standhaft!', '', 25549),
(118856, 'deDE', 'Da kommen noch mehr! Lasst Euch die Angst nicht Eure Pflicht vergessen machen!', '', 25549),
(118855, 'deDE', 'Die Dämonen greifen an! Löscht... sie... aus!', '', 25549),
(118854, 'deDE', 'Haltet die Stellung! Zeigt kein Mitleid!', '', 25549),
(118853, 'deDE', 'Erhebt Euch, Champions! Erhört den Ruf der Schlacht! Die Brennende Legion steht vor Tarrens Mühle.', '', 25549),
(118852, 'deDE', 'Verlassene! Verbündete! Die Stunde des Widerstands gegen die Brennende Legion hat geschlagen! Haltet Euch bereit!', '', 25549),
(118851, 'deDE', '', 'Wir haben das Südwachttor zurückerobert. Meine Streitkräfte übernehmen jetzt die Patrouillen. Sorgt dafür, dass sich jemand um die anderen kümmert. Wir dürfen nicht zulassen, dass die Legion weiter an Boden gewinnt!', 25549),
(118850, 'deDE', '', 'Eure Worte sind sehr freundlich, aber ich sollte eigentlich gar nicht hier sein. Ich komme bald zurück.', 25549),
(118849, 'deDE', 'Ich war wohl doch nicht bereit für solche... Ereignisse. Vielleicht sollte ich wiederkommen, wenn sich die Lage etwas beruhigt hat.', '', 25549),
(118848, 'deDE', '', 'Sammelt genug Energie, damit der Manasäbler für unsere Forschung gesättigt ist. Dann seid Ihr fertig.', 25549),
(118847, 'deDE', '', 'Der Manasäbler ist sehr schnell auf gerader Strecke, aber er wird langsamer, wenn er in die Kurven geht.', 25549),
(118846, 'deDE', '', 'Springt auf einen Manasäbler und reitet durch die Leylinienpunkte, um die noch vorhandene Energie zu absorbieren.', 25549),
(118845, 'deDE', '', 'Seid gegrüßt. Wir interessieren uns für eine Reihe Leyenergieknoten, die in diesem Gebiet überall verteilt sind.', 25549),
(118844, 'deDE', '', 'Seid gegrüßt! An der Verheerten Küste erwartet uns eine glorreiche Schlacht! Der Kriegshäuptling erwartet höchste Einsatzbereitschaft, daher kann etwas Kampftraining nicht schaden. Sagt Bescheid, wenn Ihr bereit seid.', 25549),
(118843, 'deDE', 'Willkommen an Bord. König Wrynn braucht für die kommende Schlacht perfekt vorbereitete Allianzhelden und hat angeordnet, dass wir auf dem Weg zur Verheerten Küste ein Kampftraining abhalten. Sagt Bescheid, wenn Ihr bereit dazu seid.', '', 25549),
(118842, 'deDE', 'Wir haben den Ostwachtturm zurückerobert! Kämpft weiter, um unser Land zu retten.', '', 25549),
(118840, 'deDE', 'Nor''bethos Suramar.', '', 25549),
(118839, 'deDE', 'Kommt bald wieder.', '', 25549),
(118837, 'deDE', '', '%s schaut sich nervös um, und nimmt sich viel Zeit, bevor sie das Feld betritt.', 25549),
(118836, 'deDE', 'Zeit zu brennen!', '', 25549),
(118835, 'deDE', '', 'Sehr freundlich, $n. Vielleicht würde es unseren Streitkräften mit frischen Vorräten etwas besser gehen. Ich werde sehen, was ich finden kann.', 25549),
(118834, 'deDE', 'Ermächtigt Euren Meister!', '', 25549),
(118833, 'deDE', 'Leiht mir Eure Kraft!', '', 25549),
(118832, 'deDE', 'Lasst die Jagd beginnen!', '', 25549),
(118831, 'deDE', 'Es ist, als hätten sich meine Knochen seit Jahren nicht bewegt! Kommt, suchen wir uns ein Plätzchen zum Reden, wo uns keine Basilisken anstarren.', '', 25549),
(118828, 'deDE', 'Ich muss wohl noch ''n bisschen üben.', 'Ich muss wohl noch ''n bisschen üben.', 25549),
(118827, 'deDE', 'Was sind das für Dinger? Ich hab das nich'' mal kommen sehen!', 'Was sind das für Dinger? Ich hab das nich'' mal kommen sehen!', 25549),
(118826, 'deDE', 'Das hatte ich nich'' erwartet! Ich muss mich ''nen Moment ausruhen.. Kopf dröhnt...', 'Das hatte ich nich'' erwartet! Ich muss mich ''nen Moment ausruhen.. Kopf dröhnt...', 25549),
(118825, 'deDE', 'Hm... Das muss genäht werden. Ich bin gleich wieder da!', 'Hm... Das muss genäht werden. Ich bin gleich wieder da!', 25549),
(118824, 'deDE', 'Autsch! Das gibt eine Narbe! Ich glaube, ich könnte etwas Heilung vertragen.', 'Autsch! Das gibt eine Narbe! Ich glaube, ich könnte etwas Heilung vertragen.', 25549),
(118822, 'deDE', 'Fragen werden noch Euer Tod sein. Erlaubt mir, es Euch vorzuführen!', 'Fragen werden noch Euer Tod sein. Erlaubt mir, es Euch vorzuführen!', 25549),
(118820, 'deDE', 'Stört meine Schutzbefohlenen nicht, während sie sich in der Menagerie amüsieren. Ich müsste Euch sonst entfernen.', 'Stört meine Schutzbefohlenen nicht, während sie sich in der Menagerie amüsieren. Ich müsste Euch sonst entfernen.', 25549),
(118819, 'deDE', 'Ich glaube, die wollten mich töten!', '', 25549),
(118818, 'deDE', 'Und wieder einer erledigt! Gut gemacht. Und jetzt ab mit Euch und findet den Rest von ihnen! Hier treiben sich noch jede Menge von diesen Dingern herum.', '', 25549),
(118815, 'deDE', 'Die Leere flüstert uns zu... sie erzählt uns von unserem Schicksal: einem grausamen Tod! Entzündet eine Kerze für Eure Liebsten, denn das unausweichliche Ende naht.', '', 25549),
(118814, 'deDE', 'Ihr hört sie nicht, oder? Wie sie lachen... und wie sie uns warnen. Unsere Zeit wird kommen!', '', 25549),
(118813, 'deDE', 'Damit werdet Ihr nicht davonkommen, Darion! Tirion... das Licht wird es nicht zulassen!', '', 25549),
(118812, 'deDE', 'Ich bin bereit, Nobundo! Sollen sie doch kommen!', 'Ich bin bereit, Nobundo! Sollen sie doch kommen!', 25549),
(118811, 'deDE', 'Sie verhöhnen uns, wisst Ihr. Die Schatten. Sie sehen unser Ende voraus.', '', 25549),
(118810, 'deDE', 'Die Dämonen haben die meisten meiner Schamanen getötet. Wir haben uns hierher zurückgezogen, um uns ihnen ein letztes Mal entgegenzustemmen.$B$B<Nobundo seufzt.>$B$BWenn Ihr hier helfen wollt, dann bereitet Euch auf eine großartige Schlacht vor, $gmein Freund:meine Freundin;!$B$BIch glaube, das nächste Bataillon ist im Anmarsch. Seid Ihr bereit?', '', 25549),
(118809, 'deDE', 'Tirions Überreste ruhen unter uns, in der Halle der Helden. Wir werden sofort zu Euch stoßen.', '', 25549),
(118808, 'deDE', 'Wir werden diesen Krieg nicht gewinnen, ohne Opfer zu erbringen. Tirion kannte den Preis der Freiheit.', '', 25549),
(118807, 'deDE', 'Sie verhöhnen uns, wisst Ihr. Die Schatten. Sie sehen unseren Untergang voraus.', '', 25549),
(118806, 'deDE', 'Macht Euch bereit! Das Ding kommt runter!', '', 25549),
(118805, 'deDE', 'Was? Wer hat Euch geschickt? Ich wollte nur die Besten und dann schicken sie Euch?$B$BAlso gut... Macht Euch an die Arbeit. Hier rennen jede Menge Dämonen herum. Also seid nur nicht schüchtern.', '', 25549),
(118804, 'deDE', 'Macht Euch mal nützlich und helft uns. Wenn Ihr nur rumsteht, ist niemandem geholfen.', '', 25549),
(118803, 'deDE', 'Macht sie tot! Und zwar schnell.', '', 25549),
(118802, 'deDE', 'Es ist mir eine Freude, Euch meine Dienste anzubieten.', '', 25549),
(118800, 'deDE', 'Ein weiterer Schattenpriester, der Unsinn redet. Allerdings überrascht mich das nicht. So etwas passiert eben, wenn man der Leere zu nahe kommt.', '', 25549),
(118799, 'deDE', 'Alonsus, wir können uns Mutmaßungen nicht leisten. Wir müssen herausfinden, ob dieser Schattenpriester die Wahrheit sagt.', '', 25549),
(118798, 'deDE', 'Diese Akolythen werden Euch treu dienen.', '', 25549),
(118797, 'deDE', 'Wir haben uns in den eingestürzten Schacht im nördlichen Teil der Kristallhalle zurückgezogen. Wir halten den Dämonenansturm in Schach, aber unsere Verteidigung bricht zusammen!', '', 25549),
(118784, 'deDE', '', 'Tut mir leid. Ich kann nicht riskieren, mein Geschäft deswegen zu verlieren. Ich komme zurück, wenn es sicher ist.', 25549),
(118783, 'deDE', 'Öffnet den Himmel!', '', 25549),
(118782, 'deDE', 'Dunkle Wolken ziehen auf...', '', 25549),
(118781, 'deDE', 'Seid gegrüßt, $gHohepriester:Hohepriesterin;. Was kann ich für Euch tun?', '', 25549),
(118780, 'deDE', 'Einstellung', 'Einstellung', 25549),
(118779, 'deDE', 'Das schreckliche Licht der Außenwelt brennt Eurer Ratte in den Augen! Kehrt in die Schattenseite zurück!', 'Das schreckliche Licht der Außenwelt brennt Eurer Ratte in den Augen! Kehrt in die Schattenseite zurück!', 25549),
(118778, 'deDE', '', 'Stellt an der Teufelsseelenbastion die explosive Ablenkung auf. Wir sehen uns dort.', 25549),
(118777, 'deDE', '', 'Danke. Das werde ich nicht vergessen.', 25549),
(118776, 'deDE', '', 'Verstehe... Er konnte sich nie von Ärger fernhalten...', 25549),
(118775, 'deDE', '', '<Hust.> Arluin, seid Ihr das? Es ist so dunkel...', 25549),
(118774, 'deDE', '', 'Wer ist da?', 25549),
(118773, 'deDE', '', 'Wir sammeln jetzt unsere Kräfte. Ich hoffe, wir können auf Euch zählen, wenn die Zeit gekommen ist, Suramar zu befreien.', 25549),
(118772, 'deDE', '', 'Ohne Euch wäre das nicht möglich gewesen.', 25549),
(118771, 'deDE', '', 'Wir erleben bald ein neues Zeitalter der Nachtgeborenen.', 25549),
(118770, 'deDE', 'Nehmt Euch Zeit. Genießt diesen Happen, meine Kleinen!', '', 25549),
(118769, 'deDE', 'An Euch werden sich die Hunde satt fressen!', '', 25549),
(118768, 'deDE', 'Euch erwartet ein Schicksal schlimmer als der Tod, kleiner Draenei!', '', 25549),
(118767, 'deDE', 'Nahrung für die Flammen...', '', 25549),
(118766, 'deDE', 'Frisches Fleisch wartet auf Eure Zähne!', '', 25549),
(118765, 'deDE', 'Bald ist Fütterungszeit, meine Kleinen!', '', 25549),
(118763, 'deDE', 'Wie erbärmlich. Jarvox, führt seine Hinrichtung durch. Aber schön langsam und schmerzhaft.', '', 25549),
(118762, 'deDE', 'Aaaaaarrrrrrr! Aaaaarrrrr!', '', 25549),
(118761, 'deDE', 'Ihr werdet durch meine Klinge sterben!', '', 25549),
(118760, 'deDE', 'Gerechtigkeit... oder Rache, Paladin? Wählt weise, denn der Hass führt auf einen dunklen Pfad.', '', 25549),
(118759, 'deDE', 'Hier ist für Euch Schluss, Balnazzar. Ich will Gerechtigkeit für meine getöteten Brüder und Schwestern!', '', 25549),
(118758, 'deDE', 'Ahhh, die Verteidiger des Lichts. Wir waren schon ganz ungeduldig.', '', 25549),
(118756, 'deDE', '', 'Habt meinen Dank.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(118755, 'deDE', '|TInterface\\Icons\\shaman_pvp_lightninglasso:20|t%s wirkt |cFFFF0000|Hspell:220101|h[Todesblitz]|h|r! Unterbrecht den Zauber!', '|TInterface\\Icons\\shaman_pvp_lightninglasso:20|t%s wirkt |cFFFF0000|Hspell:220101|h[Todesblitz]|h|r! Unterbrecht den Zauber!', 25549),
(118754, 'deDE', 'Jämmerliche Kreaturen... Ihr werdet schreiend sterben!', '', 25549),
(118753, 'deDE', '', 'Vielleicht tut sich doch ein neuer Weg auf...', 25549),
(118752, 'deDE', '', 'Ihr werdet meine Forschung nicht stören!', 25549),
(118751, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 25549),
(118750, 'deDE', 'Ich möchte zum Hof der Sterne (Dungeon).', 'Ich möchte zum Hof der Sterne (Dungeon).', 25549),
(118749, 'deDE', 'Champions, Ihr habt es geschafft! Ich spüre, wie Gul''dans Ritual an Macht gewinnt. Wir müssen uns beeilen. Ich kann Euch zur Nachtfestung zurückteleportieren. Seid Ihr bereit?', '', 25549),
(118748, 'deDE', 'Chance ist günstig! Altar benutzen und böse Portale beschwören. Nicht die guten! Schnell!', '', 25549),
(118747, 'deDE', '', 'Wir müssen Mathias Shaw finden und mit ihm beweisen, dass Detheroc seinen Platz eingenommen hat.', 25549),
(118746, 'deDE', '', 'Boros!', 25549),
(118745, 'deDE', 'Hochlord, Späher haben Balnazzar in diesem Tal entdeckt. Wenn wir schnell handeln, könnten wir ihn stellen.', '', 25549),
(118744, 'deDE', 'Das Tagebuch ist voller Notizen zu den Auswirkungen der Höhle auf die örtliche Flora und Fauna. Einige Einträge springen ins Auge.\n\nEintrag Nr. 5:\nDiese Höhle ist interessant. Ich habe Kristalle aus der Werkstatt mitgebracht und platziert. Welche Auswirkung die Energien hier wohl auf sie haben?\n\nEintrag Nr. 17:\nNach der Einstimmung auf die Kristalle kann ich Energiebarrieren errichten, die gegen mich gerichtete Magie neutralisieren. Damit könnte man Armeen unverwundbarer Soldaten erschaffen.\n\nEintrag Nr. 23:\nDie Barriere arbeitet nicht fehlerfrei. Auf alle drei Kristalle eingestimmt, könnte man ihre Kräfte kombinieren, um die Barriere zu neutralisieren. Ich muss das Problem beheben, bevor ich meinen Vorgesetzten berichten kann.', '', 25549),
(118743, 'deDE', 'Lauft!', 'Lauft!', 25549),
(118742, 'deDE', 'Erstaunlich.', '', 25549),
(118741, 'deDE', '$n, endlich seid Ihr gekommen, um Euch auf der Halbinsel der Sturmkuppe zu beweisen! Ihr habt gezeigt, dass Ihr tapfer seid, aber Tapferkeit alleine reicht hier nicht aus.$b$bDie Wildtiere dieser Schlucht kümmern Eure Heldentaten nicht. Sie reagieren nur auf Kraft.$b$bGerade jetzt versuchen Helden wie Ihr, diese Tiere zu zähmen und treten gegeneinander im Kampf an. Wollt Ihr Euch dieser Herausforderung stellen?', '', 25549),
(118740, 'deDE', 'Durch diese enge Schlucht wandern Ziegen, Hirsche, Worgs und Bären. Alles wilde Tiere, das stimmt natürlich, aber sie alle können durch eine Machtdemonstration gezähmt werden.$b$bBezwingt die Kreaturen im Kampf, dann werden sie gehorsam sein. Auf ihrem Rücken könnt Ihr Eure Feinde auf die Felsen unter Euch in den Tod schicken.$b$bPasst jedoch auf Sturmkralle auf, den Drachen, der zwischen den Steinen der Sturmkuppe ruht. Viele behaupten, ihn könne man nicht zähmen. Nur wenige haben es versucht. Und keiner von ihnen hat überlebt.', '', 25549),
(118739, 'deDE', '', 'Ein hart umkämpfter Baum... Glaubt Ihr, er kann uns nähren?', 25549),
(118738, 'deDE', 'Bewegung!', 'Bewegung!', 25549),
(118737, 'deDE', 'Was ist hier los?', 'Was ist hier los?', 25549),
(118736, 'deDE', 'Schnell weiter. Wir müssen die Seelenmaschine füttern.', '', 25549),
(118735, 'deDE', 'Seid versichert, niemand wird Euch vermissen.', '', 25549),
(118734, 'deDE', 'Die Legion weiß Euer Opfer zu schätzen. Ihr könnt stolz sein!', '', 25549),
(118733, 'deDE', 'Ausgezeichnet, $n!', '', 25549),
(118732, 'deDE', 'Genug geheult! Ihr gebt Euer Leben für eine große Sache!', '', 25549),
(118731, 'deDE', 'Schafft sie in die Boote. Die Seelenmaschine braucht Brennstoff!', '', 25549),
(118730, 'deDE', 'Warum findet Ihr es nicht heraus?', '', 25549),
(118729, 'deDE', 'Diese Kugeln aus Leyenergie scheinen einer Art Muster zu folgen. Ich frage mich, wohin es wohl führt?', '', 25549),
(118728, 'deDE', 'Faszinierend! Schaut Euch das an.', '', 25549),
(118727, 'deDE', '', 'Das Rabenauge ist der Schlüssel, um den Brief des SI:7 zu entziffern.', 25549),
(118726, 'deDE', '$n, nicht wahr? Ich hörte, wie die Vrykul Euren Namen erwähnten.$b$bEs ist still geworden an diesen Klippen. Kehrt später zurück, um Euch im Kampf gegen die Tiere dieser Halbinsel zu beweisen.', '', 25549),
(118725, 'deDE', 'Der Arcan''dor wird Euch nicht nur nähren, sondern mit seinen Früchten auch vollständig heilen.', '', 25549),
(118724, 'deDE', '', 'Ich bin bereit, dorthin zu gehen, wo ich gebraucht werde, und zu tun, was immer nötig ist, um sicherzustellen, dass die Ziele der Ungekrönten erreicht werden.', 25549),
(118723, 'deDE', 'Erlebt die Gabe uralter Magie.', '', 25549),
(118722, 'deDE', '', 'Einen wunderschönen Tag wünsche ich, $n. Ich nehme an, dass die Angelegenheiten der Ungekrönten in bester Ordnung sind?', 25549),
(118721, 'deDE', '', 'Lasst uns nach den anderen schauen.', 25549),
(118720, 'deDE', '', 'Er ist tot.', 25549),
(118719, 'deDE', '', 'Ihr habt uns gerettet. Ruht bitte.', 25549),
(118718, 'deDE', 'Wir haben''s geschafft... <keucht> ...oder?', '', 25549),
(118717, 'deDE', 'Hey... <hustet> Richtet Vanthir meinen Dank aus...', '', 25549),
(118716, 'deDE', '', 'Nicht sprechen! Ihr seid verwundet...', 25549),
(118715, 'deDE', '<hust> Argh...', '', 25549),
(118714, 'deDE', '', 'Oh nein...', 25549),
(118713, 'deDE', '', 'Wo ist Arluin?!', 25549),
(118712, 'deDE', '', 'Uh... Geschafft...', 25549),
(118711, 'deDE', '', 'Oculeth! Bringt uns hier raus!', 25549),
(118710, 'deDE', 'Hhghh-AAAHHHH!!!', '', 25549),
(118709, 'deDE', '', 'Arluin! NEIN!', 25549),
(118708, 'deDE', '', 'Was tut Ihr da?!', 25549),
(118707, 'deDE', 'Ihr schuldet mir etwas...', '', 25549),
(118706, 'deDE', 'Verflucht...', '', 25549),
(118705, 'deDE', '', 'Das ist zu gefährlich! Der arkane Strom würde uns zerreißen!', 25549),
(118704, 'deDE', '', 'Erath-omnas!', 25549),
(118702, 'deDE', 'Ich... danke Euch...', '', 25549),
(118701, 'deDE', 'Für keinen von uns gibt''s noch Hoffnung, seid Ihr denn blind?', '', 25549),
(118700, 'deDE', 'Der Manasturm wird noch stärker! Wir müssen das Ding abschalten!', '', 25549),
(118699, 'deDE', '', 'Gebt Acht!', 25549),
(118698, 'deDE', 'Das war schon alles? So könnte ich den ganzen Tag weitermachen!', '', 25549),
(118697, 'deDE', 'Diesen Sohn Eisenschmiedes bekommt Ihr nicht. Fresst Blei!', '', 25549),
(118696, 'deDE', '', 'Hallo!', 25549),
(118695, 'deDE', '', 'Wollt Ihr etwas Zaubersaft? Ich kann nicht mehr trinken.', 25549),
(118694, 'deDE', '', 'Wollt Ihr mitspielen? Aber dann bin ich die Gute!', 25549),
(118693, 'deDE', '', 'Seid Ihr groß!', 25549),
(118692, 'deDE', '', 'Ich stecke nicht in Schwierigkeiten, oder?', 25549),
(118691, 'deDE', '', 'Der Himmel ist so toll!', 25549),
(118690, 'deDE', 'Der Himmel ist so toll!', '', 25549),
(118689, 'deDE', 'Ich stecke nicht in Schwierigkeiten, oder?', '', 25549),
(118688, 'deDE', 'Seid Ihr groß!', '', 25549),
(118687, 'deDE', 'Wollt Ihr mitspielen? Aber dann bin ich der Gute!', '', 25549),
(118686, 'deDE', 'Wollt Ihr etwas Zaubersaft? Ich kann nicht mehr.', '', 25549),
(118685, 'deDE', 'Hallo!', '', 25549),
(118684, 'deDE', 'Leichter gesagt als getan.', '', 25549),
(118683, 'deDE', '', 'Wir müssen durchhalten, bis der Sturm vorbei ist!', 25549),
(118682, 'deDE', '', 'Rath, anu''telar!', 25549),
(118681, 'deDE', '', 'Wir haben keine Wahl. Es muss sein.', 25549),
(118680, 'deDE', 'Aber sollten wir nicht raus, BEVOR der Sturm beginnt?', '', 25549),
(118679, 'deDE', 'Fasst Euch kurz.', '', 25549),
(118678, 'deDE', 'Hunger.', '', 25549),
(118677, 'deDE', 'Ich brauche Euren Schutz!', 'Ich brauche Euren Schutz!', 25549),
(118676, 'deDE', 'Ich halte nicht mehr lange durch.', 'Ich halte nicht mehr lange durch.', 25549),
(118675, 'deDE', 'Wir müssen schnellstmöglich an unser Ziel.', 'Wir müssen schnellstmöglich an unser Ziel.', 25549),
(118674, 'deDE', 'Ich kann mich nicht verteidigen. Hilfe!', 'Ich kann mich nicht verteidigen. Hilfe!', 25549),
(118673, 'deDE', 'Hilfe! Beschützt mich vor den Kreaturen!', 'Hilfe! Beschützt mich vor den Kreaturen!', 25549),
(118672, 'deDE', 'Los, macht schneller.', 'Los, macht schneller.', 25549),
(118671, 'deDE', 'Ihr habt Timirgos gefunden!', 'Ihr habt Timirgos gefunden!', 25549),
(118670, 'deDE', '', 'Die Sicherung ist hin. Wir müssen den Manasturm manuell starten.', 25549),
(118669, 'deDE', '', 'Hier stimmt was nicht. Der temporale Warpsequenzer...', 25549),
(118668, 'deDE', 'Was immer Ihr macht, beeilt Euch! Da kommen jede Menge Wachen!', '', 25549),
(118667, 'deDE', 'Ich bin bereit zum Aufbruch.', 'Ich bin bereit zum Aufbruch.', 25549),
(118666, 'deDE', 'Seid Ihr bereit für die Reise zur Rabenwehr?', '', 25549),
(118665, 'deDE', '', 'Da! Stellt den Manasturmgenerator in die Nähe der Leitung.', 25549),
(118664, 'deDE', 'Nur einen kurzen Moment...', '', 25549),
(118663, 'deDE', 'Alle Schlösser lassen sich öffnen.', '', 25549),
(118661, 'deDE', 'Sieht nicht sonderlich effektiv aus. Beherrscht der alte Mann sein Handwerk?', '', 25549),
(118660, 'deDE', '', 'Ja, das geht schon.', 25549),
(118659, 'deDE', 'Die Horde erhebt sich.', 'Die Horde erhebt sich.', 25549),
(118658, 'deDE', 'Eure Hilfe ist mir sehr willkommen.', 'Eure Hilfe ist mir sehr willkommen.', 25549),
(118657, 'deDE', 'Die Schlacht hat erst begonnen.', 'Die Schlacht hat erst begonnen.', 25549),
(118656, 'deDE', 'Kämpft weiter. Wir dürfen nicht nachlassen.', 'Kämpft weiter. Wir dürfen nicht nachlassen.', 25549),
(118655, 'deDE', 'Erst ein wenig Ruhe, dann Rache.', 'Erst ein wenig Ruhe, dann Rache.', 25549),
(118654, 'deDE', 'Ich bin Euch für Eure Hilfe sehr dankbar.', 'Ich bin Euch für Eure Hilfe sehr dankbar.', 25549),
(118653, 'deDE', 'Ich stehe zutiefst in Eurer Schuld.', 'Ich stehe zutiefst in Eurer Schuld.', 25549),
(118652, 'deDE', 'Ihr kämpft gegen eine Macht, die Ihr nicht einmal verstehen könnt!', '', 25549),
(118651, 'deDE', 'Ihr solltet auf Euren Ton achten, Galen!', '', 25549),
(118650, 'deDE', 'Es scheint Euer... Champion... ist endlich angekommen.', '', 25549),
(118649, 'deDE', '', 'Aber noch wichtiger ist: Wenn wir scheitern, ist Suramar verloren.', 25549),
(118648, 'deDE', 'Rein, das Gerät platzieren und raus, bevor es hochgeht. Es soll kompliziertere Aufträge geben.', '', 25549),
(118647, 'deDE', 'Nicht vergessen: Nach Beginn des Manasturms gibt es zu viele Störungen für den Teleport. Ihr müsst da raus, BEVOR der Sturm beginnt!', '', 25549),
(118646, 'deDE', 'Ich teleportiere Euch hinter die Hauptverteidigungslinie. Aktiviert das Leuchtfeuer, wenn ihr fertig seid, dann kann ich Euch orten und zurückholen.', '', 25549),
(118645, 'deDE', 'Hm... Ein bisschen herb, eine Spur... Oh, ja. Das ist es.', '', 25549),
(118644, 'deDE', 'Also, los. Kommt zusammen. Nur keine Scheu. Gruppenkuscheln.', '', 25549),
(118643, 'deDE', 'So, fertig. Ich habe jetzt die benötigten Koordinaten.', '', 25549),
(118642, 'deDE', 'Untersuchung beginnt...', '', 25549),
(118641, 'deDE', 'Und keine Sorge wegen des Honorars. Bezahlt mich einfach, wenn der Auftrag erledigt ist.', '', 25549),
(118640, 'deDE', '', 'Ich dachte, Euch geht es immer nur ums Geld.', 25549),
(118639, 'deDE', 'Dafür wird die Legion bezahlen!', '', 25549),
(118638, 'deDE', 'Die Teufelsenergie... sie ist verschwunden...', '', 25549),
(118637, 'deDE', 'Die Eredarhexe! Ihr Tod ist unsere letzte Chance, Hodir zu retten!', '', 25549),
(118636, 'deDE', 'Ihr werdet nicht erfolgreich sein, Darion. Das Licht wird es nicht zulassen!', '', 25549),
(118635, 'deDE', 'Wir sind wegen Tirion Fordrings sterblicher Überreste gekommen. Macht dies nicht schwerer, als es sein muss.', '', 25549),
(118634, 'deDE', '', 'Ihr werdet nicht mein neuestes Haustier töten! Wenn ich mit Euch fertig bin, dient Ihr alle der Legion!', 25549),
(118633, 'deDE', 'Mein Lord! Wir werden angegriffen... es ist... es ist die Schwarze Klinge!', '', 25549),
(118632, 'deDE', 'Und keine Sorge wegen des Honorars. Bezahlt mich einfach, wenn der Auftrag erledigt ist.', '', 25549),
(118631, 'deDE', 'Ich werde nicht einfach stillhalten. Das wäre zu riskant. Ich bin dabei, verstanden?', '', 25549),
(118630, 'deDE', 'Ich bin nicht blind. Ich sehe, was in Suramar geschieht.', '', 25549),
(118629, 'deDE', 'Ich hab von Eurem irren Auftrag gehört. Ihr wolltet doch nicht etwa ohne mich abreisen, oder?', '', 25549),
(118628, 'deDE', '', 'Sofort.', 25549),
(118627, 'deDE', 'Ja, Gebieterin!', '', 25549),
(118626, 'deDE', '', 'Keine Details. Tut es einfach. Ich vertraue auf Euch.', 25549),
(118625, 'deDE', 'Ja. Aber es könnte klappen! Wir generieren ein Warpfeld und...', '', 25549),
(118624, 'deDE', '', 'Ein Manasturm... Seid Ihr wahnsinnig?', 25549),
(118623, 'deDE', 'Vielleicht mit einem Manasturm...', '', 25549),
(118622, 'deDE', '', 'Womit könnte man die Leylinie entfachen?', 25549),
(118621, 'deDE', '', 'Ihre Hexenmeister greifen von oben an!', 25549),
(118620, 'deDE', '', 'Wenn man die Leylinie hochfahren könnte, würde die Spannung theoretisch bis nach Shal''Aran reichen.', 25549),
(118619, 'deDE', '', 'Hm... Die Hauptleitung unter Suramar ist zehnmal so stark wie unsere hier.', 25549),
(118618, 'deDE', '', 'Valtrois, wie bekommen wir mehr Energie? Und sei es nur für kurze Zeit?', 25549),
(118617, 'deDE', 'Das reicht nicht...', '', 25549),
(118616, 'deDE', '', 'Alle Leylinien aktiviert und auf voller Kraft!', 25549),
(118615, 'deDE', '', 'Ihr müsst die restlichen Leylinienzuleitungen aktivieren.', 25549),
(118614, 'deDE', '', 'Fremdling, sprecht sofort mit Valtrois!', 25549),
(118613, 'deDE', 'Könnt Ihr meine Ausrüstung reparieren?', 'Könnt Ihr meine Ausrüstung reparieren?', 25549),
(118612, 'deDE', 'Ohne ausreichende Kraft für den Übergang in die finale Form wird er sterben.', '', 25549),
(118611, 'deDE', 'Der Arcan''dor ist in einer kritischen Phase.', '', 25549),
(118610, 'deDE', '', 'Was geht hier vor?', 25549),
(118609, 'deDE', '', 'Valtrois finale lines.', 25549),
(118608, 'deDE', 'Valewalker finale lines.', '', 25549),
(118607, 'deDE', 'Unter dem Arcan''dor erfahrt Ihr Erneuerung. Das ist jetzt der einzige Weg.', '', 25549),
(118606, 'deDE', 'Möchtet Ihr Alaina das verkohlte Medaillon geben?', 'Möchtet Ihr Alaina das verkohlte Medaillon geben?', 25549),
(118605, 'deDE', 'Erkennt Ihr dieses Medaillon?', 'Erkennt Ihr dieses Medaillon?', 25549),
(118604, 'deDE', 'So arrogant... Bald werdet Ihr verstehen.', '', 25549),
(118603, 'deDE', '', 'Sein Medaillon? Wo habt Ihr das her?\n\nNein! Das glaube ich nicht! Er kann nicht fort sein! \n\nCedric, oh mein liebster Cedric, komm bitte zurück.\n\nLass mich nicht alleine...', 25549),
(118602, 'deDE', '', 'Ich hab gesehen, wie Ihr zur Verheerten Küste aufgebrochen seid. Sagt mir bitte, habt Ihr meinen Mann gesehen?', 25549),
(118601, 'deDE', '', 'Wir sind die Meister des Arkanen, Nachtelf. Ein Baum ist kein Problem.', 25549),
(118600, 'deDE', 'HASS!!', '', 25549),
(118599, 'deDE', 'Forschen wir weiter über mein Artefakt.', 'Forschen wir weiter über mein Artefakt.', 25549),
(118598, 'deDE', '', 'Also dafür wurde diese Kammer erbaut... aber was ist es?', 25549),
(118597, 'deDE', '', 'Schön, Euch wiederzusehen, $n.', 25549),
(118596, 'deDE', 'Jetzt teilen wir die Bürde der Verantwortung für den Arcan''dor.', '', 25549),
(118595, 'deDE', 'Dieser Baum nährt sich von Leylinien. Er spendet Leben... oder Vernichtung.', '', 25549),
(118594, 'deDE', 'Das ist ein Arcan''dor, ein Geschenk der alten Magier.', '', 25549),
(118593, 'deDE', 'Die Saat erwacht und dürstet...', '', 25549),
(118592, 'deDE', 'Hrgh... mein Preis... wiegt schwer...', '', 25549),
(118591, 'deDE', 'Nichts entkommt meinem Netz!', '', 25549),
(118590, 'deDE', 'Der Arcan''dor wird wieder leben! Mit seiner Kraft kehren wir nach oben zurück!', '', 25549),
(118589, 'deDE', 'Kommt, Kinder! Labt euch an ihren Knochen!', '', 25549),
(118588, 'deDE', 'Nein! Was habt Ihr getan?!', '', 25549),
(118587, 'deDE', 'Jetzt gehört die Macht des Arcan''dor mir!', '', 25549),
(118586, 'deDE', 'Ah, ein Präsent für eine Königin. Ich danke Euch...', '', 25549),
(118585, 'deDE', 'Nein! Hodir! Was haben sie Euch angetan?!', '', 25549),
(118584, 'deDE', '', 'Ihr seid am Leben, Boros. Das ist alles, was zählt. Lasst uns zur Kapelle des Hoffnungsvollen Lichts zurückkehren.', 25549),
(118583, 'deDE', '', 'Einen Frieden, nach dem wir verzweifelt suchen.', 25549),
(118582, 'deDE', 'Hmm. So viele haben für meinen törichten Fehler bezahlt. Dies ist nicht der Weg der Gerechtigkeit, das ist mir nun klar.', '', 25549),
(118581, 'deDE', '<Keucht.> Ich danke Euch, Hochlord. Ich... ich war blind vor Rache.', '', 25549),
(118580, 'deDE', '<Die Schwingen des Greifs schlagen angesichts des bevorstehenden Kampfs erwartungsvoll.>', '<Die Schwingen des Greifs schlagen angesichts des bevorstehenden Kampfs erwartungsvoll.>', 25549),
(118579, 'deDE', 'Lasst uns den Angriff auf die Verheerte Küste beginnen!', 'Lasst uns den Angriff auf die Verheerte Küste beginnen!', 25549),
(118578, 'deDE', '<Brecht auf und schließt Euch dem Angriff auf die Verheerte Küste an.>', '<Brecht auf und schließt Euch dem Angriff auf die Verheerte Küste an.>', 25549),
(118577, 'deDE', 'Grüße, Champion.', 'Grüße, Champion.', 25549),
(118576, 'deDE', '', 'Etwas, das Euch Frieden schenkte...', 25549),
(118575, 'deDE', '', 'Ihr... habt etwas gefunden, nicht wahr?', 25549),
(118574, 'deDE', 'Möge die Dunkle Fürstin über Euch wachen, $p.', 'Möge die Dunkle Fürstin über Euch wachen, $p.', 25549),
(118573, 'deDE', 'Ihr wisst es. Ihr wart dort.', '', 25549),
(118572, 'deDE', 'Ehre dem König, $p.', 'Ehre dem König, $p.', 25549),
(118571, 'deDE', '', 'Wir müssen sie nur in Gang setzen.', 25549),
(118570, 'deDE', '', 'Thalyssra und ich hatten wohl die gleiche Idee: Die alten Leylinienzuleitungen könnten uns nähren.', 25549),
(118569, 'deDE', '', 'So weit entfernt vom Nachtbrunnen müssen wir jede Magiequelle nutzen, die sich uns bietet.', 25549),
(118568, 'deDE', 'Auf dass Euer vernichtender Zorn unseren ewigen Feind in Stücke reißt!', '', 25549),
(118567, 'deDE', 'Erhebt Eure Klinge vor der Schmiede und werdet Zeuge der Macht, die sie erhält!', '', 25549),
(118566, 'deDE', 'Ja! Euch erwartet solch boshafter Ruhm! Mit dieser Waffe werdet Ihr die Legion Eurem Willen unterwerfen! Selbst Kil''jaeden wird vor Euch winseln!', '', 25549),
(118565, 'deDE', 'Die Essenz der Natur fließt durch Eure Waffe! In Eurer Hand lässt sie die dunklen Mächte, die Azeroth bedrohen, erzittern! Andu-falah-dor!', '', 25549),
(118564, 'deDE', 'Möge Euch Eure Waffe auf dem Pfad zum Sieg gut dienen!', '', 25549),
(118563, 'deDE', 'Ihr wart immer ein Champion des Lichts. Nun führt Ihr eine Waffe, die Eurer rechtschaffenen Sache wahrhaftig würdig ist!', '', 25549),
(118562, 'deDE', 'Diese Waffen sind wahrlich eines Herrschers der Schatten würdig! Mögen Eure Klingen stets sicher und leise ihr Ziel finden.', '', 25549),
(118561, 'deDE', 'Möge dieser Segen Euren Pfad zum Sieg erhellen, $ct!', '', 25549),
(118560, 'deDE', 'Die Teufelsfledermaus schreit vor Schmerzen, als Eure Waffe sie durchbohrt.', '', 25549),
(118559, 'deDE', '|TInterface\\Icons\\creatureportrait_cyclone_nodebris:20|t%s unterbricht die Anomalie mit einem |cFFFF0000|Hspell:212115|h[temporalen Schmettern]|h|r!', '|TInterface\\Icons\\creatureportrait_cyclone_nodebris:20|t%s unterbricht die Anomalie mit einem |cFFFF0000|Hspell:212115|h[temporalen Schmettern]|h|r!', 25549),
(118558, 'deDE', 'Ich benötige einen Vorrat Ordensressourcen.', 'Ich benötige einen Vorrat Ordensressourcen.', 25549),
(118557, 'deDE', 'Seid gegrüßt und habt Dank dafür, dass Ihr beim Testen der Beta von Legion helft!\n\nIch kann Euch bestimmte Vorräte für Eure Ordenshalle anbieten.', '', 25549),
(118556, 'deDE', 'Es geht los!', '', 25549),
(118555, 'deDE', 'Wir müssen in Erfahrung bringen, warum der alte Arcan''dor versagte. Seine Überreste könnten uns Antworten liefern.', '', 25549),
(118554, 'deDE', 'Selbst in diesem Zustand wächst der Arcan''dor weiter.', '', 25549),
(118553, 'deDE', 'Vor vielen Jahren rasteten die Ausgestoßenen aus der abgeschirmten Stadt hier.', '', 25549),
(118552, 'deDE', 'Trefft mich am Tempel von Fal''adora. Wir müssen die Vergangenheit studieren, um unsere Zukunft zu retten.', '', 25549),
(118551, 'deDE', 'Schnell, schnell, durch mein Portal! Flieht!', '', 25549),
(118550, 'deDE', 'Kommt zu mir, wenn das vorbei ist, $n. Die Frostwölfe haben immer Verwendung für Leute wie Euch.', '', 25549),
(118549, 'deDE', 'Was, wenn sie zurückkommen?', '', 25549),
(118548, 'deDE', 'Ich gehe lieber auf Nummer Sicher als in mein Grab!', '', 25549),
(118547, 'deDE', 'Ich... äh... wollte nur nachsehen, ob hier oben alles klar ist. Ja... alles bestens.', '', 25549),
(118546, 'deDE', 'Als Ihr das letzte Mal so etwas gesagt habt, hätte mich fast ein Dämon gefressen!', '', 25549),
(118545, 'deDE', 'Ich weiß nicht... Das sieht mir nicht sehr sicher aus.', '', 25549),
(118544, 'deDE', 'Jetzt nicht. Kommt schon her!', 'Jetzt nicht. Kommt schon her!', 25549),
(118543, 'deDE', 'Ich kann nicht ewig warten. Jemand muss diese Schredder reparieren.', 'Ich kann nicht ewig warten. Jemand muss diese Schredder reparieren.', 25549),
(118542, 'deDE', 'Wir haben unsere Leute hier! Vertraut mir! Es ist sicher.', 'Wir haben unsere Leute hier! Vertraut mir! Es ist sicher.', 25549),
(118541, 'deDE', 'Kommt schon! Wir haben nicht ewig Zeit! Es ist sicher! Versprochen!', 'Kommt schon! Wir haben nicht ewig Zeit! Es ist sicher! Versprochen!', 25549),
(118540, 'deDE', 'Kommt Ihr jetzt endlich her?! Wir haben eine Aufgabe!', 'Kommt Ihr jetzt endlich her?! Wir haben eine Aufgabe!', 25549),
(118539, 'deDE', 'Ich werde Euch mit Freuden dienen, wenn Ihr mich wollt. Razelikhs gesamte Erinnerungen und all sein Wissen stehen mir zur Verfügung. Gestattet mir, Euch im Krieg gegen die Legion zu unterstützen.', '', 25549),
(118538, 'deDE', 'Den Rest kennt Ihr. Euer Champion kam und hat mich gefunden. Und hier bin ich nun.', '', 25549),
(118537, 'deDE', 'Ehe wir uns versahen, wurden wir aus dem Wirbelnden Nether geworfen, weil die Brennende Legion uns zur Invasion von Azeroth gerufen hatte. Am Teufelsfeuervorstoß habe ich mein Bestes gegeben, um ihre Bemühungen zu unterbinden.', '', 25549),
(118536, 'deDE', 'In diesem neuen Körper liegen unsere Seelen immer in einem ewigen Konflikt. Die Kontrolle ist mein... zumindest die meiste Zeit. Aber es ist ein harter Kampf. Wir Dämonenjäger sind es gewohnt, unsere inneren Dämonen zu zügeln.', '', 25549),
(118535, 'deDE', 'Einige Zeit später wurde die Klinge zerstört. Unsere Seelen wurden freigesetzt, nur um in den Wirbelnden Nether geschickt zu werden. Allerdings hat Razelikh eine sehr mächtige Dämonenseele. Wie bei vielen Schreckenslords bildete sich schließlich ein neuer Körper. Man sagt, dass man sie endgültig nur im Wirbelnden Nether töten kann.', '', 25549),
(118534, 'deDE', 'Letztendlich ergriff der Entweiher von mir Besitz und ich opferte mich im Gegenzug, um uns beide zu vernichten. Unsere Seelen waren in einer verzauberten Klinge gefangen, verdammt zu ewigem Zweikampf.', '', 25549),
(118533, 'deDE', 'Razelikh der Entweiher war ein Schreckenslord und mit der Eroberung der Verwüsteten Lande betraut. Ich begab mich dorthin, um ihn aufzuhalten. Aber die Dinge entwickelten sich nicht so, wie ich erwartet hatte.', '', 25549),
(118532, 'deDE', 'Wo soll ich anfangen? Ich schätze, das Einzige, was zählt, war mein Kampf mit dem Dämon.', '', 25549),
(118531, 'deDE', 'Ja, erzählt mir alles, Loramus.', 'Ja, erzählt mir alles, Loramus.', 25549),
(118530, 'deDE', 'Seid gegrüßt, $n. Ich schulde Euch wohl eine Erklärung, wenn jemals so etwas wie Vertrauen zwischen uns herrschen soll.', '', 25549),
(118529, 'deDE', '', 'Hallo, Schätzchen. Es ist mir immer eine Freude, Euch zu sehen.\n\nWie kann ich Euch helfen?', 25549),
(118528, 'deDE', 'Das ging recht schnell. Doch in Zukunft wird es schwieriger, so viele Aschenzungen zu rekrutieren.', '', 25549),
(118527, 'deDE', '', 'Für die Horde!', 25549),
(118526, 'deDE', '', 'Helden, lasst uns jetzt $p, den Schrecken der Allianz, würdigen!', 25549),
(118525, 'deDE', '', 'Die uralte Waffe in seinen Händen versetzt jene in Schrecken, die unsere Art zu leben bedrohen.', 25549),
(118524, 'deDE', '', 'Vor Euch steht der größte Champion der Horde, verantwortlich für zahllose Siege über unsere Feinde.', 25549),
(118523, 'deDE', '', '$p, dreht Euch um und lasst Eure Anhänger Zeuge Eurer skrupellosen Gerissenheit werden.\n', 25549),
(118522, 'deDE', '', '$n, tretet näher.', 25549),
(118521, 'deDE', '', 'LÖSCHEN', 25549),
(118520, 'deDE', 'Wer ist da?!', 'Wer ist da?!', 25549),
(118519, 'deDE', 'Irgendetwas stimmt hier nicht...', 'Irgendetwas stimmt hier nicht...', 25549),
(118518, 'deDE', 'Eine Täuschung! Was verbergt Ihr?', 'Eine Täuschung! Was verbergt Ihr?', 25549),
(118515, 'deDE', 'Auf dass Euer vernichtender Zorn unseren ewigen Feind in Stücke reißt!', '', 25549),
(118514, 'deDE', '', '''Sternensog'' ist bereit! Jetzt wirken!', 25549),
(118513, 'deDE', '', 'Wirkt ''Sternensog''!', 25549),
(118512, 'deDE', '', 'Versucht, das Ziel mit ''Wucherwurzeln'' festzuhalten!', 25549),
(118511, 'deDE', '', 'Versucht, das Ziel zu verwurzeln, bevor es Euch erreicht. Also los!', 25549),
(118510, 'deDE', '', 'Wirkt ''Wucherwurzeln''!', 25549),
(118509, 'deDE', '', 'Setzt ''Lunarschlag'' ein!', 25549),
(118508, 'deDE', '', 'Maximale Astrale Macht! Wirkt ''Sternensog''!', 25549),
(118507, 'deDE', '', 'Ihr könnt in die Mondkingestalt wechseln und so Schaden und Verteidigung erhöhen.', 25549),
(118506, 'deDE', '', 'Diese Angriffe verursachen regelmäßigen Schaden und sind gut geeignet für die Kampferöffnung.', 25549),
(118505, 'deDE', '', '''Solarzorn'' ist eine Fernkampffähigkeit, die Schaden verursacht und Astrale Macht für mächtigere Angriffe erzeugt.', 25549),
(118504, 'deDE', '', '''Sternensog'' kostet Astrale Macht, die Ihr mit ''Solarzorn'' ansammeln könnt.', 25549),
(118503, 'deDE', '', '''Himmlische Ausrichtung'' ordnet die Sterne neu und erhöht kurzzeitig den Schaden durch Sonnen- und Mondzauber.', 25549),
(118502, 'deDE', '', '''Lunarschlag'' fügt dem Ziel direkten Schaden zu, trifft aber auch andere Gegner in der Nähe.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(118501, 'deDE', '', '''Wucherwurzeln'' lässt Wurzeln aus dem Boden hervorschnellen, die das Ziel für kurze Zeit festhalten.', 25549),
(118500, 'deDE', '', 'Als Gleichgewichtsdruide bekämpft Ihr Gegner mit der natürlichen Macht der Sonne, des Mondes und der Sterne.', 25549),
(118499, 'deDE', '', 'Mit der Mondkingestalt werdet Ihr zu einem Wildekin.', 25549),
(118498, 'deDE', '', 'Mit ''Mondfeuer'' und ''Sonnenfeuer'' lasst Ihr die Mächte von Tag und Nacht auf Eure Feinde niederfahren.', 25549),
(118497, 'deDE', '', 'Setzt ''Mondfeuer'' und ''Sonnenfeuer'' gegen die Zielattrappe ein.', 25549),
(118496, 'deDE', '', 'Diese beiden Angriffe verursachen regelmäßigen Schaden. Sie müssen nur dann erneuert werden, wenn ihr Effekt auf dem Ziel abgelaufen ist.', 25549),
(118495, 'deDE', '', 'Wenn der Gegner durch Eure anderen Angriffe Schaden erleidet, ist es Zeit für ''Solarzorn''.', 25549),
(118494, 'deDE', '', 'Setzt ''Solarzorn'' gegen die Zielattrappe ein.', 25549),
(118493, 'deDE', '', '''Sternensog'' ist einer Eurer stärksten Angriffe. Er feuert stellare Energie auf das Ziel ab.', 25549),
(118492, 'deDE', '', 'Setzt ''Solarzorn'' gegen die Zielattrappe ein, bis Ihr genug Astrale Macht für ''Sternensog'' habt.', 25549),
(118491, 'deDE', '', 'Manchmal will man einen Gegner festnageln, um sich ihm zu nähern... oder selbst den Rückzug anzutreten.', 25549),
(118490, 'deDE', '', 'Setzt ''Wucherwurzeln'' ein, um meinen Krieger zu verwurzeln.', 25549),
(118489, 'deDE', '', 'Zeigt mir, dass Ihr die Macht des Universums selbst bändigen könnt!', 25549),
(118488, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als $gGleichgewichtsdruide:Gleichgewichtsdruidin; kämpfen.', 25549),
(118487, 'deDE', '', 'Schadensschub gefällig? Schaut zu den Sternen!', 25549),
(118486, 'deDE', '', 'Verwendet ''Himmlische Ausrichtung'' und wirkt dann ''Solarzorn'' auf die Zielattrappe.', 25549),
(118485, 'deDE', '', 'Ein Gleichgewichtsdruide kann es mit mehreren Gegnern aufnehmen.', 25549),
(118484, 'deDE', '', 'Setzt ''Lunarschlag'' ein, um diese Gegner auszuschalten.', 25549),
(118483, 'deDE', '', 'Verwandelt Euch in Eure Mondkingestalt!', 25549),
(118482, 'deDE', '', '''Mondfeuer'' ist abgelaufen! Wirkt es erneut auf das Ziel!', 25549),
(118481, 'deDE', '', '''Sonnenfeuer'' ist abgelaufen! Wirkt es erneut auf das Ziel!', 25549),
(118480, 'deDE', '', 'Wirkt ''Mondfeuer''!', 25549),
(118479, 'deDE', '', 'Wirkt ''Sonnenfeuer''!', 25549),
(118478, 'deDE', '', 'Wirkt ''Solarzorn'', um Astrale Macht zu erzeugen!', 25549),
(118477, 'deDE', '', 'Wirkt ''Solarzorn''!', 25549),
(118456, 'deDE', '', 'Zurück in die Katzengestalt!', 25549),
(118455, 'deDE', 'Ich mache mich besser auf den Weg. Möchte ja nicht tot enden.', '', 25549),
(118454, 'deDE', 'Lasst Euch vom Schatten umarmen.', 'Lasst Euch vom Schatten umarmen.', 25549),
(118453, 'deDE', '', 'Versucht, das Ziel mit ''Wucherwurzeln'' festzuhalten!', 25549),
(118452, 'deDE', '', 'Versucht, das Ziel zu verwurzeln, bevor es Euch erreicht. Also los!', 25549),
(118451, 'deDE', '', 'Wirkt ''Wucherwurzeln''!', 25549),
(118450, 'deDE', '', '5 Combopunkte! Setzt jetzt ''Wilder Biss'' ein!', 25549),
(118449, 'deDE', '', 'Setzt ''Wilder Biss'' ein!', 25549),
(118448, 'deDE', '', 'Heilt Euch selbst mit ''Heilende Berührung''!', 25549),
(118447, 'deDE', '', 'Setzt ''Schleichen'' ein, um Euch zu tarnen!', 25549),
(118446, 'deDE', '', 'Setzt ''Krallenhieb'' ein!', 25549),
(118445, 'deDE', '', '''Krallenhieb'' ist abgelaufen! Verwendet ihn erneut!', 25549),
(118444, 'deDE', '', '5 Combopunkte! Setzt jetzt ''Zerfetzen'' ein!', 25549),
(118443, 'deDE', '', 'Setzt ''Zerfetzen'' ein!', 25549),
(118442, 'deDE', '', 'Setzt ''Schreddern'' ein, um Combopunkte zu erzeugen!', 25549),
(118441, 'deDE', '', 'Setzt ''Schreddern'' ein!', 25549),
(118440, 'deDE', '', 'Setzt ''Überlebensinstinkte'' ein!', 25549),
(118439, 'deDE', '', 'Mehrere Gegner! Versucht es mit ''Prankenhieb''!', 25549),
(118438, 'deDE', '', 'Setzt jetzt ''Prankenhieb'' ein!', 25549),
(118437, 'deDE', '', 'Erst ''Hauen'', dann ''Prankenhieb'' – eine mächtige Kombination!', 25549),
(118436, 'deDE', '', 'Setzt ''Hauen'' ein!', 25549),
(118435, 'deDE', '', 'Wenig Energie! Setzt ''Tigerfuror'' ein!', 25549),
(118434, 'deDE', '', 'Setzt ''Tigerfuror'' ein!', 25549),
(118433, 'deDE', '', 'Als Druide seid Ihr Experte darin, Euch schnell aus schwierigen Lagen zu befreien.', 25549),
(118432, 'deDE', '', '''Spurt'' macht Euch für kurze Zeit deutlich schneller. Die Fähigkeit ist nicht oft verfügbar, also setzt sie nur ein, wenn es wichtig ist.', 25549),
(118431, 'deDE', '', 'Setzt ''Spurt'' ein, um Eure Bewegungsgeschindigkeit zu erhöhen.', 25549),
(118430, 'deDE', '', 'Ihr könnt die Naturgewalten für eine Reihe von Fähigkeiten anrufen, zum Beispiel für Heilung!', 25549),
(118429, 'deDE', '', 'Wenn Ihr Schaden erlitten habt, heilt Euch mit ''Nachwachsen''.', 25549),
(118428, 'deDE', '', 'Heilt Euch vollständig mit ''Nachwachsen''.', 25549),
(118427, 'deDE', '', 'Viele Zauber zwingen Euch aus der Tiergestalt. Für den Kampf solltet Ihr wieder zur Katzengestalt wechseln!', 25549),
(118426, 'deDE', '', 'Wechselt in Katzengestalt.', 25549),
(118425, 'deDE', '', 'Alternativ zu ''Wilder Biss'' könnt Ihr ''Zerfetzen'' verwenden und regelmäßigen Blutungsschaden verursachen. Eine gute Gelegenheit, früh Combopunkte einzusetzen.', 25549),
(118424, 'deDE', '', 'Wie ''Wilder Biss'' ist auch ''Zerfetzen'' ein Finishing-Move. Am besten mit 5 Combopunkten einsetzen.', 25549),
(118423, 'deDE', '', 'Setzt mit 5 Combopunkten ''Zerfetzen'' gegen die Zielattrappe ein.', 25549),
(118422, 'deDE', '', 'Manchmal will man einen Gegner festnageln, um sich ihm zu nähern oder selbst den Rückzug anzutreten.', 25549),
(118421, 'deDE', '', '''Wucherwurzeln'' lässt Wurzeln aus dem Boden hervorschnellen, die das Ziel für kurze Zeit festhalten.', 25549),
(118420, 'deDE', '', 'Setzt ''Wucherwurzeln'' ein, um meinen Soldaten zu verwurzeln.', 25549),
(118419, 'deDE', '', 'In Katzengestalt könnt Ihr Euch im Kampf auf Eure animalischen Instinkte verlassen, um zu überleben.', 25549),
(118418, 'deDE', '', '''Überlebensinstinkte'' verringern für kurze Zeit Euren erlittenen Schaden. Haltet sie bereit für Notfälle!', 25549),
(118417, 'deDE', '', 'Setzt ''Überlebensinstinkte'' zur Schadensverringerung ein.', 25549),
(118416, 'deDE', '', '''Hauen'' ist nicht die einzige Waffe gegen mehrere Gegner.', 25549),
(118415, 'deDE', '', '''Prankenhieb'' verursacht in der Nähe Schaden, der durch Blutung noch erhöht wird. Setzt ''Hauen'' und ''Prankenhieb'' am besten zusammen ein.', 25549),
(118414, 'deDE', '', 'Setzt ''Prankenhieb'' gegen mehrere Gegner zugleich ein.', 25549),
(118413, 'deDE', '', 'Im Kampf gegen mehrere Gegner wird der Wildheitsdruide zum Wirbelwind aus Zähnen und Krallen und fügt allen Schaden zu.', 25549),
(118412, 'deDE', '', '''Hauen'' greift alle Gegner in der Nähe an und lässt sie für kurze Zeit bluten.', 25549),
(118411, 'deDE', '', 'Setzt ''Hauen'' gegen mehrere Gegner gleichzeitig ein.', 25549),
(118410, 'deDE', '', '''Hauen'' fügt den Gegnern für kurze Zeit weiter Schaden zu. Ihr müsst es also nicht erneut einsetzen, so lange es noch auf das Ziel wirkt.', 25549),
(118409, 'deDE', '', 'Zeigt mir, wie wild und listig Ihr kämpfen könnt!', 25549),
(118408, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als $gWildheitsdruide:Wildheitsdruidin; kämpfen.', 25549),
(118407, 'deDE', '', 'Im Kampf braucht Ihr die Katzengestalt!', 25549),
(118406, 'deDE', '', 'Ihr seid nicht in Katzengestalt!', 25549),
(118405, 'deDE', '', 'Als Wildheitsdruide ist Gestaltwandel Eure Hauptwaffe. In Katzengestalt zerfetzt Ihr Eure Gegner mit Zähnen und Klauen.', 25549),
(118404, 'deDE', '', 'Wenn sie geschwächt sind, geht Ihr ihnen mit einem mächtigen Finishing-Move an die Kehle.', 25549),
(118403, 'deDE', '', 'Mit ''Katzengestalt'' werdet Ihr zur Katze.', 25549),
(118402, 'deDE', '', 'Als Katze könnt Ihr Euch mit Euren Tarnfähigkeiten unbemerkt an Gegner heranschleichen. Durch ''Schleichen'' aktiviert Ihr den Tarnmodus.', 25549),
(118401, 'deDE', '', 'Setzt ''Schleichen'' ein, um Euch zu tarnen.', 25549),
(118400, 'deDE', '', 'Die Tarnung hält an, bis Ihr sie abbrecht, angreift oder Schaden erleidet.', 25549),
(118399, 'deDE', '', 'Euer Primärangriff ist ''Schreddern''.', 25549),
(118398, 'deDE', '', 'Das mächtige ''Schreddern'' fügt blutenden Zielen noch mehr Schaden zu, also haltet ''Krallenhieb'' aktiv.', 25549),
(118397, 'deDE', '', 'Setzt ''Schreddern'' gegen die durch ''Krallenhieb'' blutende Zielattrappe ein.', 25549),
(118396, 'deDE', '', 'Sowohl ''Schreddern'' als auch ''Krallenhieb'' erzeugen Combopunkte für mächtige Finishing-Moves.', 25549),
(118395, 'deDE', '', '''Wilder Biss'' ist ein Finishing-Move, der mit mehr Combopunkten auch mehr Schaden verursacht.', 25549),
(118394, 'deDE', '', 'Setzt ihn am besten ein, wenn Ihr 5 Combopunkte habt.', 25549),
(118393, 'deDE', '', 'Setzt ''Wilder Biss'' gegen die Zielattrappe ein, wenn Ihr über 5 Combopunkte verfügt.', 25549),
(118392, 'deDE', '', 'Nach dem Anschleichen an die Beute folgt der Angriff!', 25549),
(118391, 'deDE', '', '''Krallenhieb'' verursacht regelmäßigen Blutungsschaden.', 25549),
(118390, 'deDE', '', '''Schreddern'' fügt blutenden Zielen mehr Schaden zu. Diese Fähigkeiten lassen sich also gut kombinieren.', 25549),
(118389, 'deDE', '', '''Krallenhieb'' verursacht regelmäßigen Schaden. Ihr müsst ihn also nicht erneut einsetzen, solange er noch aktiv ist.', 25549),
(118388, 'deDE', '', 'Setzt ''Krallenhieb'' gegen die Zielattrappe ein.', 25549),
(118387, 'deDE', '', 'Die meisten Eurer Angriffe benötigen Energie. Wenn Ihr zu wenig Energie habt, könnt Ihr unter Umständen keine Fähigkeiten einsetzen.', 25549),
(118386, 'deDE', '', '''Tigerfuror'' regeneriert etwas Energie und erhöht kurzfristig den verursachten Schaden.', 25549),
(118385, 'deDE', '', 'Setzt ''Tigerfuror'' zur Energieregeneration ein und greift dann die Zielattrappe mit ''Schreddern'' an.', 25549),
(118384, 'deDE', '', 'Gegen härtere Gegner braucht man manchmal andere Fähigkeiten.', 25549),
(118340, 'deDE', 'Au weia! Was zur Hölle geht hier eigentlich vor?', '', 25549),
(118339, 'deDE', 'Das Licht ist bereit zu dienen.', 'Das Licht ist bereit zu dienen.', 25549),
(118284, 'deDE', 'Seht! Der Altar des Lichts und Schattens wird Eure Waffe mit seiner Macht erfüllen!', '', 25549),
(118283, 'deDE', '', 'Waffenkrieger sind perfekte Kämpfer, die alle, die sich ihnen entgegenstellen, mit ihrer Kampfkunst und ihren Waffen zerschmettern.', 25549),
(118282, 'deDE', '', 'Ihr könnt einen Gegner außer Reichweite nicht besiegen. Aber zum Glück gibt es dafür eine passende Fähigkeit.', 25549),
(118281, 'deDE', '', 'Setzt ''Sturmangriff'' ein, um auf diese Zielattrappe loszustürmen.', 25549),
(118280, 'deDE', '', 'Bei Erreichen des Ziels werden einfache Angriffe automatisch ausgeführt. Aber ein fähiger Streiter hält noch eine Reihe besonderer Fähigkeiten bereit.', 25549),
(118279, 'deDE', '', '''Tödlicher Stoß'' ist so ein Angriff. Verwendet ihn möglichst oft.', 25549),
(118278, 'deDE', '', 'Setzt ''Tödlicher Stoß'' gegen die Zielattrappe ein.', 25549),
(118277, 'deDE', '', 'Verursachter Schaden erzeugt Wut für verstärkte Angriffe. Investiert die Wut in ''Zerschmettern'', um dem Gegner Schaden zuzufügen.', 25549),
(118276, 'deDE', '', 'Setzt ''Zerschmettern'' gegen die Zielattrappe ein.', 25549),
(118275, 'deDE', '', 'Einer Eurer stärksten Angriffe ist ''Kolossales Schmettern''. Wenn Ihr ihn immer möglichst schnell einsetzt, ist Euch kaum ein Gegner gewachsen.', 25549),
(118274, 'deDE', '', 'Setzt ''Kolossales Schmettern'' gegen die Zielattrappe ein.', 25549),
(118273, 'deDE', '', 'Nach dem Sieg über den Gegner ist Euer Herz von Euphorie und Stolz erfüllt!', 25549),
(118272, 'deDE', '', '''Siegesrausch'' ist zeitlich begrenzt und heilt Euch, wenn Ihr damit einen neuen Gegner angreift.', 25549),
(118271, 'deDE', '', 'Besiegt einen Gegner und aktiviert damit ''Siegesrausch'' für den Kampf gegen den nächsten.', 25549),
(118270, 'deDE', '', '''Wirbelwind'' ist nicht der einzige Angriff gegen mehrere Gegner.', 25549),
(118269, 'deDE', '', 'Mit ''Spalten'' könnt Ihr mehrere Gegner vor Euch angreifen. Für jeden Treffer verursacht Euer nächster ''Wirbelwind'' mehr Schaden!', 25549),
(118268, 'deDE', '', 'Wirkt ''Spalten'' und ''Wirbelwind'' auf diese Gruppe von Gegnern.', 25549),
(118267, 'deDE', '', 'Zeigt mir, wie furchtlos und wild Ihr kämpft!', 25549),
(118266, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als $gWaffenkrieger:Waffenkriegerin; kämpfen.', 25549),
(118265, 'deDE', '', 'Krieger trödeln nicht! Probiert ''Sturmangriff'' aus, um auf einen Gegner loszustürmen!', 25549),
(118264, 'deDE', '', 'Setzt ''Spalten'' ein!', 25549),
(118263, 'deDE', '', '''Kolossales Schmettern'' ist bereit! Jetzt einsetzen!', 25549),
(118262, 'deDE', '', 'Setzt ''Kolossales Schmettern'' ein!', 25549),
(118261, 'deDE', '', '''Tödlicher Stoß'' ist bereit! Jetzt einsetzen!', 25549),
(118260, 'deDE', '', 'Setzt ''Tödlicher Stoß'' ein!', 25549),
(118259, 'deDE', '', 'Setzt ''Zerschmettern'' ein!', 25549),
(118258, 'deDE', '', '''Siegesrausch'' ist bereit! Jetzt einsetzen!', 25549),
(118257, 'deDE', '', 'Setzt ''Siegesrausch'' ein!', 25549),
(118256, 'deDE', '', '''Wirbelwind'' kann mehrere Gegner treffen!', 25549),
(118255, 'deDE', '', 'Setzt ''Wirbelwind'' ein!', 25549),
(118254, 'deDE', '', 'Selbst wenn Eure Gegner in der Überzahl sind, sollten sie Eure Macht nicht unterschätzen!', 25549),
(118253, 'deDE', '', 'Mit ''Wirbelwind'' könnt Ihr die Waffe in weitem Bogen schwingen, um eine blutige Schneise um Euch zu schlagen.', 25549),
(118252, 'deDE', '', 'Setzt ''Wirbelwind'' gegen diese Gegnergruppe ein.', 25549),
(118251, 'deDE', '', 'In der Hitze des Gefechts müsst Ihr manchmal schnell fliehen oder aber auf den Gegner losstürmen!', 25549),
(118250, 'deDE', '', 'Mit ''Heldenhafter Sprung'' erreicht Ihr schnell Eure Ziele auf dem Schlachtfeld.', 25549),
(118249, 'deDE', '', 'Übt ''Heldenhafter Sprung''.', 25549),
(118248, 'deDE', '', '''Agonie'' ist ein passender Name für Euren ersten Angriffszauber.', 25549),
(118247, 'deDE', '', 'Durch den zunehmend größeren regelmäßigen Schaden ist ''Agonie'' eine gute Kampferöffnung.', 25549),
(118246, 'deDE', '', 'Setzt ''Agonie'' gegen die Zielattrappe ein.', 25549),
(118245, 'deDE', '', 'Wenn Ihr ''Agonie'' gewirkt habt, müsst Ihr den Zauber erst kurz vor seinem Ablauf erneut wirken.', 25549),
(118244, 'deDE', '', 'Ihr fügt Jedem großes Leid zu, der töricht genug ist, Euch anzugreifen.', 25549),
(118243, 'deDE', '', '''Verderbnis'' fügt dem Ziel während seiner Effektdauer Schattenschaden zu.', 25549),
(118242, 'deDE', '', 'Setzt ''Verderbnis'' gegen die Zielattrappe ein.', 25549),
(118241, 'deDE', '', 'Wenn Ihr ''Verderbnis'' gewirkt habt, müsst Ihr den Zauber erst kurz vor Ablauf erneut wirken.', 25549),
(118240, 'deDE', '', 'Wenn Euer Ziel mit ''Agonie'' und ''Verderbnis'' geschwächt wurde, könnt Ihr ihm das Leben entziehen.', 25549),
(118239, 'deDE', '', 'Der beliebte Angriff ''Seelendieb'' fügt dem Gegner Schaden zu und heilt Euch zugleich.', 25549),
(118238, 'deDE', '', 'Setzt ''Seelendieb'' gegen die Zielattrappe ein.', 25549),
(118237, 'deDE', '', '''Agonie'' fügt dem Gegner Schaden zu und kann einen Seelensplitter zum Verstärken von Fähigkeiten erzeugen.', 25549),
(118236, 'deDE', '', '''Instabiles Gebrechen'' verursacht wie ''Agonie'' und ''Verderbnis'' regelmäßigen Schaden, verwendet aber einen Seelensplitter für mehr Schaden.', 25549),
(118235, 'deDE', '', 'Setzt ''Instabiles Gebrechen'' gegen die Zielattrappe ein.', 25549),
(118234, 'deDE', '', '''Instabiles Gebrechen'' verursacht regelmäßigen Schaden und wird mit jedem Einsatz mächtiger! Eine gute Waffe!', 25549),
(118233, 'deDE', '', 'Doch tut ihnen bitte nicht zu sehr weh. Ich brauche sie später noch.', 25549),
(118232, 'deDE', '', 'Gut gemacht, $p. Ihr könnt jetzt als $gGebrechenhexenmeister:Gebrechenhexenmeisterin; kämpfen.', 25549),
(118231, 'deDE', '', '''Agonie'' ist vorbei! Wirkt den Zauber erneut!', 25549),
(118230, 'deDE', '', 'Wirkt ''Agonie''!', 25549),
(118229, 'deDE', '', 'Für den erhöhten Schaden müsst Ihr ''Agonie'' noch einmal vor Ablauf wirken!', 25549),
(118228, 'deDE', '', '''Verderbnis'' ist vorbei! Wirkt den Zauber erneut!', 25549),
(118227, 'deDE', '', 'Wirkt ''Verderbnis''!', 25549),
(118226, 'deDE', '', 'Beschwört jetzt Eure Verdammniswache!', 25549),
(118225, 'deDE', '', 'Setzt ''Blutsauger'' gegen Euer Ziel ein!', 25549),
(118224, 'deDE', '', 'Setzt ''Blutsauger'' ein!', 25549),
(118223, 'deDE', '', 'Wirkt ''Furcht''!', 25549),
(118222, 'deDE', '', 'Mit dem Gesundheitsstein könnt Ihr Euch heilen!', 25549),
(118221, 'deDE', '', 'Wirkt ''Aderlass'', um Euer Mana aufzufüllen!', 25549),
(118220, 'deDE', '', 'Euer Leerwandler ist tot. ''Leerwandler beschwören'' bringt ihn zurück.', 25549),
(118219, 'deDE', '', '''Instabiles Gebrechen'' ist bereit! Jetzt wirken!', 25549),
(118218, 'deDE', '', 'Wirkt ''Instabiles Gebrechen''.', 25549),
(118217, 'deDE', '', 'Maximale Seelensplitter! Wirkt jetzt ''Instabiles Gebrechen''!', 25549),
(118216, 'deDE', '', 'Gebrechenhexenmeister schwächen Gegner mit Schattenmagie und Krankheiten und entziehen ihnen dann Lebenskraft, um selbst stärker zu werden.', 25549),
(118215, 'deDE', '', 'Mit Eurer dunklen Magie könnt Ihr dämonische Diener beschwören, die Euch gehorchen.', 25549),
(118214, 'deDE', '', 'Mit ''Leerwandler beschwören'' ruft Ihr einen Dämonendiener.', 25549),
(118213, 'deDE', '', 'Viele Zauber kosten eine Menge Mana, aber Ihr wisst dieses Problem clever zu umgehen.', 25549),
(118212, 'deDE', '', 'Mit ''Aderlass'' zapft Ihr Eure eigene Lebenskraft an, um Euer Mana aufzufüllen. Zum Ausgleich könnt Ihr den Gegner anzapfen, um Euch zu heilen.', 25549),
(118211, 'deDE', '', 'Setzt ''Aderlass'' zum Auffüllen von Mana ein.', 25549),
(118210, 'deDE', '', 'Manchmal sind Euch viele Gegner gleichzeitig oder ein besonders starker Gegner einfach überlegen.', 25549),
(118209, 'deDE', '', 'Um einen Gegner kurzzeitig vom Kämpfen abzuhalten, versetzt ihn in Angst und Schrecken.', 25549),
(118208, 'deDE', '', 'Benutzt ''Furcht'', um meinen Krieger in Angst und Schrecken zu versetzen.', 25549),
(118207, 'deDE', '', 'Mächtigere Dämonen wie Höllenbestien und Verdammniswachen lassen sich nicht lange kontrollieren. Aber für kurze Zeit könnt Ihr einen an Eurer Seite kämpfen lassen.', 25549),
(118206, 'deDE', '', 'Allerdings solltet Ihr Euch diesen Dämon für den Notfall aufsparen.', 25549),
(118205, 'deDE', '', 'Ruft den Dämon jetzt mit ''Verdammniswache beschwören''.', 25549),
(118204, 'deDE', '', 'Ein Teil Eurer Kraft kann in den Gesundheitsstein einfließen. Bei Schaden könnt Ihr Euch selbst mit dem Gesundheitsstein heilen.', 25549),
(118203, 'deDE', '', 'Wirkt ''Gesundheitsstein herstellen''.', 25549),
(118202, 'deDE', '', 'Heilt jetzt einen Teil des erlittenen Schadens mit dem Gesundheitsstein.', 25549),
(118201, 'deDE', '', 'Heilt jetzt einen Teil des erlittenen Schadens mit dem Gesundheitsstein.', 25549),
(118200, 'deDE', '', 'Erstaunlich! Eure Kontrolle über Dämonen hat Euch große Macht verliehen!', 25549),
(118199, 'deDE', '', 'Ein vorbereiteter Hexenmeister kann alles überleben... selbst den Tod!', 25549),
(118198, 'deDE', '', 'Mit dem Seelenstein könnt Ihr Eure Seele für später aufbewahren. Keine Sorge, Ihr habt ja ohnehin keine Verwendung mehr für sie! Mit gesicherter Seele könnt Ihr von den Toten auferstehen.', 25549),
(118197, 'deDE', '', 'Setzt ''Seelenstein'' ein, um den Tod zu überstehen.', 25549),
(118196, 'deDE', '', 'Als Verstärkungsschamane kanalisiert Ihr die Elementarmächte direkt in Eure Waffen und macht Euch zum wilden Nahkämpfer, der Gegner mit der Macht der Flammen, Erde oder Stürme schlägt.', 25549),
(118195, 'deDE', '', 'Als ersten Angriff probieren wir ''Flammenzunge'' aus, der Eure Waffen mit Flammen umhüllt und Gegner verbrennt.', 25549),
(118194, 'deDE', '', 'Setzt ''Flammenzunge'' gegen die Zielattrappe ein.', 25549),
(118193, 'deDE', '', 'Mit brennenden Waffen könnt Ihr Euch auf den primären Angriff konzentrieren.', 25549),
(118192, 'deDE', '', '''Felsbeißer'' ermächtigt Eure Waffen, um mit Erdmacht Schaden zuzufügen.', 25549),
(118191, 'deDE', '', 'Setzt ''Felsbeißer'' gegen die Zielattrappe ein.', 25549),
(118190, 'deDE', '', '''Felsbeißer'' erzeugt Mahlstrom, eine Ressource, die stärkere Angriffe ermöglicht.', 25549),
(118189, 'deDE', '', '''Lavapeitsche'' braucht Mahlstrom, um Eure Schildhandwaffe mit Lava zu laden und mächtige Schläge auszuführen.', 25549),
(118188, 'deDE', '', 'Setzt ''Lavapeitsche'' gegen die Zielattrappe ein.', 25549),
(118187, 'deDE', '', 'Die mächtigste Mahlstromfähigkeit ist ''Sturmschlag''.', 25549),
(118186, 'deDE', '', 'Setzt ''Sturmschlag'' immer nach ''Sturmbringer'' ein.', 25549),
(118185, 'deDE', '', 'Setzt nach ''Sturmbringer'' den ''Sturmschlag'' gegen die Zielattrappe ein.', 25549),
(118184, 'deDE', '', 'Setzt ''Sturmschlag'' ein!', 25549),
(118183, 'deDE', '', 'Wenn Ihr gegen mehrere Feinde kämpft, ist es an der Zeit, den ''Zorn der Stürme'' zu entfesseln!', 25549),
(118182, 'deDE', '', '''Tobende Blitze'' fügen allen Zielen vor Euch Schaden zu. Mehrere Ziele zu treffen verstärkt Eure Waffen und verursacht mehr Schaden!', 25549),
(118181, 'deDE', '', 'Wirkt ''Tobende Blitze'', um diese Gegner auszuschalten.', 25549),
(118180, 'deDE', '', 'Wenn Ihr in einem Kampf zu viel abkriegt, kann ''Schamanistische Wut'' den Schaden für kurze Zeit verringern. Probiert es!', 25549),
(118179, 'deDE', '', 'Setzt ''Schamanistische Wut'' ein, um Schaden zu verringern.', 25549),
(118178, 'deDE', '', 'Zeigt mir, dass Ihr mit dem Zorn der Elemente kämpft!', 25549),
(118177, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als $gVerstärkungsschamane:Verstärkungsschamanin; kämpfen.', 25549),
(118176, 'deDE', '', 'Setzt ''Tobende Blitze'' ein!', 25549),
(118175, 'deDE', '', 'Setzt ''Wildgeist'' ein!', 25549),
(118174, 'deDE', '', '''Flammenzunge'' ist abgelaufen! Setzt ''Flammenzunge'' ein!', 25549),
(118173, 'deDE', '', 'Setzt ''Flammenzunge'' ein!', 25549),
(118172, 'deDE', '', '''Lavapeitsche'' ist bereit! Jetzt einsetzen!', 25549),
(118171, 'deDE', '', 'Setzt ''Lavapeitsche'' ein!', 25549),
(118170, 'deDE', '', 'Maximaler Mahlstrom! Setzt ''Lavapeitsche'' ein!', 25549),
(118169, 'deDE', '', 'Setzt ''Felsbeißer'' ein, um Mahlstrom zu erzeugen!', 25549),
(118168, 'deDE', '', 'Setzt ''Felsbeißer'' ein!', 25549),
(118167, 'deDE', '', '''Sturmbringer'' wurde ausgelöst! Setzt jetzt ''Sturmschlag'' ein!', 25549),
(118166, 'deDE', '', 'Setzt ''Sturmschlag'' ein!', 25549),
(118165, 'deDE', '', 'Ihr besitzt eine Verbindung mit Tiergeistern, wie Wölfen.', 25549),
(118164, 'deDE', '', 'Wenn Ihr Schwierigkeiten im Kampf habt, könnt Ihr zwei wilde Wolfsgeister an Eure Seite beschwören.', 25549),
(118163, 'deDE', '', 'Setzt ''Wildgeist'' ein, um Euren Schaden im Kampf zu erhöhen!', 25549),
(118162, 'deDE', '', 'Als Elementarschamane kommuniziert Ihr mit uralten Geistern und kontrolliert Elementarmächte.', 25549),
(118161, 'deDE', '', '''Flammenschock'' setzt Gegner in Flammen und verbrennt sie, während Ihr andere Zauber wirkt.', 25549),
(118160, 'deDE', '', 'Ausgezeichnet! Setzt regelmäßig ''Flammenschock'' ein, damit Eure Gegner weiterbrennen.', 25549),
(118159, 'deDE', '', 'Setzt ''Flammenschock'' gegen die Zielattrappe ein.', 25549),
(118158, 'deDE', '', 'Warum bei Feuer aufhören? Wenn Feinde brennen, könnt Ihr flüssige Lava auf sie schleudern.', 25549),
(118157, 'deDE', '', 'Ist ''Flammenschock'' auf dem Ziel aktiv, wird der Schaden von ''Lavaeruption'' erhöht.', 25549),
(118156, 'deDE', '', 'Setzt ''Lavaeruption'' gegen die Zielattrappe ein.', 25549),
(118155, 'deDE', '', 'Um Gegner zu überwinden, schleudert Ihr hauptsächlich Blitze aus Euren Händen.', 25549),
(118154, 'deDE', '', 'Setzt ''Blitzschlag'' ein, wenn keine andere Fähigkeit bereit ist.', 25549),
(118153, 'deDE', '', 'Setzt ''Blitzschlag'' gegen die Zielattrappe ein.', 25549),
(118152, 'deDE', '', '''Erdschock'' gehört zu Euren stärksten Zaubern. Er benötigt Mahlstrom, der durch Eure anderen Angriffe erzeugt wird.', 25549),
(118151, 'deDE', '', 'Setzt ''Erdschock'' gegen die Zielattrappe ein.', 25549),
(118150, 'deDE', '', 'Wirkt ''Blitzschlag'' bei der Zielattrappe, bis Euer Mahlstrom maximal aufgeladen ist und wirkt dann ''Erdschock''.', 25549),
(118149, 'deDE', '', 'Wenn Ihr im Kampf umzingelt werdet, könnt Ihr mit ''Gewitter'' Gegner zurückstoßen und Euch Freiraum schaffen.', 25549),
(118148, 'deDE', '', 'Wirkt ''Gewitter'', um Feinde um Euch herum zurückzustoßen!', 25549),
(118147, 'deDE', '', '$p, entfesselt die Elemente, um zu siegen!', 25549),
(118146, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als $gElementarschamane:Elementarschamanin; kämpfen.', 25549),
(118145, 'deDE', '', 'Setzt ''Kettenblitzschlag'' ein!', 25549),
(118144, 'deDE', '', 'Maximaler Mahlstrom! Wirkt ''Erdschock''!', 25549),
(118143, 'deDE', '', 'Wirkt ''Erdschock''!', 25549),
(118142, 'deDE', '', 'Wirkt ''Erdschock'', wenn Euer Mahlstrom das Maximum erreicht hat.', 25549),
(118141, 'deDE', '', 'Setzt ''Feuerelementar'' ein!', 25549),
(118140, 'deDE', '', 'Verbrennt Euren Feind mit ''Flammenschock''!', 25549),
(118139, 'deDE', '', 'Wirkt ''Flammenschock''!', 25549),
(118138, 'deDE', '', 'Wirkt ''Flammenschock'' nur, wenn er bald abläuft!', 25549),
(118137, 'deDE', '', 'Heilt Euch selbst mit ''Heilende Woge''!', 25549),
(118136, 'deDE', '', 'Wirkt ''Lavaeruption'', während der Gegner brennt!', 25549),
(118135, 'deDE', '', 'Wirkt ''Lavaeruption''!', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(118134, 'deDE', '', 'Bei einem durch ''Flammenschock'' brennenden Feind erhöht ''Lavaeruption'' den Schaden!', 25549),
(118133, 'deDE', '', 'Wirkt ''Blitzschlag''!', 25549),
(118132, 'deDE', '', 'Setzt ''Gewitter'' ein, um Gegner zurückzustoßen!', 25549),
(118131, 'deDE', '', 'Wolltet Ihr schon immer jemanden zum Frosch machen? Das geht mit ''Verhexen''!', 25549),
(118130, 'deDE', '', 'Als Frosch wird Euer Ziel nicht angreifen, doch der Effekt ist vorübergehend. Wird der Frosch angegriffen, verwandelt er sich zurück.', 25549),
(118129, 'deDE', '', 'Verwandelt meinen Krieger in einen Frosch!', 25549),
(118128, 'deDE', '', 'Manchmal stehen Euch auf dem Schlachtfeld mehrere Gegner gegenüber. Glücklicherweise habt Ihr dafür den ''Kettenblitzschlag''.', 25549),
(118127, 'deDE', '', 'Wenn Ihr Gegner mit ''Kettenblitzschlag'' trefft, springt der Blitz über und fügt allen Gegnern in der Nähe Schaden zu.', 25549),
(118126, 'deDE', '', 'Setzt ''Kettenblitzschlag'' gegen mehrere Gegner gleichzeitig ein.', 25549),
(118125, 'deDE', '', 'Ihr habt Schaden erlitten – für Euch aber kein Problem.', 25549),
(118124, 'deDE', '', 'Die Elemente können zerstören, doch ebenso können sie wiederherstellen.', 25549),
(118123, 'deDE', '', 'Setzt ''Heilende Woge'' ein, um Eure Gesundheit aufzufüllen!', 25549),
(118122, 'deDE', '', 'Als Meister der Elemente könnt Ihr den Elementarmächten Körper schenken, damit sie Euch im Kampf unterstützen.', 25549),
(118121, 'deDE', '', 'Ruft Euren Elementar jetzt mit ''Feuerelementar''!', 25549),
(118120, 'deDE', '', 'Als Meuchelschurke spezialisiert Ihr Euch auf Angriffe aus den Schatten, um Gegner mit einer Vielzahl von Giften und Blutungen auszuschalten.', 25549),
(118119, 'deDE', '', 'Bevor wir anfangen, müssen wir Eure Waffe mit Gift bestreichen.', 25549),
(118118, 'deDE', '', 'Setzt ''Tödliches Gift'' ein, um Eure Waffe für eine Stunde zu vergiften.', 25549),
(118117, 'deDE', '', 'Meuchelmörder nutzen Täuschung und List. Und was ist listiger, als anzugreifen, bevor Euer Ziel Euch sieht?', 25549),
(118116, 'deDE', '', 'Durch ''Verstohlenheit'' seid Ihr für die meisten Gegner unsichtbar und könnt Euch unbemerkt nähern.', 25549),
(118115, 'deDE', '', 'Setzt ''Verstohlenheit'' ein, um Euch zu verbergen.', 25549),
(118114, 'deDE', '', 'Als Meuchelschurke schwächt Ihr Feinde, bevor Ihr es zu Ende bringt.', 25549),
(118113, 'deDE', '', 'Am besten beginnt Ihr den Kampf mit ''Erdrosseln'', einer schwächenden Blutung, die Eurem Gegner regelmäßigen Schaden zufügt.', 25549),
(118112, 'deDE', '', 'Setzt ''Erdrosseln'' gegen die Zielattrappe ein.', 25549),
(118111, 'deDE', '', 'Setzt ''Erdrosseln'' wiederholt ein, damit Eure Gegner weiterbluten.', 25549),
(118110, 'deDE', '', 'Euer Hauptangriff ist ''Verstümmeln''. Er verursacht Schaden und erzeugt Combopunkte, die mächtige Finishing-Moves ermöglichen.', 25549),
(118109, 'deDE', '', 'Setzt ''Verstümmeln'' gegen die Zielattrappe ein.', 25549),
(118108, 'deDE', '', 'Da Ihr jetzt 5 Combopunkte habt, solltet Ihr ''Blutung'' einsetzen.', 25549),
(118107, 'deDE', '', 'Wenn Ihr mit 5 Combopunkten ''Blutung'' einsetzt, entsteht eine stark blutende Wunde, die regelmäßig Schaden verursacht.', 25549),
(118106, 'deDE', '', 'Setzt mit 5 Combopunkten ''Blutung'' ein.', 25549),
(118105, 'deDE', '', '''Blutung'' ist nicht Euer einziger Finishing-Move.', 25549),
(118104, 'deDE', '', 'Wenn Euer Ziel von ''Blutung'' betroffen ist, könnt Ihr für 5 Combopunkte ''Vergiften'' einsetzen, viel Schaden verursachen und den Effekt Eurer Gifte maximieren.', 25549),
(118103, 'deDE', '', 'Setzt mit 5 Combopunkten ''Vergiften'' ein.', 25549),
(118102, 'deDE', '', 'Ihr habt Schaden erlitten, doch schlaue Schurken sind vorbereitet.', 25549),
(118101, 'deDE', '', '''Blutrote Phiole'' ist ein Gebräu, das einen Teil Eurer Gesundheit wiederherstellt.', 25549),
(118100, 'deDE', '', 'Setzt ''Blutrote Phiole'' ein, um Euch ein wenig zu heilen.', 25549),
(118099, 'deDE', '', 'Es gibt Zeiten, in denen Ihr Euch einem Ziel nähern wollen werdet, ohne gleich Schaden zuzufügen.', 25549),
(118098, 'deDE', '', 'Bei ''Schattenschritt'' bleibt Ihr in Verstohlenheit und seid zum Angriff bereit.', 25549),
(118097, 'deDE', '', 'Setzt ''Schattenschritt'' ein und taucht hinter einem Ziel auf.', 25549),
(118096, 'deDE', '', 'Gegner, die Euch umzingeln wollen, erwartet eine böse Überraschung!', 25549),
(118095, 'deDE', '', '''Dolchfächer'' entfesselt Schaden, der alle Gegner um Euch herum trifft. Außerdem erhaltet Ihr einen Combopunkt pro getroffenem Gegner.', 25549),
(118094, 'deDE', '', 'Benutzt ''Dolchfächer'', um diese Gegner auszuschalten.', 25549),
(118093, 'deDE', '', 'Zeigt mir, was Ihr könnt, $p!', 25549),
(118092, 'deDE', '', 'Gut gemacht, $p. Ihr könnt jetzt als $gMeuchelschurke:Meuchelschurkin; kämpfen.', 25549),
(118091, 'deDE', '', 'Setzt ''Blutrote Phiole'' ein, um Euch zu heilen!', 25549),
(118090, 'deDE', '', '5 Combopunkte! Setzt jetzt ''Vergiften'' ein!', 25549),
(118089, 'deDE', '', 'Setzt ''Vergiften'' ein!', 25549),
(118088, 'deDE', '', 'Euch erwarten mehrere Gegner. Setzt ''Dolchfächer'' ein!', 25549),
(118087, 'deDE', '', 'Setzt ''Dolchfächer'' ein!', 25549),
(118086, 'deDE', '', 'Setzt ''Erdrosseln'' ein, damit der Gegner blutet!', 25549),
(118085, 'deDE', '', 'Setzt ''Erdrosseln'' ein!', 25549),
(118084, 'deDE', '', 'Setzt ''Verstümmeln'' ein!', 25549),
(118083, 'deDE', '', 'Setzt ''Verstümmeln'' ein, um Combopunkte zu erzeugen!', 25549),
(118082, 'deDE', '', 'Bestreicht Eure Waffe mit tödlichem Gift.', 25549),
(118081, 'deDE', '', '5 Combopunkte! Setzt jetzt ''Blutung'' ein!', 25549),
(118080, 'deDE', '', 'Setzt ''Blutung'' ein!', 25549),
(118079, 'deDE', '', 'Setzt ''Schattenschritt'' ein!', 25549),
(118078, 'deDE', '', 'Aus der Verstohlenheit anzugreifen ist wirksamer.', 25549),
(118077, 'deDE', '', 'Ihr seid in Gefahr! Setzt ''Verschwinden'' ein!', 25549),
(118076, 'deDE', '', 'Jetzt müsst Ihr noch eine Sache lernen.', 25549),
(118075, 'deDE', '', 'Manchmal ist ein Rückzug notwendig, damit Ihr später weiterkämpfen könnt.', 25549),
(118074, 'deDE', '', 'Setzt ''Verschwinden'' ein, um meinem Krieger auszuweichen.', 25549),
(118073, 'deDE', '', 'Disziplinpriester nutzen die gegensätzlichen Mächte von Licht und Schatten und entscheiden, wann sie heilen oder schaden.', 25549),
(118072, 'deDE', '', '''Schattenwort: Schmerz'' schlägt Gegner mit Schattenenergie und verursacht regelmäßigen Schaden.', 25549),
(118071, 'deDE', '', 'Setzt ''Schattenwort: Schmerz'' gegen die Zielattrappe ein.', 25549),
(118070, 'deDE', '', 'Wenn Euer Ziel von ''Schattenwort: Schmerz'' betroffen ist, müsst Ihr den Zauber erst kurz vor Ablauf erneut wirken.', 25549),
(118069, 'deDE', '', 'Das Licht ist ein beachtlicher Verbündeter, der Freunde heilen und Feinde niederstrecken kann.', 25549),
(118068, 'deDE', '', '''Sühne'' ist ein wirksamer Zauber, der Euren Gegnern schadet. Setzt ihn so oft wie möglich ein.', 25549),
(118067, 'deDE', '', 'Setzt ''Sühne'' gegen die Zielattrappe ein.', 25549),
(118066, 'deDE', '', 'Die Macht des Lichts ermöglicht es, einem Gegner vor Euch ''Heilige Pein'' zuzufügen!', 25549),
(118065, 'deDE', '', 'Euer meistgenutzter Schadenszauber, optimal eingesetzt, wenn ''Sühne'' nicht bereit ist.', 25549),
(118064, 'deDE', '', 'Setzt ''Heilige Pein'' gegen die Zielattrappe ein.', 25549),
(118063, 'deDE', '', 'Befehlt Mächte von Licht und Schatten, um den Sieg zu erringen!', 25549),
(118062, 'deDE', '', 'Gut gemacht, $p. Ihr könnt jetzt als $gDisziplinpriester:Disziplinpriesterin; kämpfen.', 25549),
(118061, 'deDE', '', '''Sühne'' ist bereit! Jetzt wirken!', 25549),
(118060, 'deDE', '', 'Wirkt jetzt ''Sühne''!', 25549),
(118059, 'deDE', '', 'Wirkt ''Bittgebet'', um Euch zu heilen!', 25549),
(118058, 'deDE', '', 'Wirkt ''Machtwort: Schild'', um Euch zu schützen!', 25549),
(118057, 'deDE', '', 'Wirkt ''Psychischer Schrei''!', 25549),
(118056, 'deDE', '', '''Schattenwort: Schmerz'' ist abgelaufen! Wirkt es erneut!', 25549),
(118055, 'deDE', '', 'Wirkt ''Schattenwort: Schmerz''!', 25549),
(118054, 'deDE', '', 'Ihr müsst ''Schattenwort: Schmerz'' nicht erneut wirken, wenn das vorherige noch eine Weile anhält.', 25549),
(118053, 'deDE', '', 'Wirkt ''Heilige Pein''!', 25549),
(118052, 'deDE', '', 'Anhänger des Lichts können Gesundheit vielseitig schützen und wiederherstellen.', 25549),
(118051, 'deDE', '', 'Eine Eurer nützlichsten Verteidigungen ist ''Machtwort: Schild'', das sämtlichen Schaden absorbiert.', 25549),
(118050, 'deDE', '', 'Denkt daran, Euren Schild in Kämpfen aufrechtzuerhalten.', 25549),
(118049, 'deDE', '', 'Wirkt ''Machtwort: Schild'', um diesen Schaden zu verhindern.', 25549),
(118048, 'deDE', '', 'In manchen Kämpfen habt Ihr es gleichzeitig mit mehreren Gegnern zu tun.', 25549),
(118047, 'deDE', '', 'Zum Glück könnt Ihr Euch auch verteidigen. ''Psychischer Schrei'' verängstigt nahe Gegner und schlägt sie so in die Flucht.', 25549),
(118046, 'deDE', '', 'Wirkt ''Psychischer Schrei'', um diese Gegner von Euch fernzuhalten.', 25549),
(118045, 'deDE', '', '''Machtwort: Schild'' hat Euch vor dem ersten Magierangriff geschützt, doch der zweite hat Euch verletzt.', 25549),
(118044, 'deDE', '', 'Für Euch ist dies kein Problem. Das Licht gibt Euch die Macht, Eure Gesundheit oder die Eurer Verbündeten wiederherzustellen.', 25549),
(118043, 'deDE', '', 'Wirkt ''Bittgebet'', um Eure Wunden zu heilen.', 25549),
(118042, 'deDE', '', 'Als Vergeltungspaladin seid Ihr ein tapferer Beschützer der Schwachen und Bestrafer der Ungerechten!', 25549),
(118041, 'deDE', '', 'Ihr greift mit Fernkampfzaubern und Nahkampf an, die Heilige Kraft erzeugen und entfesseln.', 25549),
(118040, 'deDE', '', 'Die Hingabe zum Licht lässt Euch Gegner ein mächtiges ''Richturteil'' entgegenwerfen.', 25549),
(118039, 'deDE', '', 'Setzt ''Richturteil'' gegen die Zielattrappe ein.', 25549),
(118038, 'deDE', '', 'Wenn ''Richturteil'' bereit ist, könnt Ihr es gegen nahe und ferne Gegner einsetzen.', 25549),
(118037, 'deDE', '', 'Schlagt ankommende Gegner auf mittlerer Reichweite mit ''Klinge der Gerechtigkeit''.', 25549),
(118036, 'deDE', '', 'Setzt ''Klinge der Gerechtigkeit'' gegen die Zielattrappe ein.', 25549),
(118035, 'deDE', '', '''Klinge der Gerechtigkeit'' ist ausgezeichnet, um näherkommenden Gegnern zu schaden.', 25549),
(118034, 'deDE', '', 'Wenn der Gegner in Angriffsnähe ist, setzt ''Kreuzfahrerstoß'' ein.', 25549),
(118033, 'deDE', '', 'Verwendet ''Kreuzfahrerstoß'' gegen diese Zielattrappe.', 25549),
(118032, 'deDE', '', 'Mit ''Klinge der Gerechtigkeit'' und ''Kreuzfahrerstoß'' erzeugt Ihr im Kampf Heilige Kraft.', 25549),
(118031, 'deDE', '', 'Entfesselt diese göttliche Magie mit dem mächtigen Nahkampfangriff ''Urteil des Templers'', der Eure Waffe mit der Macht des Lichts erfüllt.', 25549),
(118030, 'deDE', '', 'Sammelt Heilige Kraft durch Angriffe und setzt dann ''Urteil des Templers'' gegen diese Zielattrappe ein.', 25549),
(118029, 'deDE', '', 'Zeigt mir Euren Mut und Eifer in der Hitze des Gefechts!', 25549),
(118028, 'deDE', '', 'Gut gemacht, $p. Ihr könnt jetzt als Vergeltungspaladin kämpfen.', 25549),
(118027, 'deDE', '', '''Klinge der Gerechtigkeit'' ist bereit! Jetzt einsetzen!', 25549),
(118026, 'deDE', '', 'Benutzt ''Klinge der Gerechtigkeit''!', 25549),
(118025, 'deDE', '', 'Setzt ''Kreuzfahrerstoß'' ein, um Heilige Kraft zu erzeugen!', 25549),
(118024, 'deDE', '', 'Setzt ''Kreuzfahrerstoß'' ein!', 25549),
(118023, 'deDE', '', 'Ihr seid in Gefahr! Wirkt ''Gottesschild'', um Euch zu retten!', 25549),
(118022, 'deDE', '', 'Wirkt ''Gottesschild''!', 25549),
(118021, 'deDE', '', 'Setzt ''Lichtblitz'' ein, um Euch selbst zu heilen!', 25549),
(118020, 'deDE', '', '''Richturteil'' ist eine Distanzfähigkeit. Setzt sie aus der Ferne ein!', 25549),
(118019, 'deDE', '', '''Richturteil'' ist bereit! Jetzt einsetzen!', 25549),
(118018, 'deDE', '', 'Setzt ''Richturteil'' ein!', 25549),
(118017, 'deDE', '', '''Urteil des Templers'' ist bereit! Jetzt einsetzen!', 25549),
(118016, 'deDE', '', 'Benutzt ''Urteil des Templers!''', 25549),
(118015, 'deDE', '', 'Ihr habt maximale Heilige Kraft! Setzt ''Urteil des Templers'' ein!', 25549),
(118014, 'deDE', '', 'Ihr geratet in viele gefährliche Situationen. Gute Vorbereitung kann Euch das Leben retten.', 25549),
(118013, 'deDE', '', '''Gottesschild'' verhindert, dass Euch Angriffe Schaden zufügen.', 25549),
(118012, 'deDE', '', 'Wirkt ''Gottesschild'', um Euch vorübergehend unverwundbar zu machen!', 25549),
(118011, 'deDE', '', '''Gottesschild'' schützt Euch für kurze Zeit vor allen Angriffen, also hebt ihn für Notfälle auf.', 25549),
(118010, 'deDE', '', '''Gottesschild'' hat Euch vor dem ersten Magierangriff geschützt, doch der zweite hat Euch verletzt.', 25549),
(118009, 'deDE', '', 'Ihr könnt Euch und Eure Verbündeten durch Euren Glauben heilen. ''Lichtblitz'' ist der Eckpfeiler Eurer Heilung.', 25549),
(118008, 'deDE', '', 'Wirkt ''Lichtblitz'', um Eure Wunden zu heilen.', 25549),
(118007, 'deDE', '', 'Als Windläufermönch nutzt Ihr Fäuste und Geschwindigkeit, um Gegner zu überwinden.', 25549),
(118006, 'deDE', '', 'Dabei erzeugt Ihr Chi, eine Ressource, durch die Ihr mächtige Angriffe ausführen könnt.', 25549),
(118005, 'deDE', '', 'Setzt Euren Primärangriff ''Tigerklaue'' ein, um Schaden zu verursachen und Chi zu erzeugen.', 25549),
(118004, 'deDE', '', 'Setzt ''Tigerklaue'' gegen die Zielattrappe ein.', 25549),
(118003, 'deDE', '', 'Wenn Ihr den Kampf mit ''Tigerklaue'' beginnt, habt Ihr genügend Chi, um den mächtigen ''Tritt der aufgehenden Sonne'' für 2 Chi zu entfesseln, der viel Schaden verursacht.', 25549),
(118002, 'deDE', '', 'Verwendet ihn so oft wie möglich.', 25549),
(118001, 'deDE', '', 'Setzt ''Tritt der aufgehenden Sonne'' gegen die Zielattrappe ein.', 25549),
(118000, 'deDE', '', 'Nicht so stark, wie der ''Tritt der aufgehenden Sonne'', doch auch der ''Blackout-Tritt'' tut ordentlich weh!', 25549),
(117999, 'deDE', '', 'Er trifft deutlich härter als ''Tigerklaue'', also verwendet zusätzliches Chi für ''Blackout-Tritt''.', 25549),
(117998, 'deDE', '', 'Setzt ''Blackout-Tritt'' gegen die Zielattrappe ein.', 25549),
(117997, 'deDE', '', 'Euch stehen reichlich Angriffe zur Verfügung, Windläufer! Die ''Furorfäuste'' kosten 3 Chi und verursachen viel Schaden.', 25549),
(117996, 'deDE', '', 'Damit trefft Ihr zusätzliche Ziele neben Eurem Ziel. Setzt ''Furorfäuste'' so oft wie möglich ein, besonders bei mehreren Gegnern.', 25549),
(117995, 'deDE', '', 'Setzt ''Furorfäuste'' gegen die Zielattrappe ein.', 25549),
(117994, 'deDE', '', '''Rollen'' ist nicht Eure einzige Bewegungsfähigkeit. Windläufermönche können sich auch in die Luft schwingen und auf Ziele zurasen.', 25549),
(117993, 'deDE', '', 'Setzt ''Fliegender Schlangentritt'' ein, um zu einem Gegner zu fliegen. Wenn Ihr ihn in der Luft erneut einsetzt, endet der Flug und Ihr schadet Gegnern in Eurer Nähe.', 25549),
(117992, 'deDE', '', 'Setzt ''Fliegender Schlangentritt'' ein, um zur Zielattrappe zu fliegen und ihr zu schaden.', 25549),
(117991, 'deDE', '', 'Manchmal seid Ihr der Lage nicht mehr gewachsen und steht zu vielen Gegnern gegenüber.', 25549),
(117990, 'deDE', '', 'Wollt Ihr einen Gegner aus dem Gefecht nehmen? ''Paralysieren'' macht ihn kurze Zeit bewusstlos. Durch Schaden kommt er aber wieder zu sich.', 25549),
(117989, 'deDE', '', 'Paralysiert den angreifenden Soldaten.', 25549),
(117988, 'deDE', '', 'Zeigt mir die Kraft und Beweglichkeit eines Windläufers!', 25549),
(117987, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als Mönch kämpfen.', 25549),
(117986, 'deDE', '', 'Setzt ''Blackout-Tritt'' ein!', 25549),
(117985, 'deDE', '', 'Maximales Chi! Benutzt jetzt ''Blackout-Tritt''!', 25549),
(117984, 'deDE', '', 'Heilt Euch selbst mit ''Überschwang''!', 25549),
(117983, 'deDE', '', '''Furorfäuste'' ist bereit! Jetzt einsetzen!', 25549),
(117982, 'deDE', '', 'Setzt ''Furorfäuste'' ein!', 25549),
(117981, 'deDE', '', 'Setzt ''Fliegender Schlangentritt'' ein!', 25549),
(117980, 'deDE', '', '''Tritt der aufgehenden Sonne'' ist bereit! Jetzt einsetzen!', 25549),
(117979, 'deDE', '', 'Setzt ''Tritt der aufgehenden Sonne'' ein!', 25549),
(117978, 'deDE', '', 'Rollt, rollt, rollt!', 25549),
(117977, 'deDE', '', 'Setzt ''Tigerklaue'' ein, um Chi zu erzeugen!', 25549),
(117976, 'deDE', '', 'Setzt ''Tigerklaue'' ein!', 25549),
(117975, 'deDE', '', 'Ihr seid schnell und agil. Ihr könnt im Kampf nach Belieben herumflitzen.', 25549),
(117974, 'deDE', '', 'Der Schlüssel zur Mobilität der Mönche ist ''Rollen''. Damit könnt Ihr schnell ordentliche Strecken in Bewegungsrichtung zurücklegen.', 25549),
(117973, 'deDE', '', 'Übt einige Male ''Rollen''.', 25549),
(117972, 'deDE', '', 'Verletzungen gehören zum Kampf dazu, doch Ihr könnt Euch oder Verbündete durch die Nebel heilen. Heilt Eure Wunden mit ''Überschwang''.', 25549),
(117971, 'deDE', '', 'Setzt ''Überschwang'' ein, um Eure Gesundheit aufzufüllen!', 25549),
(117970, 'deDE', '', 'Als Frostmagier könnt Ihr das Schlachtfeld überragend kontrollieren, indem Ihr Gegner einfriert und dann Eis auf sie hinabschmettern lasst.', 25549),
(117969, 'deDE', '', 'Eure Kontrolle über das Eis erlaubt Euch, Wasserelementare als Diener zu rufen. Damit beginnen wir.', 25549),
(117968, 'deDE', '', 'Mit ''Wasserelementar beschwören'' beschwört Ihr Euren Diener.', 25549),
(117967, 'deDE', '', 'Euer grundlegender, verlässlichster Angriff ist ''Frostblitz''.', 25549),
(117966, 'deDE', '', 'Dieser Distanzangriff fügt Gegnern Schaden zu, verlangsamt sie und kann andere Angriffe verstärken.', 25549),
(117965, 'deDE', '', 'Setzt ''Frostblitz'' gegen die Zielattrappe ein.', 25549),
(117964, 'deDE', '', 'Jetzt sehen wir uns ''Eislanze'' an: Dieser Zauber ähnelt ''Frostblitz'', wird jedoch spontan gewirkt und verursacht weniger Schaden.', 25549),
(117963, 'deDE', '', 'Die wahre Macht von ''Eislanze'' liegt im Einsatz gegen gefrorene Ziele, was den Schaden stark erhöht.', 25549),
(117962, 'deDE', '', 'Setzt ''Eislanze'' gegen die gefrorene Zielattrappe ein.', 25549),
(117961, 'deDE', '', 'Es gibt noch einen Weg, um die Macht von ''Eislanze'' zu maximieren.', 25549),
(117960, 'deDE', '', '''Frostblitz'' löst manchmal den Effekt ''Eisige Finger'' aus, der ''Eislanze'' einen riesigen Schadensbonus gewährt. Probiert es.', 25549),
(117959, 'deDE', '', 'Setzt ''Frostblitz'' gegen die Zielattrappe ein, bis Ihr ''Eisige Finger'' habt. Wirkt dann ''Eislanze''.', 25549),
(117958, 'deDE', '', 'Setzt ''Frostblitz'' gegen die Zielattrappe ein, bis Ihr ''Eisige Finger'' habt. Wirkt ''Eislanze'', wenn der Effekt aktiv ist.', 25549),
(117957, 'deDE', '', 'Ein weiterer wirksamer Zauber ist ''Gefrorene Kugel''. Wirkt ihn, wann immer er bereit ist, denn er kann ''Eislanze'' verstärken.', 25549),
(117956, 'deDE', '', 'Passt jedoch auf, sie trifft alle Gegner auf ihrem Weg, nicht nur Euer Ziel.', 25549),
(117955, 'deDE', '', 'Setzt ''Gefrorene Kugel'' gegen die Zielattrappe ein.', 25549),
(117954, 'deDE', '', 'Trotz all Eurer Bemühungen werden Euch Gegner gelegentlich erreichen.', 25549),
(117953, 'deDE', '', 'In solchen Fällen wird zusätzlicher Schutz benötigt. ''Eisbarriere'' erschafft einen Schild aus Eis, der Angriffe absorbiert.', 25549),
(117952, 'deDE', '', 'Setzt ''Eisbarriere'' ein, um Schaden zu verringern.', 25549),
(117951, 'deDE', '', 'Ihr seid in einer verzwickten Lage? ''Unsichtbarkeit'' bietet Euch einen großartigen Ausweg.', 25549),
(117950, 'deDE', '', 'Dadurch können Gegner Euch nicht anvisieren und Ihr könnt entkommen. Doch passt auf! Sie hält nicht lange an!', 25549),
(117949, 'deDE', '', 'Entkommt dem Kampf durch ''Unsichtbarkeit''.', 25549),
(117948, 'deDE', '', 'Zeigt mir die rohe Macht und Überlegenheit Eurer Kräfte!', 25549),
(117947, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als $gFrostmagier:Frostmagier; kämpfen.', 25549),
(117946, 'deDE', '', 'Wirkt ''Blizzard''!', 25549),
(117945, 'deDE', '', 'Wirkt ''Frostnova''!', 25549),
(117944, 'deDE', '', 'Ihr müsst Euren Gegner festfrieren, ehe er Euch erreicht.', 25549),
(117943, 'deDE', '', 'Wirkt ''Frostnova''!', 25549),
(117942, 'deDE', '', 'Wirkt ''Frostblitz''!', 25549),
(117941, 'deDE', '', '''Gefrorene Kugel'' ist bereit! Jetzt einsetzen!', 25549),
(117940, 'deDE', '', 'Wirkt ''Gefrorene Kugel''!', 25549),
(117939, 'deDE', '', 'Wirkt ''Eisbarriere''!', 25549),
(117938, 'deDE', '', '''Eisige Finger'' wurde ausgelöst! Wirkt jetzt ''Eislanze''!', 25549),
(117937, 'deDE', '', 'Wirkt ''Eislanze''!', 25549),
(117936, 'deDE', '', 'Euer Ziel ist eingefroren! Wirkt ''Eislanze''!', 25549),
(117935, 'deDE', '', 'Wirkt ''Eislanze'' erst, wenn Ihr ''Eisige Finger'' habt oder Euer Ziel eingefroren ist.', 25549),
(117934, 'deDE', '', 'Setzt ''Unsichtbarkeit'' ein!', 25549),
(117933, 'deDE', '', 'Euer Wasserelementar ist tot. Ruft ihn mit ''Wasserelementar beschwören'' zurück!', 25549),
(117932, 'deDE', '', 'Das Schlachtfeld ist gefährlich. Mobilität kann Euch das Leben retten.', 25549),
(117931, 'deDE', '', 'Einfach zu laufen ist so gewöhnlich! Glücklicherweise habt Ihr einen Zauber, der einem Meister der Magie würdig ist.', 25549),
(117930, 'deDE', '', '''Blinzeln'' teleportiert Euch ein Stück, um Gefahren zu umgehen oder Gegnern näherzukommen.', 25549),
(117929, 'deDE', '', 'Übt ''Blinzeln''.', 25549),
(117928, 'deDE', '', 'Was wäre, wenn Ihr Gegner festfrieren könntet, damit sie Euch nicht erreichen können?', 25549),
(117927, 'deDE', '', '''Frostnova'' lässt nahe Gegner am Boden festfrieren. So könnt Ihr Abstand gewinnen und sie aus der Ferne ausschalten. Lasst uns vorerst üben, sie festzufrieren.', 25549),
(117926, 'deDE', '', 'Friert meinen Krieger mit ''Frostnova'' ein.', 25549),
(117925, 'deDE', '', 'Merkt Euch, dass ''Eislanze'' gefrorenen Zielen mehr Schaden zufügt. Eine gute Taktik ist die Verbindung von ''Frostnova'' und ''Eislanze''.', 25549),
(117924, 'deDE', '', 'Ihr seid meisterhaft darin, vielen Gegnern gleichzeitig zu schaden.', 25549),
(117923, 'deDE', '', 'Mit ''Blizzard'' lasst Ihr eisige Splitter auf den Zielort prasseln. Toller Name, oder?', 25549),
(117922, 'deDE', '', 'Wirkt ''Blizzard'', um diese Gegner auszuschalten.', 25549),
(117876, 'deDE', '', 'Mal schauen, welche Naturgewalten Ihr noch beherrscht.', 25549),
(117875, 'deDE', '', 'Mit ''Alphatier'' ruft Ihr ein Tier herbei, das dem Kampf beitritt und kurze Zeit Euer Ziel angreift.', 25549),
(117874, 'deDE', '', 'Setzt ''Alphatier'' gegen die Zielattrappe ein.', 25549),
(117873, 'deDE', '', 'Ihr seid eindeutig kampfbereit. ''Kobraschuss'' ist Euer primärer Distanzangriff, mit dem Ihr Gegnern zusetzt, während sie mit Eurem Begleiter beschäftigt sind.', 25549),
(117872, 'deDE', '', 'Setzt ''Kobraschuss'' gegen die Zielattrappe ein.', 25549),
(117871, 'deDE', '', 'Setzt ''Zorn des Wildtiers'' gegen die Zielattrappe ein.', 25549),
(117870, 'deDE', '', 'Im Kampf versetzt ''Zorn des Wildtiers'' Euch und Euren Begleiter in einen Blutrausch, der Euren Schaden für kurze Zeit erhöht.', 25549),
(117869, 'deDE', '', 'Während ''Zorn des Wildtiers'' aktiv ist, verringert ''Alphatier'' die Zeit, bis die Fähigkeit wieder eingesetzt werden kann.', 25549),
(117868, 'deDE', '', 'Beweist, dass Ihr das nötige Können und die Schläue besitzt, jede Beute zu jagen!', 25549),
(117867, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als $gTierherrschaftsjäger:Tierherrschaftsjägerin; kämpfen.', 25549),
(117866, 'deDE', '', '''Zorn des Wildtiers'' ist bereit! Jetzt einsetzen!', 25549),
(117865, 'deDE', '', 'Setzt ''Zorn des Wildtiers'' ein!', 25549),
(117864, 'deDE', '', 'Ruft Euren Begleiter!', 25549),
(117863, 'deDE', '', 'Setzt ''Kobraschuss'' ein!', 25549),
(117862, 'deDE', '', '''Alphatier'' ist bereit! Jetzt einsetzen!', 25549),
(117861, 'deDE', '', 'Setzt ''Alphatier'' ein!', 25549),
(117860, 'deDE', '', '''Tötungsbefehl'' ist bereit! Jetzt einsetzen!', 25549),
(117859, 'deDE', '', 'Setzt ''Tötungsbefehl'' ein!', 25549),
(117858, 'deDE', '', 'Euer Begleiter ist verletzt! Setzt ''Tier heilen'' ein!', 25549),
(117857, 'deDE', '', 'Setzt ''Mehrfachschuss'' ein!', 25549),
(117856, 'deDE', '', 'Tierherrschaftsjäger haben eine enge Verbindung mit ihren Begleitern. Sie rufen und stärken sie im Kampf, während sie selbst Gegner mit Distanzangriffen bekämpfen.', 25549),
(117855, 'deDE', '', 'Mit Eurem treuen Begleiter seid Ihr Meister Eurer Umgebung. Mit ''Begleiter rufen'' ruft Ihr Euer Tier zu Euch.', 25549),
(117854, 'deDE', '', 'Setzt ''Begleiter rufen'' ein und bringt Euren Begleiter in den Kampf.', 25549),
(117853, 'deDE', '', 'Wenn Ihr Euren Begleiter Gegner angreifen und ablenken lasst, bleibt Euch mehr Zeit für Distanzangriffe.', 25549),
(117852, 'deDE', '', 'Keine Sorge, Euer Begleiter ist widerstandsfähig! ''Tötungsbefehl'' ist ein starker Angriff Eures Begleiters - gut geeignet, um einen Kampf zu beginnen.', 25549),
(117851, 'deDE', '', 'Setzt ''Tötungsbefehl'' mehrmals gegen die Zielattrappe ein.', 25549),
(117850, 'deDE', '', 'Euer Begleiter ist verwundet! Glücklicherweise könnt Ihr Eurem Gefährten helfen.', 25549),
(117849, 'deDE', '', 'Mit ''Tier heilen'' könnt Ihr die Wunden Eures Begleiters versorgen.', 25549),
(117848, 'deDE', '', 'Setzt ''Tier heilen'' ein, um Euren Begleiter zu heilen.', 25549),
(117847, 'deDE', '', 'Euer Begleiter ist gestorben! Wenn das passiert, wird die Fähigkeit ''Tier heilen'' zu ''Tier wiederbeleben'' und kann Euren treuen Begleiter zurückbringen.', 25549),
(117846, 'deDE', '', 'Manchmal seid Ihr in der Unterzahl. In solchen Fällen könnt Ihr eine ganze Gruppe Gegner gleichzeitig aufs Korn nehmen!', 25549),
(117845, 'deDE', '', '''Mehrfachschuss'' feuert eine Salve ab, die auch Gegner in der Nähe Eures Ziels trifft.', 25549),
(117844, 'deDE', '', 'Bei diesem Angriff greift auch Euer Begleiter mehrere Ziele an.', 25549),
(117843, 'deDE', '', 'Mit ''Mehrfachschuss'' trefft Ihr alle Gegner.', 25549),
(117842, 'deDE', '', 'Selbst die größten Abenteurer können sich mit ihrer Beute übernehmen.', 25549),
(117841, 'deDE', '', 'Kurz vor einer Niederlage könnt Ihr ''Totstellen'' einsetzen, um Gegnern vorzugaukeln, Ihr wärt keine Bedrohung mehr.', 25549),
(117840, 'deDE', '', 'Setzt ''Totstellen'' ein, sodass mein Krieger fälschlicherweise von Euch ablässt.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(117775, 'deDE', '', 'Als unheiliger Todesritter beherrscht Ihr die Mächte von Tod und Krankheit.', 25549),
(117774, 'deDE', '', 'Krankheiten schwächen Eure Gegner und mit Nahkampfangriffen streckt Ihr sie nieder.', 25549),
(117773, 'deDE', '', 'Doch Euer stärkster Verbündeter ist der Tod selbst. Mit ''Totenerweckung'' verwandelt Ihr eine Leiche in Euren Ghuldiener.', 25549),
(117772, 'deDE', '', 'Ihr solltet immer einen Diener dabei haben.', 25549),
(117771, 'deDE', '', 'Beschwört Euren Diener mit ''Totenerweckung''.', 25549),
(117770, 'deDE', '', 'Zu Beginn des Kampfes solltet Ihr den Feind am besten zunächst aus der Ferne mit Krankheiten infizieren.', 25549),
(117769, 'deDE', '', '''Ausbruch'' verursacht regelmäßigen Schaden und verbreitet eine virulente Seuche unter Gegnern in der Nähe.', 25549),
(117768, 'deDE', '%s ist gefallen! Eure Verbündeten ziehen sich zurück.', '%s ist gefallen! Eure Verbündeten ziehen sich zurück.', 25549),
(117767, 'deDE', '', 'Setzt ''Ausbruch'' gegen die Zielattrappe ein.', 25549),
(117766, 'deDE', '', 'Nun da Euer Gegner an allerlei Krankheiten leidet, ist es Zeit, in den Nahkampf überzugehen!', 25549),
(117765, 'deDE', '', '''Schwärender Stoß'' fügt dem Ziel Schaden und schwärende Wunden zu.', 25549),
(117764, 'deDE', '', 'Setzt ''Schwärender Stoß'' gegen die Zielattrappe ein.', 25549),
(117763, 'deDE', '', 'Ah, das sieht gewöhnungsbedürftig aus! Nachdem das Ziel mit ''Schwärender Stoß'' infiziert wurde, könnt Ihr die Wunden mit ''Geißelstoß'' aufbrechen lassen!', 25549),
(117762, 'deDE', '', 'Gegen ''Schwärender Stoß'' gefolgt von ''Geißelstoß'' können nur wenige Gegner bestehen.', 25549),
(117761, 'deDE', '', 'Setzt ''Geißelstoß'' gegen die Zielattrappe ein, sobald sie durch ''Schwärender Stoß'' infiziert wurde.', 25549),
(117760, 'deDE', '', '''Geißelstoß'' wirkt am besten auf Ziele, die von schwärenden Wunden betroffen sind.', 25549),
(117759, 'deDE', '', 'Eure Angriffe erzeugen Runenmacht. Damit könnt Ihr den Zauber ''Todesmantel'' verwenden, der unheilige Energie auf Euer Ziel feuert und die Energie Eures Ghuls regeneriert.', 25549),
(117758, 'deDE', '', 'Setzt ''Todesmantel'' gegen die Zielattrappe ein.', 25549),
(117757, 'deDE', '', 'Eure Angriffe lassen Euch gelegentlich ''Todesmantel'' ohne Runenmachtkosten einsetzen. Macht Euch das so oft wie möglich zunutze!', 25549),
(117756, 'deDE', 'Euer untoter Diener ist im Kampf sehr nützlich. Mit ''Dunkle Transformation'' könnt Ihr Euren Ghul vorübergehend in ein stärkeres, bulliges Monster mit weiteren Fähigkeiten verwandeln. Probiert es!', '', 25549),
(117755, 'deDE', 'Verstärkt Euren Ghul mit ''Dunkle Transformation''.', '', 25549),
(117754, 'deDE', 'Als Todesritter kontrolliert Ihr das Schlachtfeld!', '', 25549),
(117753, 'deDE', 'Wirkt ''Tod und Verfall'', um den Boden unter Euch zu verderben. Alle Gegner in dem Bereich erleiden Schaden und einige Eurer Angriffe treffen mehrere Ziele.', '', 25549),
(117752, 'deDE', 'Setzt ''Tod und Verfall'' ein, um diese Dienergruppe auszuschalten.', '', 25549),
(117751, 'deDE', '', 'Wenn Ihr im Kampf viel Schaden erleidet, kann ''Todesstoß'' die Lage ausgleichen.', 25549),
(117750, 'deDE', '', 'Die dunkle Macht schadet Gegnern und heilt einen Teil Eurer Gesundheit.', 25549),
(117749, 'deDE', '', 'Setzt ''Todesstoß'' ein, um etwas Gesundheit wiederherzustellen.', 25549),
(117748, 'deDE', '', 'Zeigt, dass Ihr die Macht der Dunkelheit gemeistert habt!', 25549),
(117747, 'deDE', '', 'Gut gemacht, $p! Ihr könnt jetzt als unheiliger Todesritter kämpfen.', 25549),
(117746, 'deDE', '', 'Setzt Eure ''Armee der Toten'' ein!', 25549),
(117745, 'deDE', 'Ein guter Zeitpunkt, um ''Dunkle Transformation'' einzusetzen!', '', 25549),
(117744, 'deDE', 'Euch bedrohen mehrere Gegner. Benutzt ''Tod und Verfall''!', '', 25549),
(117743, 'deDE', '', '''Todesmantel'' ist kostenlos! Jetzt einsetzen!', 25549),
(117742, 'deDE', '', 'Setzt ''Todesmantel'' ein!', 25549),
(117741, 'deDE', '', 'Setzt ''Todesstoß'' ein!', 25549),
(117740, 'deDE', '', 'Euer Ziel hat keine schwärende Wunde. Setzt jetzt ''Schwärender Stoß'' ein!', 25549),
(117739, 'deDE', '', 'Setzt ''Schwärender Stoß'' ein!', 25549),
(117738, 'deDE', '', 'Der ''Ausbruch'' Eures Ziels ist abgelaufen, wirkt ihn jetzt!', 25549),
(117737, 'deDE', '', 'Wirkt ''Ausbruch''!', 25549),
(117736, 'deDE', '', 'Die virulente Seuche Eures Ziels ist abgelaufen. Wirkt jetzt ''Ausbruch''!', 25549),
(117735, 'deDE', '', 'Euer Diener ist tot. Beschwört mit ''Totenerweckung'' einen neuen.', 25549),
(117734, 'deDE', '', 'Setzt ''Geißelstoß'' ein!', 25549),
(117733, 'deDE', '', '''Geißelstoß'' nach ''Schwärender Stoß'' – eine wirksame Kombination!', 25549),
(117732, 'deDE', '', 'Euer Ziel hat die Höchstmenge schwärender Wunden. Setzt ''Geißelstoß'' ein!', 25549),
(117731, 'deDE', '', 'Einige Gegner werden Euch lieber auf Abstand halten.', 25549),
(117730, 'deDE', '', '''Todesgriff'' packt ein entferntes Ziel und zieht es zu Euch heran. Kein Gegner kann Eurem eisigen Griff entkommen!', 25549),
(117729, 'deDE', '', 'Setzt ''Todesgriff'' ein und zieht meinen Krieger zu Euch.', 25549),
(117728, 'deDE', '', '''Todesgriff'' kann aus einiger Entfernung eingesetzt werden. Versucht, ihn weiter vom Ziel entfernt einzusetzen.', 25549),
(117727, 'deDE', '', 'Als Bezwinger der Macht des Todes müsst Ihr nur selten in der Unterzahl kämpfen.', 25549),
(117726, 'deDE', '', '''Armee der Toten'' erweckt einen Schwarm Ghule, die alles in Eurer Umgebung angreifen.', 25549),
(117725, 'deDE', '', 'Diese mächtige Fähigkeit ist nicht oft einsetzbar, hebt sie für Notfälle auf.', 25549),
(117724, 'deDE', '', 'Ruft Eure Diener jetzt mit ''Armee der Toten''.', 25549),
(117723, 'deDE', '', 'Beschützt sie, während ich ihre Wunden heile!', 25549),
(117722, 'deDE', 'Mit ''Heldenhafter Sprung'' erreicht Ihr schnell Eure Ziele auf dem Schlachtfeld.', '', 25549),
(117721, 'deDE', 'Mit ''Wirbelwind'' könnt Ihr die Waffe in weitem Bogen schwingen, um eine blutige Schneise um Euch zu schlagen.', '', 25549),
(117720, 'deDE', 'Mit ''Spalten'' könnt Ihr mehrere Gegner vor Euch angreifen. Für jeden Treffer verursacht Euer nächster ''Wirbelwind'' mehr Schaden!', '', 25549),
(117719, 'deDE', '''Siegesrausch'' ist zeitlich begrenzt und heilt Euch, wenn Ihr damit einen neuen Gegner angreift.', '', 25549),
(117718, 'deDE', '''Tödlicher Stoß'' ist so ein Angriff. Verwendet ihn möglichst oft.', '', 25549),
(117717, 'deDE', 'Ihr könnt einen Gegner außer Reichweite nicht besiegen. Aber zum Glück gibt es dafür eine passende Fähigkeit.', '', 25549),
(117716, 'deDE', '', 'Mathias Shaw erkundete mit unserem SI:7-Eliteteam die Insel. Wir warteten gerade am Abzugspunkt.', 25549),
(117715, 'deDE', 'Mit dem Seelenstein könnt Ihr Eure Seele für später aufbewahren. Keine Sorge, Ihr habt ja ohnehin keine Verwendung mehr für sie! Mit gesicherter Seele könnt Ihr von den Toten auferstehen.', '', 25549),
(117714, 'deDE', 'Allerdings solltet Ihr Euch diesen Dämon für den Notfall aufsparen.', '', 25549),
(117713, 'deDE', 'Um einen Gegner kurzzeitig vom Kämpfen abzuhalten, versetzt ihn in Angst und Schrecken.', '', 25549),
(117712, 'deDE', 'Mit ''Aderlass'' zapft Ihr Eure eigene Lebenskraft an, um Euer Mana aufzufüllen. Zum Ausgleich könnt Ihr den Gegner anzapfen, um Euch zu heilen.', '', 25549),
(117711, 'deDE', 'Mit Eurer dunklen Magie könnt Ihr dämonische Diener beschwören, die Euch gehorchen.', '', 25549),
(117710, 'deDE', '''Instabiles Gebrechen'' verursacht wie ''Agonie'' und ''Verderbnis'' regelmäßigen Schaden, verwendet aber einen Seelensplitter für mehr Schaden.', '', 25549),
(117709, 'deDE', 'Der beliebte Angriff ''Seelendieb'' fügt dem Gegner Schaden zu und heilt Euch zugleich.', '', 25549),
(117708, 'deDE', '''Verderbnis'' fügt dem Ziel während seiner Effektdauer Schattenschaden zu.', '', 25549),
(117707, 'deDE', 'Durch den zunehmend größeren regelmäßigen Schaden ist ''Agonie'' eine gute Kampferöffnung.', '', 25549),
(117706, 'deDE', 'Für Euch ist dies kein Problem. Das Licht gibt Euch die Macht, Eure Gesundheit oder die Eurer Verbündeten wiederherzustellen.', '', 25549),
(117705, 'deDE', 'Zum Glück könnt Ihr Euch auch verteidigen. ''Psychischer Schrei'' verängstigt nahe Gegner und schlägt sie so in die Flucht.', '', 25549),
(117704, 'deDE', 'Denkt daran, Euren Schild in Kämpfen aufrechtzuerhalten.', '', 25549),
(117703, 'deDE', 'Eine Eurer nützlichsten Verteidigungen ist ''Machtwort: Schild'', das sämtlichen Schaden absorbiert.', '', 25549),
(117702, 'deDE', 'Euer meistgenutzter Schadenszauber, optimal eingesetzt, wenn ''Sühne'' nicht bereit ist.', '', 25549),
(117701, 'deDE', '''Sühne'' ist ein wirksamer Zauber, der Euren Gegnern schadet. Setzt ihn so oft wie möglich ein.', '', 25549),
(117700, 'deDE', '''Schattenwort: Schmerz'' schlägt Gegner mit Schattenenergie und verursacht regelmäßigen Schaden.', '', 25549),
(117699, 'deDE', '', 'Das... ist unmöglich...', 25549),
(117698, 'deDE', '', 'Ihr könnt nicht... trotzen...', 25549),
(117697, 'deDE', '', 'Wir setzen die Welt in Flammen!', 25549),
(117696, 'deDE', '', 'Der Untergang naht!', 25549),
(117695, 'deDE', '', 'Wo einer fällt... erheben sich zwei.', 25549),
(117694, 'deDE', '', 'Wir sind... endlos...', 25549),
(117693, 'deDE', '', 'Ihr könnt uns nicht alle stoppen...', 25549),
(117692, 'deDE', '', 'Endlich, passende Beute...', 25549),
(117691, 'deDE', '', 'Ich werde Gul''dan Euren Kopf persönlich überbringen.', 25549),
(117690, 'deDE', '', 'Spielt nicht mit uns!', 25549),
(117689, 'deDE', '', 'Die Legion wird alles erobern!', 25549),
(117688, 'deDE', '', 'Endlich ein bisschen Spaß.', 25549),
(117687, 'deDE', '', 'Eure Seele wird uns ewig dienen!', 25549),
(117686, 'deDE', '', 'Vernichtet sie!', 25549),
(117685, 'deDE', 'Ihr könnt Euch und Eure Verbündeten durch Euren Glauben heilen. ''Lichtblitz'' ist der Eckpfeiler Eurer Heilung.', '', 25549),
(117684, 'deDE', '''Gottesschild'' verhindert, dass Euch Angriffe Schaden zufügen.', '', 25549),
(117683, 'deDE', 'Entfesselt diese göttliche Magie mit dem mächtigen Nahkampfangriff ''Urteil des Templers'', der Eure Waffe mit der Macht des Lichts erfüllt.', '', 25549),
(117682, 'deDE', 'Wenn der Gegner in Angriffsnähe ist, setzt ''Kreuzfahrerstoß'' ein.', '', 25549),
(117681, 'deDE', 'Schlagt ankommende Gegner auf mittlerer Reichweite mit ''Klinge der Gerechtigkeit''.', '', 25549),
(117680, 'deDE', 'Die Hingabe zum Licht lässt Euch Gegner ein mächtiges ''Richturteil'' entgegenwerfen.', '', 25549),
(117679, 'deDE', 'Ihr greift mit Fernkampfzaubern und Nahkampf an, die Heilige Kraft erzeugen und entfesseln.', '', 25549),
(117678, 'deDE', '', 'Hmm. Ich finde Euch bald...', 25549),
(117677, 'deDE', '', 'Nun gut. Genießt Eure Freiheit... vorerst.', 25549),
(117676, 'deDE', '', 'Hmm. Meine Beute kann warten...', 25549),
(117675, 'deDE', '', 'Was haben wir hier? Ist da jemand?', 25549),
(117674, 'deDE', '', 'Ich spüre einen Spion unter uns.', 25549),
(117673, 'deDE', '', 'Lauft nur. Ihr sterbt nur erschöpft.', 25549),
(117672, 'deDE', '', '<Seufzt.> Also gut. Ich bin Valtrois.', 25549),
(117671, 'deDE', 'Wenn Ihr Schwierigkeiten im Kampf habt, könnt Ihr zwei wilde Wolfsgeister an Eure Seite beschwören.', '', 25549),
(117670, 'deDE', '''Tobende Blitze'' fügt allen Zielen vor Euch Schaden zu. Mehrere Ziele zu treffen verstärkt Eure Waffen und verursacht mehr Schaden!', '', 25549),
(117669, 'deDE', 'Setzt ''Sturmschlag'' immer nach ''Sturmbringer'' ein.', '', 25549),
(117668, 'deDE', '''Lavapeitsche'' braucht Mahlstrom, um Eure Schildhandwaffe mit Lava zu laden und mächtige Schläge auszuführen.', '', 25549),
(117667, 'deDE', '''Felsbeißer'' ermächtigt Eure Waffen, um mit Erdmacht Schaden zuzufügen.', '', 25549),
(117666, 'deDE', 'Als ersten Angriff probieren wir ''Flammenzunge'' aus, der Eure Waffen mit Flammen umhüllt und Gegner verbrennt.', '', 25549),
(117665, 'deDE', 'Die Elemente können zerstören, doch ebenso können sie wiederherstellen.', '', 25549),
(117664, 'deDE', 'Wenn Ihr Gegner mit ''Kettenblitzschlag'' trefft, springt der Blitz über und fügt allen Gegnern in der Nähe Schaden zu.', '', 25549),
(117663, 'deDE', 'Als Frosch wird Euer Ziel nicht angreifen, doch der Effekt ist vorübergehend. Wird der Frosch angegriffen, verwandelt er sich zurück.', '', 25549),
(117662, 'deDE', 'Setzt ''Blitzschlag'' ein, wenn keine andere Fähigkeit bereit ist.', '', 25549),
(117661, 'deDE', 'Ist ''Flammenschock'' auf dem Ziel aktiv, wird der Schaden von ''Lavaeruption'' erhöht.', '', 25549),
(117660, 'deDE', '''Flammenschock'' setzt Gegner in Flammen und verbrennt sie, während Ihr andere Zauber wirkt.', '', 25549),
(117659, 'deDE', 'Manchmal ist ein Rückzug notwendig, damit Ihr später weiterkämpfen könnt.', '', 25549),
(117658, 'deDE', '''Dolchfächer'' entfesselt Schaden, der alle Gegner um Euch herum trifft. Außerdem erhaltet Ihr einen Combopunkt pro getroffenem Gegner.', '', 25549),
(117657, 'deDE', 'Bei ''Schattenschritt'' bleibt Ihr in Verstohlenheit und seid zum Angriff bereit.', '', 25549),
(117656, 'deDE', '''Blutrote Phiole'' ist ein Gebräu, das einen Teil Eurer Gesundheit wiederherstellt.', '', 25549),
(117655, 'deDE', 'Wenn Euer Ziel von ''Blutung'' betroffen ist, könnt Ihr für 5 Combopunkte ''Vergiften'' einsetzen, viel Schaden verursachen und den Effekt Eurer Gifte maximieren.', '', 25549),
(117654, 'deDE', 'Wenn Ihr mit 5 Combopunkten ''Blutung'' einsetzt, entsteht eine stark blutende Wunde, die regelmäßig Schaden verursacht.', '', 25549),
(117653, 'deDE', 'Am besten beginnt Ihr den Kampf mit ''Erdrosseln'', einer schwächenden Blutung, die Eurem Gegner regelmäßigen Schaden zufügt.', '', 25549),
(117652, 'deDE', 'Darion Mograine! Was hat das zu bedeuten?!', '', 25549),
(117651, 'deDE', 'Erhebt Eure Klinge vor der Schmiede und werdet Zeuge der Macht, die sie ihr verleiht!', '', 25549),
(117650, 'deDE', 'Bevor wir anfangen, müssen wir Eure Waffe mit Gift bestreichen.', '', 25549),
(117649, 'deDE', 'Verwendet ihn so oft wie möglich.', '', 25549),
(117648, 'deDE', 'Der Schlüssel zur Mobilität der Mönche ist ''Rollen''. Damit könnt Ihr schnell ordentliche Strecken in Bewegungsrichtung zurücklegen.', '', 25549),
(117647, 'deDE', 'Setzt diesen Trick ein, wann immer Ihr auf jemanden trefft, den Ihr nicht mögt. Aber vielleicht solltet Ihr Euch das für die wirklich zähen Gegner aufheben!', '', 25549),
(117646, 'deDE', 'Wenn Ihr Euch drei oder sogar noch mehr Gegnern stellen müsst, nutzt Eure Geisteskraft, um Euch selbst zu duplizieren. So werdet Ihr Euer eigener Verbündeter! Eure verbündeten Doppelgänger greifen die Feinde automatisch an.', '', 25549),
(117645, 'deDE', 'Wollt Ihr einen Gegner aus dem Gefecht nehmen? ''Paralysieren'' macht ihn kurze Zeit bewusstlos. Durch Schaden kommt er aber wieder zu sich.', '', 25549),
(117644, 'deDE', 'Setzt ''Fliegender Schlangentritt'' ein, um zu einem Gegner zu fliegen. Wenn Ihr ihn in der Luft erneut einsetzt, endet der Flug und Ihr schadet Gegnern in Eurer Nähe.', '', 25549),
(117643, 'deDE', 'Damit trefft Ihr zusätzliche Ziele neben Eurem Ziel. Setzt ''Furorfäuste'' so oft wie möglich ein, besonders bei mehreren Gegnern.', '', 25549),
(117642, 'deDE', 'Ihr beginnt Euch einen Namen zu machen. Genau wie Ihr gewinnt das furchteinflößende Artefakt, das Ihr führt, ebenfalls an Macht.', '', 25549),
(117641, 'deDE', 'Er trifft deutlich härter als ''Tigerklaue'', also verwendet zusätzliches Chi für ''Blackout-Tritt''.', '', 25549),
(117640, 'deDE', 'Setzt Euren Primärangriff ''Tigerklaue'' ein, um Schaden zu verursachen und Chi zu erzeugen.', '', 25549),
(117639, 'deDE', 'Dabei erzeugt Ihr Chi, eine Ressource, durch die Ihr mächtige Angriffe ausführen könnt.', '', 25549),
(117638, 'deDE', 'Ihr habt gut gekämpft. Die Zweifel an der Entscheidung meines Vaters waren unbegründet. Ulduar wird Euch unterstützen, wenn Ihr gewillt seid, uns dabei zu helfen, Hodir zu finden.', '', 25549),
(117637, 'deDE', 'Sie sind fort... das Portal ist geschlossen!', '', 25549),
(117636, 'deDE', '', 'Tretet vor den Altar der Ewigen Jagd. Lasst ihn Eure Waffe mit Macht erfüllen, sodass sie noch stärker wird als zuvor!', 25549),
(117635, 'deDE', '', 'Ah, das Symbol kenne ich. Dann rekrutiert Thalyssra jetzt also Fremde... Sind wir schon so verzweifelt?', 25549),
(117634, 'deDE', 'Bei diesem Angriff greift auch Euer Begleiter mehrere Ziele an.', '', 25549),
(117633, 'deDE', 'Hodir war schon immer impulsiver, als ihm gut getan hat.\n\nAber Euch hat er richtig eingeschätzt. Ich hätte nie gedacht, dass sich ein Kind der Sterblichen als würdig erweisen könnte, Odyns Segen zu erhalten. Ihr seid ein Rätsel, $n.\n\nSobald ihr bereit seid, werde ich Euch von hier fortteleportieren.', '', 25549),
(117632, 'deDE', 'Kurz vor einer Niederlage könnt Ihr ''Totstellen'' einsetzen, um Gegnern vorzugaukeln, Ihr wärt keine Bedrohung mehr.', '', 25549),
(117631, 'deDE', '''Mehrfachschuss'' feuert eine Salve ab, die auch Gegner in der Nähe Eures Ziels trifft.', '', 25549),
(117630, 'deDE', 'Mit ''Tier heilen'' könnt Ihr die Wunden Eures Begleiters versorgen.', '', 25549),
(117629, 'deDE', '', 'Und jetzt werde ich Euch töten. Letzte Worte?', 25549),
(117628, 'deDE', 'Keine Sorge, Euer Begleiter ist widerstandsfähig! ''Tötungsbefehl'' ist ein starker Angriff Eures Begleiters - gut geeignet, um einen Kampf zu beginnen.', '', 25549),
(117627, 'deDE', '', 'Geschafft. Endlich offen.', 25549),
(117626, 'deDE', 'Mit Eurem treuen Begleiter seid Ihr Meister Eurer Umgebung. Mit ''Begleiter rufen'' ruft Ihr Euer Tier zu Euch.', '', 25549),
(117625, 'deDE', 'Während ''Zorn des Wildtiers'' aktiv ist, verringert ''Alphatier'' die Zeit, bis die Fähigkeit wieder eingesetzt werden kann.', '', 25549),
(117624, 'deDE', '', 'Ihr da! Seid so gut und stellt Euch auf den anderen Schalter, ja?', 25549),
(117623, 'deDE', 'Mit ''Alphatier'' ruft Ihr ein Tier herbei, das dem Kampf beitritt und kurze Zeit Euer Ziel angreift.', '', 25549),
(117622, 'deDE', 'Wenn Ihr Schaden erlitten habt, heilt Euch mit ''Nachwachsen''.', '', 25549),
(117621, 'deDE', '''Spurt'' macht Euch für kurze Zeit deutlich schneller. Die Fähigkeit ist nicht oft verfügbar, also setzt sie nur ein, wenn es wichtig ist.', '', 25549),
(117620, 'deDE', 'Zeit zu gehen! Hier!', '', 25549),
(117619, 'deDE', '''Hauen'' greift alle Gegner in der Nähe an und lässt sie für kurze Zeit bluten.', '', 25549),
(117618, 'deDE', 'Hodir war schon immer viel zu impulsiv und das zu seinem eigenen Schaden.\n\nAber in Euch hat er sich offenbar nicht getäuscht. Ich hätte nie gedacht, ein Kind der Sterblichen würde sich als würdig erweisen, Odyns Segen zu erhalten. Ihr seid ein Rätsel, $n.', '', 25549),
(117617, 'deDE', '''Prankenhieb'' verursacht in der Nähe Schaden, der durch Blutung noch erhöht wird. Setzt ''Hauen'' und ''Prankenhieb'' am besten zusammen ein.', '', 25549),
(117616, 'deDE', '''Überlebensinstinkte'' verringern für kurze Zeit Euren erlittenen Schaden. Haltet sie bereit für Notfälle!', '', 25549),
(117615, 'deDE', '''Wucherwurzeln'' lässt Wurzeln aus dem Boden hervorschnellen, die das Ziel für kurze Zeit festhalten.', '', 25549),
(117614, 'deDE', 'Wie ''Wilder Biss'' ist auch ''Zerfetzen'' ein Finishing-Move. Am besten mit 5 Combopunkten einsetzen.', '', 25549),
(117613, 'deDE', 'Alternativ zu ''Wilder Biss'' könnt Ihr ''Zerfetzen'' verwenden und regelmäßigen Blutungsschaden verursachen. Eine gute Gelegenheit, früh Combopunkte einzusetzen.', '', 25549),
(117612, 'deDE', '''Tigerfuror'' regeneriert etwas Energie und erhöht kurzfristig den verursachten Schaden.', '', 25549),
(117611, 'deDE', 'Narr! Euer Verrat verzögert nur das Unvermeidliche! Für Euch habe ich ein besonderes Gefängnis, sobald Euer Körper und alles, was Ihr kennt, zertrümmert ist.', '', 25549),
(117610, 'deDE', '''Schreddern'' fügt blutenden Zielen mehr Schaden zu. Diese Fähigkeiten lassen sich also gut kombinieren.', '', 25549),
(117609, 'deDE', '''Krallenhieb'' verursacht regelmäßigen Blutungsschaden.', '', 25549),
(117608, 'deDE', 'Setzt ihn am besten ein, wenn Ihr 5 Combopunkte habt.', '', 25549),
(117607, 'deDE', '''Wilder Biss'' ist ein Finishing-Move, der mit mehr Combopunkten auch mehr Schaden verursacht.', '', 25549),
(117606, 'deDE', 'Das mächtige ''Schreddern'' fügt blutenden Zielen noch mehr Schaden zu, also haltet ''Krallenhieb'' aktiv.', '', 25549),
(117605, 'deDE', 'Wenn sie geschwächt sind, geht Ihr ihnen mit einem mächtigen Finishing-Move an die Kehle.', '', 25549),
(117604, 'deDE', '''Wucherwurzeln'' lässt Wurzeln aus dem Boden hervorschnellen, die das Ziel für kurze Zeit festhalten.', '', 25549),
(117603, 'deDE', '''Lunarschlag'' fügt dem Ziel direkten Schaden zu, trifft aber auch andere Gegner in der Nähe.', '', 25549),
(117602, 'deDE', 'Euer Tod wird... ein Knaller.', '', 25549),
(117601, 'deDE', '', 'Drugon hätte auf diesem Gipfel versteckt bleiben sollen. Ich danke Euch, Champion, mein Volk ist dank Euch jetzt sicherer.', 25549),
(117600, 'deDE', '', 'Thalyssra finale lines.', 25549),
(117599, 'deDE', 'Oculeth finale lines.', '', 25549),
(117598, 'deDE', '', 'Drugon der Frostblütige ist ein uralter Feind meines Volks und wurde an den Schneeblinden Klippen gesichtet. Vernichtet diese Kreatur.', 25549),
(117597, 'deDE', 'Jetzt können wir das alte Netzwerk wiederherstellen. Wenn Ihr da draußen meine alten Signalgeber findet, dann aktiviert sie!', '', 25549),
(117596, 'deDE', '''Himmlische Ausrichtung'' ordnet die Sterne neu und erhöht kurzzeitig den Schaden durch Sonnen- und Mondzauber.', '', 25549),
(117595, 'deDE', '''Sternensog'' kostet Astrale Macht, die Ihr mit ''Solarzorn'' ansammeln könnt.', '', 25549),
(117594, 'deDE', '''Solarzorn'' ist eine Fernkampffähigkeit, die Schaden verursacht und Astrale Macht für mächtigere Angriffe erzeugt.', '', 25549),
(117593, 'deDE', 'Diese Angriffe verursachen regelmäßigen Schaden und sind gut geeignet für die Kampferöffnung.', '', 25549),
(117592, 'deDE', 'Ihr könnt in die Mondkingestalt wechseln und so Schaden und Verteidigung erhöhen.', '', 25549),
(117591, 'deDE', 'Es ist soweit! Beginnt mit der Beschwörung. Richtet das Szepter auf den Altar. Heute läuten wir das Ende dieser Welt ein!', '', 25549),
(117590, 'deDE', 'Euer Sieg überrascht mich nicht. Ich erwog, Allaris gegen Euch zu unterstützen, aber Euer Einfallsreichtum könnte noch nützlich sein. Betrachtet Euch als... befördert. Enttäuscht mich nicht!', '', 25549),
(117589, 'deDE', '', 'Oculeth, könnt Ihr die Teleporter in dieser Kammer reparieren?', 25549),
(117588, 'deDE', 'Getötet... von niederem Gesindel... das ist meiner unwürdig...', '', 25549),
(117586, 'deDE', 'Ihr seid noch nicht Zeuge meiner wahren Macht geworden!', '', 25549),
(117584, 'deDE', 'Bin schon dabei! Wenn die Untersuchung abgeschlossen ist, haben wir unsere erste Verbindung.', '', 25549),
(117583, 'deDE', 'Mit ''Blizzard'' lasst Ihr eisige Splitter auf den Zielort prasseln. Toller Name, oder?', '', 25549),
(117582, 'deDE', 'Dann sind wir nun wohl doch Feinde. Schade, Ihr hättet mir jederzeit dienen können!', '', 25549),
(117581, 'deDE', '''Frostnova'' lässt nahe Gegner am Boden festfrieren. So könnt Ihr Abstand gewinnen und sie aus der Ferne ausschalten. Lasst uns vorerst üben, sie festzufrieren.', '', 25549),
(117580, 'deDE', '''Blinzeln'' teleportiert Euch ein Stück, um Gefahren zu umgehen oder Gegnern näherzukommen.', '', 25549),
(117579, 'deDE', 'Einfach zu laufen ist so gewöhnlich! Glücklicherweise habt Ihr einen Zauber, der einem Meister der Magie würdig ist.', '', 25549),
(117578, 'deDE', 'Dadurch können Gegner Euch nicht anvisieren und Ihr könnt entkommen. Doch passt auf! Sie hält nicht lange an!', '', 25549),
(117577, 'deDE', 'In solchen Fällen wird zusätzlicher Schutz benötigt. ''Eisbarriere'' erschafft einen Schild aus Eis, der Angriffe absorbiert.', '', 25549),
(117576, 'deDE', 'Ahh, nur EINER von Euch ist für das Ritual vonnöten. "Diskutiert" die Angelegenheit, aber schnell...', '', 25549),
(117575, 'deDE', 'Passt jedoch auf, sie trifft alle Gegner auf ihrem Weg, nicht nur Euer Ziel.', '', 25549),
(117574, 'deDE', 'Hodir, wartet!', '', 25549),
(117573, 'deDE', '|TInterface\\Icons\\Ability_Hunter_RapidRegeneration:20|tSchnacki lässt ein |cFFFF0404|Hspell:219848|h[Pistolensperrfeuer]|h|r los! Springt auf den Boden!', '|TInterface\\Icons\\Ability_Hunter_RapidRegeneration:20|tSchnacki lässt ein |cFFFF0404|Hspell:219848|h[Pistolensperrfeuer]|h|r los! Springt auf den Boden!', 25549),
(117572, 'deDE', '''Frostblitz'' löst manchmal den Effekt ''Eisige Finger'' aus, der ''Eislanze'' einen riesigen Schadensbonus gewährt. Probiert es.', '', 25549),
(117571, 'deDE', 'Die wahre Macht von ''Eislanze'' liegt im Einsatz gegen gefrorene Ziele, was den Schaden stark erhöht.', '', 25549),
(117570, 'deDE', 'Dieser Distanzangriff fügt Gegnern Schaden zu, verlangsamt sie und kann andere Angriffe verstärken.', '', 25549),
(117569, 'deDE', 'Eure Kontrolle über das Eis erlaubt Euch, Wasserelementare als Diener zu rufen. Damit beginnen wir.', '', 25549),
(117568, 'deDE', 'Ähm... großer Meister? Wer von uns wird das Szepter führen?', '', 25549),
(117567, 'deDE', 'Ich werde durch das Portal Argus betreten und dort als Ankerpunkt fungieren. Ihr kanalisiert die Ritualenergie durch das Szepter und erweitert so den Riss, um unzählige weitere Portale zu öffnen.', '', 25549),
(117566, 'deDE', 'Mit dem Buch, dem Auge und dem Szepter werden wir das Portal verstärken und Tore zu unzähligen Dämonenwelten öffnen. Die geballte Macht der Legion wird auf diese erbärmliche Welt niedergehen!', '', 25549),
(117565, 'deDE', 'Mit der Beschaffung dieser Artefakte habt Ihr Euch wirklich bewiesen. Euer Platz in den Reihen des Schattenrats ist Euch gewiss.', '', 25549),
(117564, 'deDE', 'Ah, das Buch! Endlich... Überbracht von jemandem, dessen lästige Handschrift ich nur zu gut kenne! Wollt Ihr Euch nicht der Siegerseite anschließen, "Champion"?', '', 25549),
(117563, 'deDE', '|TInterface\\Icons\\ability_siege_engineer_overload:20|tRax'' Schredder gerät |cFFFF0404|Hspell:219614|h[außer Kontrolle]|h|r! Springt zum Zeppelin!', '|TInterface\\Icons\\ability_siege_engineer_overload:20|tRax'' Schredder gerät |cFFFF0404|Hspell:219614|h[außer Kontrolle]|h|r! Springt zum Zeppelin!', 25549),
(117562, 'deDE', '', 'Zuerst brauche ich Verbündete.', 25549),
(117561, 'deDE', '', 'Die perfekte Zuflucht und eine Art Zuhause, bis zur Rückkehr nach Suramar.', 25549),
(117560, 'deDE', 'Diese mächtige Fähigkeit ist nicht oft einsetzbar, hebt sie für Notfälle auf.', '', 25549),
(117559, 'deDE', '', '<seufzt> Die Fragen werden immer mehr!', 25549),
(117558, 'deDE', '', 'Und wie lange mussten ihre Hüter sie bewachen...?', 25549),
(117557, 'deDE', '', 'Wozu wird diese Energie benötigt? Für eine Waffe?', 25549),
(117556, 'deDE', '', 'Verstärkung aus Unterstadt im Anmarsch!', 25549),
(117555, 'deDE', '''Armee der Toten'' erweckt einen Schwarm Ghule, die alles in Eurer Umgebung angreifen.', '', 25549),
(117554, 'deDE', '''Todesgriff'' packt ein entferntes Ziel und zieht es zu Euch heran. Kein Gegner kann Eurem eisigen Griff entkommen!', '', 25549),
(117553, 'deDE', 'Die dunkle Macht schadet Gegnern und heilt einen Teil Eurer Gesundheit.', '', 25549),
(117552, 'deDE', 'Wirkt ''Tod und Verfall'', um den Boden unter Euch zu verderben. Alle Gegner in dem Bereich erleiden Schaden und einige Eurer Angriffe treffen mehrere Ziele.', '', 25549),
(117551, 'deDE', '', 'Und wir der Mittelpunkt...', 25549),
(117550, 'deDE', 'Gegen ''Schwärender Stoß'' gefolgt von ''Geißelstoß'' können nur wenige Gegner bestehen.', '', 25549),
(117549, 'deDE', '''Schwärender Stoß'' fügt dem Ziel Schaden und schwärende Wunden zu.', '', 25549),
(117548, 'deDE', '''Ausbruch'' verursacht regelmäßigen Schaden und verbreitet eine virulente Seuche unter Gegnern in der Nähe.', '', 25549),
(117547, 'deDE', 'Ihr solltet immer einen Diener dabei haben.', '', 25549),
(117546, 'deDE', 'Doch Euer stärkster Verbündeter ist der Tod selbst. Mit ''Totenerweckung'' verwandelt Ihr eine Leiche in Euren Ghuldiener.', '', 25549),
(117545, 'deDE', 'Krankheiten schwächen Eure Gegner und mit Nahkampfangriffen streckt Ihr sie nieder.', '', 25549),
(117544, 'deDE', 'Am Ende steht das Nichts...', '', 25549),
(117543, 'deDE', 'Eure Existenz bedeutet gar nichts! Bereitet Euch auf Euren letzten Atemzug vor, Sterbliche!', '', 25549),
(117542, 'deDE', 'Ihr werdet lernen, wo Ihr hingehört, Sterbliche.', '', 25549),
(117541, 'deDE', 'Wie hilflos Ihr Euch fühlen müsst, wenn Ihr seht, wie Eure Welt um Euch herum zerfällt.', '', 25549),
(117540, 'deDE', 'Nein! Die Festung muss fallen!', '', 25549),
(117539, 'deDE', '', 'So dunkel...', 25549),
(117538, 'deDE', '', 'Wertlose Insekten. Ihr werdet noch um Euren Tod betteln!', 25549),
(117537, 'deDE', 'Lasst das Licht Euch durchfließen.', '', 25549),
(117536, 'deDE', 'Seht, wie hell unser inneres Feuer brennt!', '', 25549),
(117535, 'deDE', 'Das Licht wird unsere Feinde vernichten!', '', 25549),
(117534, 'deDE', 'Ich werde zurückkehren.', '', 25549),
(117533, 'deDE', 'Meine Macht schwindet...', '', 25549),
(117532, 'deDE', 'Mein Licht verblasst...', '', 25549),
(117531, 'deDE', 'Wir sind siegreich.', '', 25549),
(117530, 'deDE', 'Das Licht wird fortbestehen.', '', 25549),
(117529, 'deDE', 'Ich verteidige das Licht.', '', 25549),
(117528, 'deDE', 'Ich werde diese Welt reinigen!', '', 25549),
(117527, 'deDE', 'Ich bin die Verkörperung des Lichts!', '', 25549),
(117526, 'deDE', 'Wir kämpfen für das Licht!', '', 25549),
(117525, 'deDE', 'Tod... alter Freund... nicht heute...', '', 25549),
(117524, 'deDE', 'Hggghh... unghhh... Ich werd'' schon wieder.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(117523, 'deDE', 'Es tut nur etwas weh... Ich hole Euch schon wieder ein...', '', 25549),
(117522, 'deDE', 'Der Tod fordert Euer Leben!', '', 25549),
(117521, 'deDE', 'Ihr könnt gegen meine Macht nicht bestehen.', '', 25549),
(117520, 'deDE', 'Die Schatten werden Euch verschlingen.', '', 25549),
(117519, 'deDE', 'Euer Wille wird sich meinem beugen!', '', 25549),
(117518, 'deDE', 'Ergebt Euch dem Wahnsinn!', '', 25549),
(117517, 'deDE', 'Die Schatten leiten mich.', '', 25549),
(117516, 'deDE', '', 'Die Naaru sind mit uns, immer.', 25549),
(117515, 'deDE', '', 'Das Licht scheint auf uns herab!', 25549),
(117514, 'deDE', '', 'A''dal! Verleihe uns Kraft!', 25549),
(117513, 'deDE', 'Zerschmettert unsere Feinde!', '', 25549),
