(117270, 'deDE', 'Die Läuterung trifft alle!', '', 25549),
(117269, 'deDE', 'Spürt die Kraft der Elemente!', '', 25549),
(117268, 'deDE', 'Für die Allianz!', '', 25549),
(117267, 'deDE', '', 'Argh... Das war ein Treffer...', 25549),
(117266, 'deDE', '', 'Argh...!', 25549),
(117265, 'deDE', '', 'Das tut weh... Aber Ihr...', 25549),
(117264, 'deDE', '', 'Mein Greif will endlich kämpfen!', 25549),
(117263, 'deDE', '', 'Schlitz'' sie auf, Mädchen!', 25549),
(117262, 'deDE', '', 'Los, Sturmschnabel!', 25549),
(117261, 'deDE', '', 'Ihr bleibt besser tot.', 25549),
(117260, 'deDE', '', 'Unsere Vorfahren wären stolz.', 25549),
(117259, 'deDE', '', 'Ihr seid hässlich. Und jetzt noch tot.', 25549),
(117258, 'deDE', '', 'Wir machen das!', 25549),
(117257, 'deDE', '', 'Ah, das wird jetzt gut!', 25549),
(117256, 'deDE', '', 'Euch mache ich fertig.', 25549),
(117255, 'deDE', 'Schlagt schnell zu, schlagt hart zu!', '', 25549),
(117254, 'deDE', 'Wir können sie überraschen!', '', 25549),
(117253, 'deDE', 'Das kam überraschend.', '', 25549),
(117252, 'deDE', 'Das ist kein Spaß, geflotschter König beißt ins Gras!', '', 25549),
(117251, 'deDE', 'Da hilft kein Klagen, Nappel hat König geschlagen!', '', 25549),
(117250, 'deDE', 'Der König besiegt, verfiddelt im Staube liegt!', '', 25549),
(117249, 'deDE', 'Große Schlacht, die Knatzel ganz flotschig gemacht!', '', 25549),
(117248, 'deDE', 'Hahaha! Ein verfiddelter Sieg im gronzigen Krieg!', '', 25549),
(117247, 'deDE', 'Knatzel im Eimer, den Sieg nimmt uns keiner!', '', 25549),
(117246, 'deDE', 'Keine Zeit zum Scherzen, denn Nappel kriegt jetzt Schmerzen!', '', 25549),
