(116911, 'deDE', 'Kal''theros maldin.', '', 25549),
(116910, 'deDE', 'Nor''bethos Suramar.', 'Nor''bethos Suramar.', 25549),
(116909, 'deDE', 'Es sind schlimme Zeiten. Seid wachsam.', 'Macht''s gut.', 25549),
(116908, 'deDE', 'Möge Elisande Euch leiten.', '', 25549),
(116907, 'deDE', 'Des Brunnens Segen sei mit Euch.', 'Reist im Sternenlicht.', 25549),
(116906, 'deDE', 'Dies ist unsere Zeit!', 'Unsere Zeit ist gekommen.', 25549),
(116905, 'deDE', 'Die Shal''dorei erheben sich.', 'Die Shal''dorei sind zurückgekehrt.', 25549),
(116904, 'deDE', 'Kal''theros maldin.', 'Kal''theros maldin.', 25549),
(116903, 'deDE', '', 'Eure Welt wird unsss gehören!', 25549),
