INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(116757, 'deDE', 'Unvorstellbar...', '', 25549),
(116756, 'deDE', 'Gegen Gewürm verliere ich nicht!', '', 25549),
(116755, 'deDE', 'Unsere Feinde werden fallen!', '', 25549),
(116754, 'deDE', 'Wir können sie nicht aufhalten!', '', 25549),
(116753, 'deDE', 'Elisande... Ich habe Euch enttäuscht.', '', 25549),
(116747, 'deDE', 'In der Nähe spürt Ihr einen großen Teich mit Leyenergie.', 'In der Nähe spürt Ihr einen großen Teich mit Leyenergie.', 25549),
(116746, 'deDE', 'Hier sind so viele Freunde, mit denen man spielen kann!', 'Hier sind so viele Freunde, mit denen man spielen kann!', 25549),
(116745, 'deDE', 'Ihr fühlt Euch wie zu Hause.', 'Ihr fühlt Euch wie zu Hause.', 25549),
(116744, 'deDE', 'Diese Kristalle sind RIESIG!', 'Diese Kristalle sind RIESIG!', 25549),
(116743, 'deDE', 'Ihr habt das Gefühl, als ob hohe Gebäude über Euch aufragen.', 'Ihr habt das Gefühl, als ob hohe Gebäude über Euch aufragen.', 25549),
(116742, 'deDE', 'Ganz in der Nähe spürt Ihr einen Riss im Gefüge der Magie.', 'Ganz in der Nähe spürt Ihr einen Riss im Gefüge der Magie.', 25549),
(116741, 'deDE', 'Ihr spürt überall um Euch herum Leyenergie.', 'Ihr spürt überall um Euch herum Leyenergie.', 25549),
(116740, 'deDE', 'Hier gibt es so hübsche Kristalle!', 'Hier gibt es so hübsche Kristalle!', 25549),
(116739, 'deDE', 'Ihr verspürt Abscheu und Mitleid für diese Kreaturen.', 'Ihr verspürt Abscheu und Mitleid für diese Kreaturen.', 25549),
(116738, 'deDE', 'In der Nähe hört Ihr einen großen Wasserfall.', 'In der Nähe hört Ihr einen großen Wasserfall.', 25549),
(116737, 'deDE', 'Ihr habt das Bild des Mondes vor Augen.', 'Ihr habt das Bild des Mondes vor Augen.', 25549),
(116736, 'deDE', 'Ihr habt das Gefühl, unter Freunden zu sein.', 'Ihr habt das Gefühl, unter Freunden zu sein.', 25549),
(116735, 'deDE', 'Ihr hört das Knistern eines kleines Feuers.', 'Ihr hört das Knistern eines kleines Feuers.', 25549),
(116734, 'deDE', 'Ihr fühlt, wie der Boden um Euch herum bebt.', 'Ihr fühlt, wie der Boden um Euch herum bebt.', 25549),
(116733, 'deDE', 'Ihr riecht nasskaltes und dunkles Erdreich.', 'Ihr riecht nasskaltes und dunkles Erdreich.', 25549),
(116732, 'deDE', 'Ihr habt ein Bild von Finsternis vor Augen.', 'Ihr habt ein Bild von Finsternis vor Augen.', 25549),
(116731, 'deDE', 'Ihr fragt Euch, ob Geister wirklich freundlich sein können.', 'Ihr fragt Euch, ob Geister wirklich freundlich sein können.', 25549),
(116730, 'deDE', 'Ihr habt ein Bild von elegant umherstolzierenden Kreaturen vor Augen.', 'Ihr habt ein Bild von elegant umherstolzierenden Kreaturen vor Augen.', 25549),
(116729, 'deDE', 'Ihr spürt eine gewisse Sicherheit von oben.', 'Ihr spürt eine gewisse Sicherheit von oben.', 25549),
(116728, 'deDE', 'Ganz schwach nehmt ihr hinunterrinnendes Wasser wahr.', 'Ganz schwach nehmt ihr hinunterrinnendes Wasser wahr.', 25549),
(116727, 'deDE', 'Ihr hört flatternde Federn, stampfende Hufe und kratzende Klauen.', 'Ihr hört flatternde Federn, stampfende Hufe und kratzende Klauen.', 25549),
(116726, 'deDE', 'Ihr riecht den sanften Duft von Blumen in der Sonne.', 'Ihr riecht den sanften Duft von Blumen in der Sonne.', 25549),
(116725, 'deDE', 'Ihr hört raschelnde Blätter im Wind.', 'Ihr hört raschelnde Blätter im Wind.', 25549),
(116724, 'deDE', 'Ihr habt das Gefühl, Euch über allem zu befinden.', 'Ihr habt das Gefühl, Euch über allem zu befinden.', 25549),
(116723, 'deDE', 'Ihr spürt die Anwesenheit von Kreaturen, die vor langer Zeit dazu verflucht wurden, eine neue Form anzunehmen.', 'Ihr spürt die Anwesenheit von Kreaturen, die vor langer Zeit dazu verflucht wurden, eine neue Form anzunehmen.', 25549),
(116722, 'deDE', 'In der Nähe befinden sich uralte Ruinen, doch Ihr spürt deutlich ein Gefühl von Verlassenheit.', 'In der Nähe befinden sich uralte Ruinen, doch Ihr spürt deutlich ein Gefühl von Verlassenheit.', 25549),
(116721, 'deDE', 'Ihr spürt, dass Timirgos von irgendeinem hellen Licht hypnotisiert ist.', 'Ihr spürt, dass Timirgos von irgendeinem hellen Licht hypnotisiert ist.', 25549),
(116720, 'deDE', 'Ihr hört einen leisen Wasserstrudel.', 'Ihr hört einen leisen Wasserstrudel.', 25549),
(116719, 'deDE', 'Endlich verspüre ich wieder Frieden.', '', 25549),
(116718, 'deDE', 'Sterbt, Verräter des Dämonenpakts!', '', 25549),
(116717, 'deDE', '', 'Kommt, Brüder, die Brennende Legion greift an!', 25549),
(116716, 'deDE', '', 'Moment, Ihr seid ja gar kein Dämon!', 25549),
(116715, 'deDE', 'Sagt Valeera, wir wachen über sie.', '', 25549),
(116714, 'deDE', 'Ihr wagt es, meine Ruhe zu stören, Dämon?!', '', 25549),
(116713, 'deDE', 'Geht zu Erzdruide Großhuf und berichtet ihm, was geschehen ist. Ich werde diese Überreste studieren.', '', 25549),
(116712, 'deDE', 'Das... kann nicht sein! Zerstört den bösen Setzling, bevor er entkommt!', '', 25549),
(116711, 'deDE', 'Habt Ihr eine Probe des Alptraums?', 'Habt Ihr eine Probe des Alptraums?', 25549),
(116710, 'deDE', 'Die Shal''dorei wurden ausgewählt.', 'Wir sind... die Auserwählten...', 25549),
(116709, 'deDE', 'Anath''ashar!', 'Anath''ashar!', 25549),
(116708, 'deDE', 'Sterbt, Fremdling!', 'Niemand fordert uns ungestraft heraus!', 25549),
(116707, 'deDE', 'Die Shal''dorei werden herrschen!', 'Wir sind auserwählt zu herrschen!', 25549),
(116706, 'deDE', 'Abschaum wie Ihr sollte einfach gehorchen.', 'Ich werde Euch beseitigen, Gewürm!', 25549),
(116705, 'deDE', 'Euer Zeitalter ist zu Ende!', 'Das Zeitalter der Shal''dorei ist gekommen!', 25549),
(116704, 'deDE', 'Unsere Magie wird Euch zerbrechen!', 'Unsere Magie wird Euch zerbrechen!', 25549),
(116703, 'deDE', 'Euer Tod ist vorherbestimmt!', 'Euer Schicksal ist besiegelt!', 25549),
(116702, 'deDE', 'Anath''ashar!', 'Anath''ashar!', 25549),
(116701, 'deDE', 'Niemand fordert uns ungestraft heraus!', 'Keine Gnade gegenüber Fremdlingen!', 25549),
(116700, 'deDE', 'Ihr werdet Euch fügen!', 'Die Shal''dorei werden herrschen!', 25549),
(116699, 'deDE', 'Niederer Abschaum!', 'Abschaum wie Ihr sollte einfach gehorchen.', 25549),
(116698, 'deDE', 'Euer Stern sinkt!', 'Euer Stern sinkt!', 25549),
(116697, 'deDE', 'Erzittert vor unserer Stärke!', 'Erzittert vor unserer Stärke!', 25549),
(116696, 'deDE', 'Euer Tod ist gewiss!', 'Euer Tod ist vorherbestimmt!', 25549),
(116695, 'deDE', 'Anath''ashar!', 'Anath''ashar!', 25549),
