UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ich kann Euch keine Siegel des unausweichlichen Schicksals geben. Vielleicht zu einem späteren Zeitpunkt, wenn Ihr mächtig genug seid, um sie zu verwenden oder wenn genug Zeit vergangen ist.', `VerifiedBuild`=25549 WHERE (`ID`=93994 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='<Laanda mustert Euch von Kopf bis Fuß und flüstert dann nervös.>$B$BWas macht Ihr da, $C? Wenn Ihr Eure Garnisonsmission unerkannt ausführen wollt, BRAUCHT IHR EINE VERKLEIDUNG.$B$BKommt zu mir zurück, wenn Ihr eine Sargereiverkleidung angelegt habt.$B$BNotfalls müsst Ihr einen Sargerei in der Nähe töten und seine Kleidung an Euch nehmen. Ihr dürft mich keinesfalls auffliegen lassen.', `VerifiedBuild`=25549 WHERE (`ID`=93993 AND `locale`='deDE');
