UPDATE `broadcast_text_locale` SET `MaleText_lang`='Jene, die sich wegen ihrer eigenen, selbstsüchtigen Ziele in die Zeitlinien einmischen, sind meist gefährlich.\n\nAus diesem Grund schloss ich mich den Wächtern, den standhaften Verteidigern der Zeitwanderer, an.\n\nWir schützen die Behüter und Weber bei ihren Aufgaben.', `VerifiedBuild`=25549 WHERE (`ID`=75796 AND `locale`='deDE');
