UPDATE `broadcast_text_locale` SET `MaleText_lang`='Wenn Ihr Euch nicht selbst prügelt, könnt Ihr''s vergess''n. Ihr müsst den Kampf schon "hautnah" erleben.\n\nGeht und sprecht mit einer der Wachen, um Euch für den Kampf anzustellen. Dann gilt die Wette.', `VerifiedBuild`=25549 WHERE (`ID`=69979 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Wer seid Ihr denn?\n\nHier gibt''s keine krummen Geschäfte. Nur ein bisschen Blutsport unter Freunden, ohne jegliche finanzielle Beteiligung. Unsere Weste ist lupenrein.', `VerifiedBuild`=25549 WHERE (`ID`=69978 AND `locale`='deDE');
