UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Wenn Ihr dies hier lest, bin ich entweder tot oder auf dem Halbhügelmarkt.$B$BHoffentlich habe ich nur meinen Posten verlassen, um einen schönen Krug Bier im Ort zu trinken. Vielleicht solltet Ihr zur Sicherheit mal nachsehen.$B$BWenn ich aber in der Tat meinen Auftrag vermasselt habe, richtet bitte meiner Familie in Zhus Wacht aus, dass ich sie liebe.\n\n- Sho', `VerifiedBuild`=25549 WHERE (`ID`=57545 AND `locale`='deDE');
