UPDATE `broadcast_text_locale` SET `MaleText_lang`='Alles außerhalb des Kreises um Euch wird Euch nicht sehen können, aber die Illusion wird aufgehoben, sobald Ihr angreift oder Schaden erleidet.\n$bIch empfehle Euch, verborgen zu bleiben, bis ich etwas anderes sage. Diese Dämonen sind zu mächtig, um sie direkt und mit voller Gewalt anzugreifen.', `VerifiedBuild`=25549 WHERE (`ID`=54226 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=54225 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Die Schatten werden uns gut verbergen.\n$bDiese ''Schattenhülle'' tarnt mich und ich kann ihre Magie an Euch weitergeben.\n$bSie wird uns nicht unsichtbar machen, doch so lange wir uns in ausreichender Entfernung von unseren Feinden halten, werden wir versteckt sein.', `VerifiedBuild`=25549 WHERE (`ID`=54224 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=54223 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=54222 AND `locale`='deDE');
