UPDATE `broadcast_text_locale` SET `MaleText_lang`='Haltet bei Theramores Schmiede Ausschau nach dem Zwerg Kerik.\n\nEr ist ein Trunkenbold und ein wenig zu großzügig in Sachen Sprengstoff, aber eigentlich ist er ganz nett und kennt sich mit Minen aus.', `FemaleText_lang`='Haltet bei Theramores Schmiede Ausschau nach dem Zwerg Kerik.\n\nEr ist ein Trunkenbold und ein wenig zu großzügig in Sachen Sprengstoff, aber eigentlich ist er ganz nett und kennt sich mit Minen aus.', `VerifiedBuild`=25549 WHERE (`ID`=52074 AND `locale`='deDE');
