UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ich weiß, dass einer von diesen Wollbusch-Zwergen, die gerade zu Besuch sind, ein Archäologe ist.\n\nIch glaube, es ist die Ehefrau, Faena. Sie sind beide irgendwie Forscher. Haltet im Gasthaus nach ihnen Ausschau.', `FemaleText_lang`='Ich weiß, dass einer von diesen Wollbusch-Zwergen, die gerade zu Besuch sind, ein Archäologe ist.\n\nIch glaube, es ist die Ehefrau, Faena. Sie sind beide irgendwie Forscher. Haltet im Gasthaus nach ihnen Ausschau.', `VerifiedBuild`=25549 WHERE (`ID`=52060 AND `locale`='deDE');
