UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ich war früher in der Forscherliga, wisst Ihr.\n\\Aber dann ist mir aufgefallen, dass das Einzige, wonach ich wirklich gerne gesucht habe, EDELSTEINE waren.\n\nGroße, glitzernde, bunte, wertvolle Edelsteine... Oh, wie ich euch liebe!', `VerifiedBuild`=25549 WHERE (`ID`=51960 AND `locale`='deDE');
