UPDATE `broadcast_text_locale` SET `MaleText_lang`='Auf meinem Flug von Darnassus, um Malfurion Sturmgrimm aufzusuchen, traf ich auf diese verletzten Flüchtlinge aus den Ruinen von Auberdine.$B$BSie kämpfen für die gute Sache und ich helfe ihnen zu heilen, doch ihre Verletzungen sind zahlreich und es wird seine Zeit dauern.$B$BIch vertraue darauf, dass auch Ihr bereit seid, ihnen zu Hilfe zu kommen.', `VerifiedBuild`=25549 WHERE (`ID`=33175 AND `locale`='deDE');
