UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ich weiß nicht, wovon Ihr sprecht, Drache... aber ich werde mich von diesem anmaßenden Gehabe nicht einschüchtern lassen. Ich gehe, wenn es mir passt!', `VerifiedBuild`=25549 WHERE (`ID`=14299 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Eine dunkle Macht will Euch zu ihrem Werkzeug machen, Medivh! Wenn Ihr bleibt, erwartet Euch nur Finsternis. Beeilt Euch, uns bleibt nicht viel Zeit!', `VerifiedBuild`=25549 WHERE (`ID`=14298 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=14297 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ihr seid mit Euren arkanen Stümpereien zu weit gegangen, Medivh. Ihr habt die Aufmerksamkeit von Mächten jenseits Eurer Vorstellungskraft geweckt. Ihr müsst Karazhan endlich ruhen lassen!', `VerifiedBuild`=25549 WHERE (`ID`=14296 AND `locale`='deDE');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ihr habt meine volle Aufmerksamkeit, Drache. Ihr werdet feststellen, dass ich nicht so leicht zu ängstigen bin wie die Dorfbewohner.', `VerifiedBuild`=25549 WHERE (`ID`=14295 AND `locale`='deDE');
