UPDATE `broadcast_text_locale` SET `MaleText_lang`='Tresa Bergweh hat jede Menge Unwetter erlebt, aber dank ihrer Kenntnisse der Überlebenskunstfertigkeiten hat sie alle unbeschadet überstanden. \n\nSie ist im Militärviertel, südlich des Stadttors von Eisenschmiede, zu finden, wenn Ihr mit ihr sprechen wollt.', `FemaleText_lang`='Tresa Bergweh hat jede Menge Unwetter erlebt, aber dank ihrer Kenntnisse der Überlebenskunstfertigkeiten hat sie alle unbeschadet überstanden. \n\nSie ist im Militärviertel, südlich des Stadttors von Eisenschmiede, zu finden, wenn Ihr mit ihr sprechen wollt.', `VerifiedBuild`=25549 WHERE (`ID`=5143 AND `locale`='deDE');
