UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ah, Braenna Kieselbruch. Sie hat magische Hände. Braenna muss man konsultieren, wenn es um Fragen der Priesterschaft geht. \n\nIhr müsst vom Stadttor von Eisenschmiede aus nach Norden ziehen, zur Halle der Mysterien. Da müsste sie zu finden sein.', `FemaleText_lang`='Ah, Braenna Kieselbruch. Sie hat magische Hände. Braenna muss man konsultieren, wenn es um Fragen der Priesterschaft geht. \n\nIhr müsst vom Stadttor von Eisenschmiede aus nach Norden ziehen, zur Halle der Mysterien. Da müsste sie zu finden sein.', `VerifiedBuild`=25549 WHERE (`ID`=5101 AND `locale`='deDE');
