UPDATE `broadcast_text_locale` SET `MaleText_lang`='Bink, die kleine Hexenbraut drüben in der Halle der Mysterien, kann Euch wahrscheinlich in allen magischen Belangen weiterhelfen. \n\nDie Halle der Mysterien liegt gleich nördlich des Stadttors von Eisenschmiede.', `FemaleText_lang`='Bink, die kleine Hexenbraut drüben in der Halle der Mysterien, kann Euch wahrscheinlich in allen magischen Belangen weiterhelfen. \n\nDie Halle der Mysterien liegt gleich nördlich des Stadttors von Eisenschmiede.', `VerifiedBuild`=25549 WHERE (`ID`=5098 AND `locale`='deDE');
